def find_first_tag_text(url=None, tag='p', html=None, timeout=10, user_agent='python'):
    """
    Find the first occurrence of an HTML tag on a web page (or in provided HTML) and return its text content.
    Attempts to use an external `html_tag_finder` library if available; otherwise uses a built-in parser.

    Parameters:
    - url: URL of the web page to fetch (string). Either url or html must be provided.
    - tag: tag name to find (e.g., 'p', 'h1', 'div'). Case-insensitive.
    - html: optional raw HTML string; if provided, fetching from url is skipped.
    - timeout: network timeout in seconds (used when fetching url).
    - user_agent: user-agent string for the HTTP request.

    Returns:
    - A string with the inner text of the first found tag (entities decoded, stripped), or None if not found.

    Examples:
    - find_first_tag_text(url='https://example.com', tag='h1')
    - find_first_tag_text(html='<div><p>Hello <b>world</b></p></div>', tag='p')
    """
    # Try to use html_tag_finder if present
    try:
        import html_tag_finder  # may fail; if present, try a few common APIs
    except Exception:
        html_tag_finder = None

    if html_tag_finder is not None:
        # try some plausible APIs, fall back to builtin parser if unknown
        try:
            if hasattr(html_tag_finder, 'find_first_tag_text'):
                # hypothetical direct API
                if html is not None:
                    return html_tag_finder.find_first_tag_text(html=html, tag=tag)
                else:
                    return html_tag_finder.find_first_tag_text(url=url, tag=tag, timeout=timeout)
            if hasattr(html_tag_finder, 'find'):
                # hypothetical .find(url, tag) -> returns element or text
                if html is not None:
                    res = html_tag_finder.find(html, tag=tag)
                else:
                    res = html_tag_finder.find(url, tag=tag, timeout=timeout)
                # try to coerce to text
                if res is None:
                    return None
                if isinstance(res, str):
                    return res.strip()
                if hasattr(res, 'text'):
                    return str(res.text).strip()
                return str(res).strip()
        except Exception:
            # if the library exists but API doesn't match or fails, fall back to builtin parser
            pass

    # Built-in fallback implementation using standard library
    from html.parser import HTMLParser
    from html import unescape
    import urllib.request

    if html is None:
        if not url:
            raise ValueError("Either url or html must be provided.")
        req = urllib.request.Request(url, headers={'User-Agent': user_agent})
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            # try to detect encoding from headers; default to utf-8
            content_type = resp.headers.get_content_charset()
            raw = resp.read()
            try:
                html = raw.decode(content_type or 'utf-8', errors='replace')
            except Exception:
                html = raw.decode('utf-8', errors='replace')

    target = (tag or '').lower().strip()
    if not target:
        raise ValueError("tag must be a non-empty string")

    class _StopParsing(Exception):
        pass

    class _FirstTagParser(HTMLParser):
        def __init__(self, target_tag):
            super().__init__(convert_charrefs=True)  # convert_charrefs makes data already unescaped for common cases
            self.target = target_tag
            self.capturing = False
            self.depth = 0
            self.text_parts = []
            self.found = False
            self.ignore_stack = []  # track script/style nesting when capturing

        def handle_starttag(self, tag, attrs):
            t = tag.lower()
            if not self.found:
                if t == self.target:
                    self.capturing = True
                    self.depth = 1
                    self.found = True
                    # do not raise here; we want to capture contents
                # else: not found yet
            else:
                # already found and capturing: track nested tags
                if self.capturing:
                    self.depth += 1

            # if capturing and encountering script/style, push to ignore stack
            if self.capturing and t in ('script', 'style'):
                self.ignore_stack.append(t)

        def handle_endtag(self, tag):
            t = tag.lower()
            if self.capturing:
                # handle script/style ignore stack
                if len(self.ignore_stack) > 0 and t == self.ignore_stack[-1]:
                    self.ignore_stack.pop()
                    return

                if t == self.target:
                    self.depth -= 1
                    if self.depth <= 0:
                        self.capturing = False
                        # stop parsing early
                        raise _StopParsing()
                else:
                    # general nested end tag reduces depth if depth>1
                    if self.depth > 0:
                        self.depth -= 1

        def handle_data(self, data):
            if self.capturing and not self.ignore_stack:
                # accumulate raw data; convert_charrefs=True already handled numeric and named char refs
                self.text_parts.append(data)

        def handle_entityref(self, name):
            # only reached if convert_charrefs=False; but convert_charrefs=True so likely unused
            if self.capturing and not self.ignore_stack:
                self.text_parts.append('&%s;' % name)

        def handle_charref(self, name):
            if self.capturing and not self.ignore_stack:
                self.text_parts.append('&#%s;' % name)

    parser = _FirstTagParser(target)
    try:
        parser.feed(html)
        parser.close()
    except _StopParsing:
        # expected early termination
        pass

    if not parser.found:
        return None

    text = ''.join(parser.text_parts)
    # ensure entities decode (in case convert_charrefs didn't handle some)
    text = unescape(text)
    # collapse whitespace similar to browser rendering
    text = ' '.join(text.split()).strip()
    return text if text != '' else ''


