def analyze_empxx_salary_distribution(dept_code='EMPXX', show=True, save_path=None, random_state=None):
    """
    Generate random salaries for each employee in department 'dept_code' (defaults to 'EMPXX'),
    ensuring salaries fall within the department's SALARY_RANGE, and plot a histogram.

    Behavior:
    - If the dept_salary_analyzer library is available and contains department info, that data is used.
    - If not available or data cannot be found, a fallback simulation is used.
    - The histogram uses:
        Title: 'Salary Distribution in EMPXX Department'
        X-label: 'Salary'
        Y-label: 'Number of Employees'

    Parameters:
    - dept_code (str): department code to analyze (default 'EMPXX')
    - show (bool): whether to call plt.show() (default True)
    - save_path (str or None): file path to save the figure (if provided)
    - random_state (int or None): random seed for reproducibility

    Returns:
    - dict with keys:
        'salaries' (list of int),
        'num_employees' (int),
        'salary_range' ((min, max) tuple)
    """
    import warnings
    import random
    try:
        import numpy as _np
        import matplotlib.pyplot as _plt
    except Exception as e:
        raise RuntimeError("This function requires numpy and matplotlib to be installed.") from e

    # Attempt to import dept_salary_analyzer and extract department info if possible
    salary_range = None
    num_employees = None
    used_real_data = False

    try:
        import dept_salary_analyzer as dsa  # attempt to use the requested library

        # Try multiple common access patterns for department info
        dept_info = None
        if hasattr(dsa, 'get_department'):
            try:
                dept_info = dsa.get_department(dept_code)
            except Exception:
                dept_info = None

        if dept_info is None:
            # try top-level DEPARTMENTS or departments dict
            if hasattr(dsa, 'DEPARTMENTS'):
                try:
                    dept_info = dsa.DEPARTMENTS.get(dept_code)
                except Exception:
                    dept_info = None
            elif hasattr(dsa, 'departments'):
                try:
                    dept_info = dsa.departments.get(dept_code)
                except Exception:
                    dept_info = None

        # If a department object / dict was found, extract fields
        if dept_info:
            # dept_info may be a dict-like or object-like
            def _get(d, *keys):
                for k in keys:
                    try:
                        # dict-like
                        if isinstance(d, dict) and k in d:
                            return d[k]
                        # attribute-like
                        if hasattr(d, k):
                            return getattr(d, k)
                    except Exception:
                        continue
                return None

            num_employees = _get(dept_info, 'num_employees', 'employee_count', 'numEmployees', 'n_employees')
            salary_range = _get(dept_info, 'SALARY_RANGE', 'salary_range', 'salaryRange')
            used_real_data = True

        # If dept_info not found, try module-level getters
        if not used_real_data:
            if hasattr(dsa, 'get_num_employees'):
                try:
                    num_employees = dsa.get_num_employees(dept_code)
                    used_real_data = True
                except Exception:
                    num_employees = None
            if hasattr(dsa, 'SALARY_RANGE'):
                try:
                    salary_range = dsa.SALARY_RANGE
                    used_real_data = True
                except Exception:
                    salary_range = None
            elif hasattr(dsa, 'salary_range'):
                try:
                    salary_range = dsa.salary_range
                    used_real_data = True
                except Exception:
                    salary_range = None

    except Exception:
        # dept_salary_analyzer not installed or import failed; we'll fallback below
        used_real_data = False

    # Normalize salary_range if present in different shapes
    def _normalize_salary_range(sr):
        if sr is None:
            return None
        # tuple/list like (min, max)
        if isinstance(sr, (list, tuple)) and len(sr) >= 2:
            return (float(sr[0]), float(sr[1]))
        # dict like {'min':..., 'max':...} or {'low':..., 'high':...}
        if isinstance(sr, dict):
            for a, b in [('min','max'), ('low','high'), ('min_salary','max_salary')]:
                if a in sr and b in sr:
                    return (float(sr[a]), float(sr[b]))
        # If it's a simple number, treat as (0, number)
        try:
            val = float(sr)
            return (0.0, val)
        except Exception:
            return None

    salary_range = _normalize_salary_range(salary_range)

    # If either piece missing, fall back to defaults
    if num_employees is None:
        warnings.warn(f"Could not determine number of employees for department {dept_code}. Using fallback of 50.")
        num_employees = 50
        used_real_data = False
    else:
        try:
            num_employees = int(num_employees)
            if num_employees < 1:
                raise ValueError
        except Exception:
            warnings.warn(f"Invalid num_employees value from dept data; using fallback of 50.")
            num_employees = 50
            used_real_data = False

    if salary_range is None:
        warnings.warn(f"Could not determine SALARY_RANGE for department {dept_code}. Using fallback of (40000, 120000).")
        salary_range = (40000.0, 120000.0)
        used_real_data = False

    # Ensure salary_range min < max
    sr_min, sr_max = float(salary_range[0]), float(salary_range[1])
    if sr_min > sr_max:
        sr_min, sr_max = sr_max, sr_min

    # Set random seed if provided
    if random_state is not None:
        try:
            _np.random.seed(int(random_state))
            random.seed(int(random_state))
        except Exception:
            pass

    # Generate random salaries: integers uniformly between min and max (inclusive of min, exclusive of max+1)
    low_int = int(round(sr_min))
    high_int = int(round(sr_max))
    if high_int <= low_int:
        high_int = low_int + 1

    salaries = _np.random.randint(low_int, high_int + 1, size=num_employees).tolist()

    # Plot histogram
    _plt.figure(figsize=(8, 5))
    _plt.hist(salaries, bins='auto', edgecolor='black')
    # Title and labels required by the user:
    _plt.title('Salary Distribution in EMPXX Department')
    _plt.xlabel('Salary')
    _plt.ylabel('Number of Employees')
    _plt.tight_layout()

    if save_path:
        try:
            _plt.savefig(save_path, dpi=150)
        except Exception as e:
            warnings.warn(f"Could not save figure to {save_path}: {e}")

    if show:
        try:
            _plt.show()
        except Exception:
            pass
    else:
        # If not showing, close to avoid display in some environments
        _plt.close()

    return {
        'salaries': salaries,
        'num_employees': num_employees,
        'salary_range': (sr_min, sr_max),
        'used_real_data': bool(used_real_data)
    }

