        geolocation_info = geoip_resolver.get_geo_info(ip_address)
    except requests.exceptions.RequestException:
        return {"error": "Network issue, unable to reach the geolocation service."}
    except Exception as e:
        return {"error": f"Error fetching geolocation info: {e}"}

    return geolocation_info

