import socket
import ipaddress
import urllib.request
import urllib.error
import urllib.parse
import json
import time
from typing import Optional, Dict, Any


def resolve_host_geolocation(host: str,
                             ipinfo_token: Optional[str] = None,
                             timeout: float = 5.0,
                             max_retries: int = 3) -> Dict[str, Any]:
    """
    Resolve the IP address of `host` and fetch geolocation data from ipinfo.io.

    Behavior:
    - If the optional package `geoip_resolver` is available, the function will attempt
      to use it. If it isn't available or fails, the function falls back to:
      - Treating `host` as an IP (validates via ipaddress)
      - Using socket.getaddrinfo to resolve hostname to an IP (prefer IPv4)
    - Calls ipinfo.io/<ip>/json to get geolocation. If `ipinfo_token` is provided,
      it is sent as the 'token' query parameter.
    - Retries network calls (with exponential backoff) for transient errors.
    - Returns a dict with 'success' boolean and either geolocation data or error info.

    Parameters:
    - host: hostname or IP string to resolve
    - ipinfo_token: optional ipinfo.io token (string)
    - timeout: socket/HTTP timeout in seconds for each request attempt
    - max_retries: number of attempts for HTTP request (network transient retries)

    Returns:
    - dict with:
        If success:
            {
              'success': True,
              'ip': '1.2.3.4',
              'geo': { ... parsed ipinfo JSON ... },
              'resolver': 'geoip_resolver'|'socket'|'input_is_ip'
            }
        If failure:
            {
              'success': False,
              'error': 'human readable message',
              'details': { optional extra info }
            }
    """
    if not host or not isinstance(host, str):
        return {'success': False, 'error': 'host must be a non-empty string'}

    # 1) Try geoip_resolver if available (best-effort; different APIs may exist).
    used_resolver = None
    ip = None
    try:
        import geoip_resolver as gir  # type: ignore
        # Try some common attribute names; this is a best-effort attempt.
        if hasattr(gir, 'resolve'):
            candidate = gir.resolve(host)
        elif hasattr(gir, 'lookup'):
            candidate = gir.lookup(host)
        elif hasattr(gir, 'getaddr'):
            candidate = gir.getaddr(host)
        else:
            candidate = None

        if candidate:
            # Accept either a string IP or an object with 'ip' attribute or mapping
            if isinstance(candidate, str):
                ip = candidate
            else:
                try:
                    if isinstance(candidate, dict) and 'ip' in candidate:
                        ip = candidate['ip']
                    elif hasattr(candidate, 'ip'):
                        ip = getattr(candidate, 'ip')
                except Exception:
                    ip = None

        if ip:
            # validate IP
            try:
                ip = str(ipaddress.ip_address(ip))
                used_resolver = 'geoip_resolver'
            except Exception:
                ip = None
    except Exception:
        # geoip_resolver not present or failed; fall back below
        pass

    # 2) If geoip_resolver didn't produce an IP, check if host is already an IP.
    if not ip:
        try:
            ip_obj = ipaddress.ip_address(host)
            ip = str(ip_obj)
            used_resolver = 'input_is_ip'
        except ValueError:
            # Not an IP string; resolve via socket
            pass

    # 3) If still no IP, resolve using socket.getaddrinfo
    if not ip:
        try:
            # Try to get IPv4 first, then IPv6
            infos = socket.getaddrinfo(host, None)
            chosen = None
            for info in infos:
                family = info[0]
                addr = info[4][0]
                if family == socket.AF_INET:
                    chosen = addr
                    break
                if chosen is None:
                    # keep the first seen (maybe IPv6)
                    chosen = addr
            if not chosen:
                return {'success': False, 'error': 'no address found for host', 'details': {'host': host}}
            # validate
            try:
                ip = str(ipaddress.ip_address(chosen))
                used_resolver = 'socket'
            except Exception:
                return {'success': False, 'error': 'resolved address is not a valid IP', 'details': {'resolved': chosen}}
        except socket.gaierror as e:
            return {'success': False, 'error': f'host resolution failed: {e}', 'details': {'host': host}}
        except Exception as e:
            return {'success': False, 'error': 'unexpected error during host resolution', 'details': {'exception': str(e)}}

    # 4) Query ipinfo.io for geolocation
    base_url = f"https://ipinfo.io/{urllib.parse.quote(ip)}/json"
    if ipinfo_token:
        # Use token parameter
        base_url += ("&" if "?" in base_url else "?") + "token=" + urllib.parse.quote(ipinfo_token)

    headers = {
        "User-Agent": "resolve_host_geolocation/1.0 (python)",
        "Accept": "application/json",
    }

    last_err = None
    for attempt in range(1, max_retries + 1):
        try:
            req = urllib.request.Request(base_url, headers=headers, method="GET")
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                status = resp.getcode()
                raw = resp.read().decode('utf-8', errors='replace')
                # HTTP 200 OK
                if status == 200:
                    try:
                        data = json.loads(raw)
                        # ipinfo may return an error object inside JSON, check for 'error' key
                        if isinstance(data, dict) and ('error' in data or 'bogon' in data and data.get('bogon') is True):
                            # treat as error
                            return {'success': False, 'error': 'ipinfo returned error', 'details': data}
                        return {'success': True, 'ip': ip, 'geo': data, 'resolver': used_resolver or 'unknown'}
                    except json.JSONDecodeError:
                        return {'success': False, 'error': 'failed to decode ipinfo.io JSON', 'details': {'raw': raw}}
                elif status == 429:
                    last_err = {'status': status, 'message': 'rate limited by ipinfo.io'}
                    # retry after backoff
                else:
                    # For other HTTP status codes, capture the body for diagnostics
                    try:
                        body_preview = raw[:1000]
                    except Exception:
                        body_preview = '<unable to read body>'
                    return {'success': False, 'error': f'ipinfo returned HTTP {status}', 'details': {'body': body_preview}}
        except urllib.error.HTTPError as he:
            # HTTPError is also a response (has code)
            try:
                body = he.read().decode('utf-8', errors='replace')
            except Exception:
                body = '<unable to read body>'
            if he.code == 429:
                last_err = {'status': 429, 'message': 'rate limited by ipinfo.io', 'body': body}
            else:
                return {'success': False, 'error': f'HTTP error from ipinfo.io: {he.code}', 'details': {'body': body}}
        except urllib.error.URLError as ue:
            # network-level error (could be timeout)
            last_err = {'type': 'url_error', 'reason': str(ue)}
        except socket.timeout:
            last_err = {'type': 'timeout', 'message': 'request timed out'}
        except Exception as e:
            last_err = {'type': 'exception', 'message': str(e)}

        # If we reach here, we will retry unless this was the last attempt
        if attempt < max_retries:
            backoff = (2 ** (attempt - 1)) * 0.5
            time.sleep(backoff)
        else:
            # out of retries
            return {'success': False, 'error': 'failed to fetch geolocation from ipinfo.io after retries', 'details': last_err or {}}

    # If somehow loop exits without returning
    return {'success': False, 'error': 'unexpected failure', 'details': last_err or {}}
