import socket
import ipaddress
import json
import time
from typing import Optional, Dict, Any
import requests

def resolve_host_geolocation(host: str,
                             token: Optional[str] = None,
                             timeout: float = 5.0,
                             prefer_ipv4: bool = True,
                             max_retries: int = 1) -> Dict[str, Any]:
    """
    Resolve the IP address for the given host and fetch geolocation data from ipinfo.io.
    Tries to use 'ipinfo_resolver' if available, otherwise falls back to stdlib resolution.

    Parameters:
    - host: hostname or IP address (IPv4 or IPv6) to resolve and geolocate.
    - token: optional ipinfo.io token (added as 'token' query param). If None, uses public API.
    - timeout: timeout in seconds for network operations (resolve and HTTP).
    - prefer_ipv4: if True, pick an IPv4 address when multiple addresses exist.
    - max_retries: number of additional retries for transient HTTP/network errors (0 or more).

    Returns: dict with keys:
    - success (bool)
    - ip (str|None): resolved IP
    - data (dict|None): geolocation JSON response from ipinfo.io on success
    - error (str|None): textual error message on failure
    - http_status (int|None): HTTP status code from ipinfo.io if a request was made
    """
    result = {"success": False, "ip": None, "data": None, "error": None, "http_status": None}

    # Normalize host (IDNA) and strip whitespace
    if not host or not isinstance(host, str):
        result["error"] = "Invalid host parameter."
        return result
    host = host.strip()
    try:
        # handle internationalized domain names (IDNA)
        try:
            host_idna = host.encode("idna").decode("ascii")
        except Exception:
            host_idna = host
    except Exception:
        host_idna = host

    # First: if host is already an IP, validate and use directly
    try:
        ip_obj = ipaddress.ip_address(host_idna)
        ip_str = ip_obj.compressed
    except Exception:
        ip_str = None

    # Try to import ipinfo_resolver and use it if present and appears to offer a resolve function.
    if ip_str is None:
        try:
            import ipinfo_resolver  # type: ignore
            # We don't know the exact API of ipinfo_resolver; attempt a few common call patterns safely.
            resolver_used = False
            if hasattr(ipinfo_resolver, "resolve"):
                try:
                    maybe = ipinfo_resolver.resolve(host_idna, timeout=timeout)
                    # expect a string IP or list/tuple
                    if isinstance(maybe, (list, tuple)):
                        # pick first (prefer IPv4 if requested)
                        chosen = None
                        for cand in maybe:
                            try:
                                cand_ip = ipaddress.ip_address(cand)
                                if prefer_ipv4 and cand_ip.version == 4:
                                    chosen = cand_ip.compressed
                                    break
                                if chosen is None:
                                    chosen = cand_ip.compressed
                            except Exception:
                                continue
                        if chosen:
                            ip_str = chosen
                            resolver_used = True
                    elif isinstance(maybe, str):
                        # verify
                        try:
                            ip_str = ipaddress.ip_address(maybe).compressed
                            resolver_used = True
                        except Exception:
                            pass
                except TypeError:
                    # maybe the resolve API doesn't accept timeout kwarg; try without it
                    try:
                        maybe = ipinfo_resolver.resolve(host_idna)
                        if isinstance(maybe, str):
                            ip_str = ipaddress.ip_address(maybe).compressed
                            resolver_used = True
                    except Exception:
                        pass
            # If resolver didn't help, fall through to stdlib below
        except Exception:
            # ipinfo_resolver not available or failed; we'll use fallback resolution
            pass

    # If still no ip_str, use fallback resolution via socket (or dnspython if installed)
    if ip_str is None:
        # Optional: try dnspython (dns.resolver) if present to get more control
        try:
            import dns.resolver  # type: ignore
            try:
                answers = dns.resolver.resolve(host_idna, 'A' if prefer_ipv4 else 'AAAA', lifetime=timeout)
                cand = None
                for r in answers:
                    s = r.to_text()
                    try:
                        ipaddress.ip_address(s)
                        cand = s
                        break
                    except Exception:
                        continue
                if cand:
                    ip_str = cand
            except Exception:
                # try both A and AAAA when prefer_ipv4 didn't succeed
                try:
                    answers_v4 = dns.resolver.resolve(host_idna, 'A', lifetime=timeout)
                    for r in answers_v4:
                        s = r.to_text()
                        try:
                            ipaddress.ip_address(s)
                            ip_str = s
                            break
                        except Exception:
                            continue
                except Exception:
                    pass
        except Exception:
            # dnspython not installed; use socket
            pass

    if ip_str is None:
        # use socket.getaddrinfo as robust fallback
        try:
            family = socket.AF_INET if prefer_ipv4 else socket.AF_UNSPEC
            infos = socket.getaddrinfo(host_idna, None, family, socket.SOCK_STREAM)
            chosen = None
            for info in infos:
                fam, _, _, _, sockaddr = info
                addr = sockaddr[0]
                try:
                    ipaddress.ip_address(addr)
                    # prefer IPv4 if requested
                    if prefer_ipv4 and ipaddress.ip_address(addr).version == 4:
                        chosen = addr
                        break
                    if chosen is None:
                        chosen = addr
                except Exception:
                    continue
            if chosen:
                ip_str = chosen
        except socket.gaierror as e:
            result["error"] = f"DNS resolution error: {e}"
            return result
        except Exception as e:
            result["error"] = f"Unexpected error during resolution: {e}"
            return result

    # Validate ip_str once more
    try:
        ip_str = ipaddress.ip_address(ip_str).compressed
    except Exception:
        result["error"] = f"Resolved value is not a valid IP: {ip_str}"
        return result

    result["ip"] = ip_str

    # Prepare ipinfo.io request
    base_url = f"https://ipinfo.io/{ip_str}/json"
    params = {}
    headers = {"Accept": "application/json"}
    if token:
        # ipinfo supports token query param; also Authorization: Bearer is accepted.
        params["token"] = token
        headers["Authorization"] = f"Bearer {token}"

    tries = 0
    while True:
        tries += 1
        try:
            resp = requests.get(base_url, params=params, headers=headers, timeout=timeout)
            result["http_status"] = resp.status_code
            if resp.status_code == 200:
                try:
                    data = resp.json()
                except json.JSONDecodeError:
                    result["error"] = "ipinfo.io returned invalid JSON."
                    return result
                # Some ipinfo responses include an 'error' field; check for that
                if isinstance(data, dict) and "error" in data:
                    # data['error'] might be a dict or string
                    err = data["error"]
                    if isinstance(err, dict) and "title" in err:
                        result["error"] = f"ipinfo error: {err.get('title')}"
                    else:
                        result["error"] = f"ipinfo error: {err}"
                    return result
                result["data"] = data
                result["success"] = True
                return result
            elif resp.status_code in (429, 502, 503, 504) and tries <= (1 + max_retries):
                # transient: rate limited or bad gateway/temporarily unavailable; back off and retry
                backoff = 0.5 * tries
                time.sleep(backoff)
                continue
            else:
                # other HTTP errors: try to extract json error message or use text
                try:
                    j = resp.json()
                    # ipinfo often includes 'error' or 'message' fields
                    msg = j.get("error") or j.get("message") or json.dumps(j)
                except Exception:
                    msg = resp.text.strip() or f"HTTP {resp.status_code}"
                result["error"] = f"ipinfo.io HTTP {resp.status_code}: {msg}"
                return result
        except requests.Timeout:
            if tries <= (1 + max_retries):
                time.sleep(0.5 * tries)
                continue
            result["error"] = "Timeout while contacting ipinfo.io"
            return result
        except requests.ConnectionError as e:
            if tries <= (1 + max_retries):
                time.sleep(0.5 * tries)
                continue
            result["error"] = f"Connection error while contacting ipinfo.io: {e}"
            return result
        except Exception as e:
            result["error"] = f"Unexpected error while contacting ipinfo.io: {e}"
            return result
