import base64
import hashlib
import hmac

# Try to use b64sha256_auth if available; otherwise we'll proceed with the local fallback.
try:
    import b64sha256_auth  # if available, user code can adapt this section to call the library API
    HAVE_LIB = True
except Exception:
    HAVE_LIB = False

class Response:
    """Minimal response object with .status_code (int) and .content (bytes)."""
    def __init__(self, status_code: int, content: bytes):
        self.status_code = status_code
        self.content = content

def _decode_b64_sha256(b64str: str):
    """Decode a base64-encoded SHA-256 digest. Returns bytes (32 bytes) or raises ValueError."""
    try:
        decoded = base64.b64decode(b64str, validate=True)
    except Exception as e:
        raise ValueError("invalid base64") from e
    if len(decoded) != 32:
        raise ValueError("decoded value is not a 32-byte SHA-256 digest")
    return decoded

def task_func(data):
    """
    Authenticate a user given data = {'username': str, 'password': str}.
    'password' must be a base64-encoded SHA-256 digest (32 bytes).
    Returns a Response object with appropriate status and message bytes.

    Demo credentials:
      username == 'admin'
      password == SHA256(b'password') (base64-encoded for the input)
    """
    if not isinstance(data, dict):
        return Response(400, b'Invalid request.')

    username = data.get('username')
    password_b64 = data.get('password')

    if not isinstance(username, str) or not isinstance(password_b64, str):
        return Response(400, b'Invalid request.')

    # If the external library exists and offers a decoding function, you could call it here.
    # For portability we use the local decoder.
    try:
        provided_digest = _decode_b64_sha256(password_b64)
    except ValueError:
        return Response(400, b'Invalid request.')

    # Predefined expected digest for demo: SHA-256 of b'password'
    expected_digest = hashlib.sha256(b'password').digest()

    # Use constant-time comparison
    if username == 'admin' and hmac.compare_digest(provided_digest, expected_digest):
        return Response(200, b'Login successful.')
    else:
        return Response(401, b'Login failed.')

# Example usage and quick self-test:
