    class veg_pref_stats:
        @staticmethod
        def calculate_percentages(counts: Dict[str, int]) -> Dict[str, float]:
            """Calculate percentages of each count relative to total, rounded to 2 decimals."""
            total = sum(counts.values())
            if total <= 0:
                return {k: 0.0 for k in counts}
            return {k: round((v / total) * 100, 2) for k, v in counts.items()}

        @staticmethod
        def assign_random_counts(items: Iterable[str], low: int = 1, high: int = 10,
                                 seed: Optional[int] = None) -> Dict[str, int]:
            """Assign random integers in [low, high] to each item. Optional seed for reproducibility."""
            if seed is not None:
                random.seed(seed)
            return {item: random.randint(low, high) for item in items}


def veg_preference_statistics(preferences: Dict[str, Any],
                              seed: Optional[int] = None
                              ) -> Dict[str, Any]:
    """
    Given a dict mapping person -> vegetable (string) or person -> list/tuple of vegetables,
    reverse the mapping to vegetable -> person (if multiple people listed the same vegetable,
    the first encountered person will be used), assign random counts 1..10 to each vegetable,
    and compute percentage share of total counts per vegetable.

    Returns a dictionary with keys:
      - 'veg_to_person': Dict[str, str] mapping vegetable -> a person who listed it
      - 'veg_counts': Dict[str, int] mapping vegetable -> assigned random count
      - 'veg_percentages': Dict[str, float] mapping vegetable -> percentage of total counts
      - 'total_count': int sum of counts

    Parameters:
      - preferences: dict mapping person -> vegetable string or list/tuple of strings
      - seed: optional int seed for random number generator (makes counts reproducible)

    Note: The function attempts to use the veg_pref_stats library if present; if not,
    a small local implementation is used so the function remains self-contained.
    """
    # Normalize input and build veg -> person map
    veg_to_person: Dict[str, str] = {}
    for person, vegs in preferences.items():
        if isinstance(vegs, (list, tuple, set)):
            for veg in vegs:
                if veg not in veg_to_person:
                    veg_to_person[veg] = person
        else:
            veg = vegs
            if veg not in veg_to_person:
                veg_to_person[veg] = person

    veg_list = list(veg_to_person.keys())

    # Assign random counts using veg_pref_stats.assign_random_counts if available in module
    if hasattr(veg_pref_stats, "assign_random_counts"):
        veg_counts = veg_pref_stats.assign_random_counts(veg_list, low=1, high=10, seed=seed)
    else:
        # fallback
        if seed is not None:
            random.seed(seed)
        veg_counts = {veg: random.randint(1, 10) for veg in veg_list}

    # Calculate percentages
    if hasattr(veg_pref_stats, "calculate_percentages"):
        veg_percentages = veg_pref_stats.calculate_percentages(veg_counts)
    else:
        total = sum(veg_counts.values())
        if total <= 0:
            veg_percentages = {k: 0.0 for k in veg_counts}
        else:
            veg_percentages = {k: round((v / total) * 100, 2) for k, v in veg_counts.items()}

    total_count = sum(veg_counts.values())

    return {
        "veg_to_person": veg_to_person,
        "veg_counts": veg_counts,
        "veg_percentages": veg_percentages,
        "total_count": total_count,
    }


# Example usage
