import random
import json
import os
from typing import List, Tuple, Optional, Dict

def create_random_city_map(
    cities: List[str],
    lat_range: Tuple[float, float],
    lon_range: Tuple[float, float],
    seed: Optional[int] = None,
    output_file: str = "city_map.html",
    zoom_start: int = 4
) -> Tuple[str, Dict[str, Tuple[float, float]]]:
    """
    Create an HTML map with markers for a list of cities. Coordinates are randomly
    generated within the provided latitude and longitude ranges.

    Returns (output_file, coords) where coords is a dict mapping city -> (lat, lon).

    The generated HTML uses Leaflet (CDN) and can be opened in any browser.
    """
    # Validate inputs
    if not isinstance(cities, list):
        raise TypeError("cities must be a list of strings")
    if len(cities) == 0:
        # allow empty list but still create a map centered in the middle of ranges
        pass
    if not (isinstance(lat_range, (list, tuple)) and len(lat_range) == 2):
        raise TypeError("lat_range must be a tuple/list of (min_lat, max_lat)")
    if not (isinstance(lon_range, (list, tuple)) and len(lon_range) == 2):
        raise TypeError("lon_range must be a tuple/list of (min_lon, max_lon)")

    min_lat, max_lat = float(lat_range[0]), float(lat_range[1])
    min_lon, max_lon = float(lon_range[0]), float(lon_range[1])
    if min_lat > max_lat:
        raise ValueError("lat_range min must be <= max")
    if min_lon > max_lon:
        raise ValueError("lon_range min must be <= max")

    rnd = random.Random(seed)

    coords = {}
    for city in cities:
        lat = rnd.uniform(min_lat, max_lat)
        lon = rnd.uniform(min_lon, max_lon)
        coords[city] = (lat, lon)

    # Determine map center: average of generated coords if any, otherwise mid of ranges
    if coords:
        avg_lat = sum(lat for lat, lon in coords.values()) / len(coords)
        avg_lon = sum(lon for lat, lon in coords.values()) / len(coords)
    else:
        avg_lat = (min_lat + max_lat) / 2.0
        avg_lon = (min_lon + max_lon) / 2.0

    # Prepare markers for embedding into JS
    markers = []
    for city, (lat, lon) in coords.items():
        popup = f"{city} ({lat:.6f}, {lon:.6f})"
        markers.append({"name": city, "lat": lat, "lon": lon, "popup": popup})

    markers_json = json.dumps(markers)

    # Create HTML using Leaflet from CDN
    html = f"""<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <title>City Map</title>
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <link
    rel="stylesheet"
    href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"
    integrity="sha256-sA+e2wQ7b9yY3f5jz2Y1U4m5pH0q+2Qq3n8R+o3D0+M="
    crossorigin=""
  />
  <style>
    body, html, #map {{
      height: 100%;
      margin: 0;
      padding: 0;
    }}
    #map {{ height: 90vh; }}
    .info-box {{
      padding: 6px 8px;
      font: 14px/16px Arial, Helvetica, sans-serif;
      background: white;
      background: rgba(255, 255, 255, 0.8);
      box-shadow: 0 0 15px rgba(0,0,0,0.2);
      border-radius: 5px;
    }}
  </style>
</head>
<body>
  <div id="map"></div>
  <script
    src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"
    integrity="sha256-o9N1j7kG8x3o1g1xq2gZb6b0k3q1v1Xy1+3w5x0y0Xk="
    crossorigin="">
  </script>
  <script>
    const center = [{avg_lat:.8f}, {avg_lon:.8f}];
    const map = L.map('map').setView(center, {zoom_start});
    L.tileLayer('https://{{s}}.tile.openstreetmap.org/{{z}}/{{x}}/{{y}}.png', {{
      maxZoom: 19,
      attribution: '&copy; OpenStreetMap contributors'
    }}).addTo(map);

    const markers = {markers_json};

    for (const m of markers) {{
      const marker = L.marker([m.lat, m.lon]).addTo(map);
      marker.bindPopup(m.popup);
    }}

    // If no markers, display an info box with instructions
    if (markers.length === 0) {{
      const info = L.control({{position: 'topright'}});
      info.onAdd = function (map) {{
        const div = L.DomUtil.create('div', 'info-box');
        div.innerHTML = '<b>No cities provided</b><br>Adjust input and regenerate map.';
        return div;
      }};
      info.addTo(map);
    }}
  </script>
</body>
</html>
"""

    # Write HTML to file
    with open(output_file, "w", encoding="utf-8") as f:
        f.write(html)

    # Return path and generated coordinates
    return os.path.abspath(output_file), coords

# Example usage:
if __name__ == "__main__":
    cities = ["Springfield", "Gotham", "Metropolis", "Smallville"]
    out, generated = create_random_city_map(
        cities,
        lat_range=(34.0, 42.0),
        lon_range=(-118.5, -74.0),
        seed=42,
        output_file="example_city_map.html",
        zoom_start=5
    )
    print("Map written to:", out)
    print("Generated coordinates:")
    for city, (lat, lon) in generated.items():
        print(f"  {city}: {lat:.6f}, {lon:.6f}")
