def analyze_numbers(data, threshold, bins=10, show_plot=True, save_path=None):
    """
    Analyze a list/iterable of numeric data:
      - Compute average (mean)
      - Identify values greater than the average
      - Count how many values are greater than `threshold`
      - Plot a histogram of the sorted numbers

    This function attempts to use the 'numstats_plot' library if available.
    If it's not installed, a small internal fallback implementation will be used.

    Parameters:
      data: iterable of numbers (ints/floats). None/NaN entries are ignored.
      threshold: numeric value to count how many entries are greater than it.
      bins: number of histogram bins (default 10).
      show_plot: if True, call pyplot.show(). If False, don't display (useful when saving).
      save_path: if provided (str), save the figure to this path (e.g., 'out.png').

    Returns:
      dict with keys: 'average', 'values_above_avg', 'count_above_threshold', 'total_count'
    """
    # Imports inside function to keep it self-contained
    import math
    try:
        import numpy as _np  # prefer numpy if available
    except Exception:
        _np = None
    try:
        import matplotlib.pyplot as _plt
    except Exception as e:
        raise ImportError("matplotlib is required for plotting. Install it (pip install matplotlib).") from e

    # Try to import the requested library; if unavailable, provide a minimal fallback
    try:
        import numstats_plot as _nsp  # pragma: no cover - uses external lib if present
        _has_nsp = True
    except Exception:
        _has_nsp = False

    # Fallback implementation if numstats_plot isn't available
    if not _has_nsp:
        class _FallbackNSP:
            @staticmethod
            def compute_average(values):
                if _np is not None:
                    return float(_np.mean(values))
                # basic mean without numpy
                return float(sum(values) / len(values))

            @staticmethod
            def values_greater_than_avg(values, avg):
                return [v for v in values if v > avg]

            @staticmethod
            def count_greater_than_value(values, threshold):
                return sum(1 for v in values if v > threshold)

            @staticmethod
            def plot_histogram_sorted(values, bins=10, threshold=None, avg=None, show=True, save_path=None):
                sorted_vals = list(values)  # already sorted by caller if desired
                # Plot histogram of sorted values (sorting doesn't change counts but follows request)
                _plt.figure()
                _plt.hist(sorted_vals, bins=bins, edgecolor='black')
                title = "Histogram of Sorted Values"
                _plt.title(title)
                _plt.xlabel("Value")
                _plt.ylabel("Frequency")
                # Optional vertical lines for average and threshold
                if avg is not None:
                    _plt.axvline(avg, color='orange', linestyle='--', label=f'Average = {avg:.4g}')
                if threshold is not None:
                    _plt.axvline(threshold, color='red', linestyle=':', label=f'Threshold = {threshold:.4g}')
                if (avg is not None) or (threshold is not None):
                    _plt.legend()
                if save_path:
                    _plt.savefig(save_path, bbox_inches='tight')
                if show:
                    _plt.show()
                # Close the figure to free memory
                _plt.close()

        _nsp = _FallbackNSP()

    # Normalize and validate input data: flatten iterables and keep numeric values only
    # We accept iterables like list, tuple, numpy arrays, etc.
    numeric_values = []
    # If numpy is available, use numpy.asarray for faster handling
    if _np is not None:
        try:
            arr = _np.asarray(data)
            # If it's a scalar, wrap it
            if arr.shape == ():
                arr = arr.reshape(1)
            for v in arr.ravel():
                try:
                    if v is None:
                        continue
                    if _np.isnan(v):
                        continue
                except Exception:
                    # For non-numeric types, fall back to math check below
                    pass
                try:
                    fv = float(v)
                except Exception:
                    continue
                if math.isnan(fv) or math.isinf(fv):
                    continue
                numeric_values.append(fv)
        except Exception:
            # Fall back to generic iteration
            for item in data:
                try:
                    if item is None:
                        continue
                    fv = float(item)
                except Exception:
                    continue
                if math.isnan(fv) or math.isinf(fv):
                    continue
                numeric_values.append(fv)
    else:
        # No numpy; iterate
        for item in data:
            try:
                if item is None:
                    continue
                fv = float(item)
            except Exception:
                continue
            if math.isnan(fv) or math.isinf(fv):
                continue
            numeric_values.append(fv)

    if len(numeric_values) == 0:
        raise ValueError("No valid numeric values found in 'data'.")

    # Compute average (mean) using the chosen library interface
    avg = _nsp.compute_average(numeric_values)

    # Identify values greater than average
    values_above_avg = _nsp.values_greater_than_avg(numeric_values, avg)

    # Count how many values are greater than specified threshold
    count_above_threshold = _nsp.count_greater_than_value(numeric_values, threshold)

    # Plot histogram of the sorted numbers (sort for the plot as requested)
    sorted_values = sorted(numeric_values)
    # Use the plotting function from the library/fallback
    _nsp.plot_histogram_sorted(sorted_values, bins=bins, threshold=threshold, avg=avg, show=show_plot, save_path=save_path)

    return {
        "average": float(avg),
        "values_above_avg": values_above_avg,
        "count_above_threshold": int(count_above_threshold),
        "total_count": int(len(numeric_values)),
    }

# Example usage:
if __name__ == "__main__":
    sample_data = [1, 2, 3, 4, 10, 20, None, float('nan'), "5", 6.5]
    result = analyze_numbers(sample_data, threshold=5, bins=8, show_plot=False, save_path="hist.png")
    print(result)
