from typing import Dict, List, Tuple, Union, Iterable, Any
import numbers

# Try to use the real library if available; otherwise provide a local fallback.
try:
    import student_grade_report  # type: ignore
    HAS_LIB = True
except Exception:
    HAS_LIB = False

# Fallback implementation (used only if the real library isn't available).
if not HAS_LIB:
    class _FallbackGradeReport:
        """
        Simple fallback for a hypothetical 'student_grade_report' library.
        Stores grades and computes averages per-student and per-subject.
        """
        def __init__(self):
            # raw storage: dict[student][subject] -> list[grades]
            self._data = {}

        def add_grade(self, student: str, subject: str, grade: float) -> None:
            if student not in self._data:
                self._data[student] = {}
            if subject not in self._data[student]:
                self._data[student][subject] = []
            self._data[student][subject].append(float(grade))

        def add_grades_from_iterable(self, items: Iterable[Tuple[str,str,float]]) -> None:
            for student, subject, grade in items:
                self.add_grade(student, subject, grade)

        def add_grades_from_nested_dict(self, d: Dict[str, Dict[str, Union[float, List[float]]]]) -> None:
            for student, subjects in d.items():
                for subject, grade_or_list in subjects.items():
                    if isinstance(grade_or_list, Iterable) and not isinstance(grade_or_list, (str, bytes)):
                        for g in grade_or_list:
                            self.add_grade(student, subject, g)
                    else:
                        self.add_grade(student, subject, grade_or_list)

        def compute_student_averages(self) -> Dict[str, float]:
            result = {}
            for student, subjects in self._data.items():
                all_grades = []
                for grades in subjects.values():
                    all_grades.extend(grades)
                result[student] = (sum(all_grades) / len(all_grades)) if all_grades else 0.0
            return result

        def compute_subject_averages(self) -> Dict[str, float]:
            subject_acc = {}
            for student_subjects in self._data.values():
                for subject, grades in student_subjects.items():
                    if subject not in subject_acc:
                        subject_acc[subject] = []
                    subject_acc[subject].extend(grades)
            return {subject: (sum(grades)/len(grades) if grades else 0.0) for subject, grades in subject_acc.items()}

        def as_dict(self) -> Dict[str, Any]:
            return {
                "raw": self._data,
                "student_averages": self.compute_student_averages(),
                "subject_averages": self.compute_subject_averages(),
            }

    # Expose the fallback under the same name that we'd expect from the real library
    class student_grade_report:
        Report = _FallbackGradeReport


def _normalize_input(grades_input: Any) -> List[Tuple[str, str, float]]:
    """
    Convert supported input formats into a list of (student, subject, grade) tuples.
    Supported formats:
      - dict: {student: {subject: grade_or_list_of_grades}}
      - list of tuples: [(student, subject, grade), ...]
      - list of dicts: [{"student":..., "subject":..., "grade":...}, ...]
    """
    normalized = []

    if isinstance(grades_input, dict):
        # nested dict
        for student, subj_map in grades_input.items():
            if not isinstance(subj_map, dict):
                raise ValueError("If top-level input is a dict, each value must be a dict of subjects.")
            for subject, grade_or_list in subj_map.items():
                if isinstance(grade_or_list, Iterable) and not isinstance(grade_or_list, (str, bytes)):
                    for g in grade_or_list:
                        if not isinstance(g, numbers.Number):
                            raise ValueError(f"All grades must be numeric. Got {g} for {student}/{subject}.")
                        normalized.append((str(student), str(subject), float(g)))
                else:
                    if not isinstance(grade_or_list, numbers.Number):
                        raise ValueError(f"All grades must be numeric. Got {grade_or_list} for {student}/{subject}.")
                    normalized.append((str(student), str(subject), float(grade_or_list)))
        return normalized

    if isinstance(grades_input, list):
        # Could be list of tuples or list of dicts
        if not grades_input:
            return []
        first = grades_input[0]
        if isinstance(first, tuple) or isinstance(first, list):
            # Expect (student, subject, grade)
            for item in grades_input:
                if len(item) != 3:
                    raise ValueError("Tuples/lists must be of length 3: (student, subject, grade).")
                student, subject, grade = item
                if not isinstance(grade, numbers.Number):
                    raise ValueError(f"Grade must be numeric, got {grade}.")
                normalized.append((str(student), str(subject), float(grade)))
            return normalized
        elif isinstance(first, dict):
            # Expect dicts with keys student, subject, grade
            for item in grades_input:
                s = item.get("student") or item.get("name") or item.get("student_name")
                sub = item.get("subject")
                grade = item.get("grade")
                if s is None or sub is None or grade is None:
                    raise ValueError("Each dict must contain 'student', 'subject', and 'grade' keys.")
                if not isinstance(grade, numbers.Number):
                    raise ValueError(f"Grade must be numeric, got {grade}.")
                normalized.append((str(s), str(sub), float(grade)))
            return normalized

    raise ValueError("Unsupported input format. Provide nested dict, list of tuples, or list of dicts.")


def generate_student_grade_report(grades_input: Any) -> Dict[str, Any]:
    """
    Create a grade report (using student_grade_report if available, otherwise a fallback).
    The function computes average grades per student and per subject, and returns a dictionary:
      {
        "raw": {student: {subject: [grades]}},
        "student_averages": {student: avg},
        "subject_averages": {subject: avg}
      }

    Accepted input formats:
      - Nested dict: { "Alice": {"Math": [90, 95], "English": 88}, "Bob": {"Math": 80, "English": [70, 75]} }
      - List of tuples: [("Alice", "Math", 90), ("Alice", "Math", 95), ("Bob", "English", 70)]
      - List of dicts: [{"student": "Alice", "subject": "Math", "grade": 90}, ...]

    Example:
      report = generate_student_grade_report({
          "Alice": {"Math": [90, 95], "English": 88},
          "Bob": {"Math": 80, "English": [70, 75]}
      })
    """
    # Normalize input to list of (student, subject, grade) tuples
    items = _normalize_input(grades_input)

    # Create the report object (from real library if available, else fallback)
    report = student_grade_report.Report()

    # Add grades
    for student, subject, grade in items:
        report.add_grade(student, subject, grade)

    # Return a dict representation
    return report.as_dict()


