      ImportError: if neither excel_copy_reader nor openpyxl is available.
      RuntimeError: for file I/O or read/write errors.
    """
    # Helper implementations using openpyxl
    def _copy_with_openpyxl(src, dst):
        try:
            from openpyxl import load_workbook, Workbook
        except ImportError:
            raise ImportError("openpyxl is required for fallback copying. Install with `pip install openpyxl`.")
        wb_src = load_workbook(src, data_only=True)
        wb_dst = Workbook()
        # Remove default sheet created by Workbook() if necessary
        default_sheet = wb_dst.active
        if default_sheet and default_sheet.title == "Sheet" and len(wb_src.sheetnames) > 0:
            wb_dst.remove(default_sheet)
        for sheet_name in wb_src.sheetnames:
            ws_src = wb_src[sheet_name]
            ws_dst = wb_dst.create_sheet(title=sheet_name)
            # Copy cell values
            for row in ws_src.iter_rows():
                for cell in row:
                    ws_dst.cell(row=cell.row, column=cell.column, value=cell.value)
            # Copy merged cells
            try:
                merged = list(ws_src.merged_cells.ranges)
                for m in merged:
                    ws_dst.merge_cells(str(m))
            except Exception:
                # ignore merged cell copying if any issue
                pass
            # Copy column widths and row heights (best-effort)
            try:
                for col, dim in ws_src.column_dimensions.items():
                    if dim.width is not None:
                        ws_dst.column_dimensions[col].width = dim.width
                for r_idx, dim in ws_src.row_dimensions.items():
                    if getattr(dim, "height", None) is not None:
                        ws_dst.row_dimensions[r_idx].height = dim.height
            except Exception:
                pass
        wb_dst.save(dst)

    def _read_with_openpyxl(path):
        try:
            from openpyxl import load_workbook
        except ImportError:
            raise ImportError("openpyxl is required for reading. Install with `pip install openpyxl`.")
        wb = load_workbook(path, data_only=True)
        result = {}
        for sheet in wb.sheetnames:
            ws = wb[sheet]
            rows = []
            for r in ws.iter_rows(values_only=True):
                # convert tuple to list for easier consumption
                rows.append(list(r))
            result[sheet] = rows
        return result

    # Try to use excel_copy_reader if available
    ecr = None
    try:
        import excel_copy_reader as ecr  # noqa: F401
    except Exception:
        ecr = None

    copied = False
    if ecr is not None:
        # Try a few common expected function names for copying
        for func_name in ("copy_excel", "copy_workbook", "copy", "copy_file"):
            func = getattr(ecr, func_name, None)
            if callable(func):
                try:
                    # try calling with (src, dst)
                    func(src_path, dst_path)
                    copied = True
                    break
                except TypeError:
                    # maybe different signature; try single-arg returning bytes/content or similar
                    try:
                        result = func(src_path)
                        # if result looks like bytes or file-like, write to dst_path
                        if isinstance(result, (bytes, bytearray)):
                            with open(dst_path, "wb") as f:
                                f.write(result)
                            copied = True
                            break
                    except Exception:
                        pass
                except Exception:
                    # if copy attempt fails, don't crash here; we'll fallback
                    copied = False

    if not copied:
        # fallback to openpyxl-based copy
        _copy_with_openpyxl(src_path, dst_path)

    # Now read the destination file. Prefer excel_copy_reader read functions if available.
    if ecr is not None:
        for func_name in ("read_excel", "read_workbook", "read"):
            func = getattr(ecr, func_name, None)
            if callable(func):
                try:
                    data = func(dst_path)
                    # If the returned data structure looks reasonable, return it
                    if isinstance(data, dict):
                        return data
                    # else if returns list-of-lists and single-sheet, try to normalize:
                    if isinstance(data, list):
                        return {"Sheet1": data}
                except Exception:
                    # ignore and fallback to openpyxl read
                    pass

    # final fallback: read with openpyxl
    return _read_with_openpyxl(dst_path)
```

