def split_dataset_remove_column(df, column_to_remove=None, test_size=0.2, random_state=None):
    """
    Remove a specified column from the DataFrame (if present) and split the resulting DataFrame
    into train and test sets. This tries to use the 'split_cleaner' library if available;
    otherwise it falls back to sklearn.model_selection.train_test_split.

    Parameters:
    - df: pandas.DataFrame (or convertible to one)
    - column_to_remove: str or None - column name to drop if it exists
    - test_size: float in (0,1) or int - proportion (or absolute number) for test set
    - random_state: int or None - random seed for reproducibility

    Returns:
    - train_df, test_df: tuple of pandas.DataFrame
    """
    # Local imports so the function is self-contained
    try:
        import pandas as pd
    except Exception as e:
        raise ImportError("pandas is required by this function. Install with `pip install pandas`.") from e

    # Ensure we have a DataFrame
    if not isinstance(df, pd.DataFrame):
        try:
            df = pd.DataFrame(df)
        except Exception as e:
            raise ValueError("Input could not be converted to a pandas DataFrame.") from e

    # Drop the column if it exists
    if column_to_remove is not None and column_to_remove in df.columns:
        df_clean = df.drop(columns=[column_to_remove]).copy()
    else:
        df_clean = df.copy()

    # Try to use split_cleaner if available
    try:
        import split_cleaner  # noqa: F401
        # Prefer a function named train_test_split or split; be flexible
        split_func = None
        for name in ("train_test_split", "split", "split_dataset"):
            split_func = getattr(split_cleaner, name, None)
            if callable(split_func):
                break
        if not callable(split_func):
            raise ImportError("split_cleaner was found but no known split function ('train_test_split', 'split', 'split_dataset') is available.")
        # Call the split function. We attempt to pass common arguments; if the library uses different names,
        # it should be adjusted by the user.
        try:
            train_df, test_df = split_func(df_clean, test_size=test_size, random_state=random_state)
        except TypeError:
            # Try calling with different argument names (fallback)
            train_df, test_df = split_func(df_clean, test_fraction=test_size, seed=random_state)
    except ImportError:
        # Fallback to sklearn
        try:
            from sklearn.model_selection import train_test_split
        except Exception as e:
            raise ImportError(
                "split_cleaner is not available and sklearn is required for the fallback. "
                "Install one of them, e.g. `pip install split_cleaner` or `pip install scikit-learn`."
            ) from e
        train_df, test_df = train_test_split(df_clean, test_size=test_size, random_state=random_state, shuffle=True)

    # Ensure returned objects are DataFrames
    if not isinstance(train_df, pd.DataFrame):
        try:
            train_df = pd.DataFrame(train_df)
        except Exception:
            raise TypeError("train split is not a DataFrame and could not be converted.")
    if not isinstance(test_df, pd.DataFrame):
        try:
            test_df = pd.DataFrame(test_df)
        except Exception:
            raise TypeError("test split is not a DataFrame and could not be converted.")

    return train_df, test_df

