```python
def plot_random_3d_dots(n=200, seed=None, point_size=20, color='blue', show=True, save_path=None):
    """
    Generate n random 3D points in [0,1) (for x,y,z) and plot them.
    Tries to use a module named `scatter3d_plot` if available; otherwise uses matplotlib.

    Parameters:
    - n (int): number of points to generate.
    - seed (int or None): random seed for reproducibility.
    - point_size (int or float): marker size for the scatter plot.
    - color (str or array-like): color for the points.
    - show (bool): whether to call plt.show() (or scatter3d_plot's display).
    - save_path (str or None): if given, save the figure to this path (PNG/PDF/etc).

    Returns:
    - (xs, ys, zs): three lists of floats with the generated coordinates.
    """
    import random

    if seed is not None:
        random.seed(seed)

    # Generate coordinates
    xs = [random.random() for _ in range(n)]
    ys = [random.random() for _ in range(n)]
    zs = [random.random() for _ in range(n)]

    # Try to use scatter3d_plot if available
    try:
        import scatter3d_plot as s3p
    except Exception:
        s3p = None

    if s3p is not None:
        # Try a few likely APIs on the library; if none work, fall back to matplotlib below.
        try:
            # try a common scatter-like API
            if hasattr(s3p, 'scatter'):
                # assume signature scatter(x, y, z, **kwargs)
                s3p.scatter(xs, ys, zs, s=point_size, c=color)
                if save_path and hasattr(s3p, 'savefig'):
                    try:
                        s3p.savefig(save_path)
                    except Exception:
                        pass
                if show and hasattr(s3p, 'show'):
                    try:
                        s3p.show()
                    except Exception:
                        pass
                return xs, ys, zs
            # try a more generic plot function
            if hasattr(s3p, 'plot'):
                # many libs use plot(x, y, z, kind='scatter') or just plot(x,y,z,'.')
                try:
                    s3p.plot(xs, ys, zs, kind='scatter', s=point_size, c=color)
                except Exception:
                    s3p.plot(xs, ys, zs, marker='o', markersize=point_size, color=color)
                if save_path and hasattr(s3p, 'savefig'):
                    try:
                        s3p.savefig(save_path)
                    except Exception:
                        pass
                if show and hasattr(s3p, 'show'):
                    try:
                        s3p.show()
                    except Exception:
                        pass
                return xs, ys, zs
            # try constructor/class style
            if hasattr(s3p, 'Scatter3D'):
                try:
                    fig = s3p.Scatter3D(xs, ys, zs, size=point_size, color=color)
                    if save_path and hasattr(fig, 'savefig'):
                        fig.savefig(save_path)
                    if show and hasattr(fig, 'show'):
                        fig.show()
                    return xs, ys, zs
                except Exception:
                    pass
            # If none of the above worked, fall back
            raise RuntimeError("scatter3d_plot imported but no known plotting API worked; falling back.")
        except Exception:
            pass

    # Fallback: use matplotlib
    try:
        import matplotlib.pyplot as plt
        from mpl_toolkits.mplot3d import Axes3D  # noqa: F401 (needed for projection)
    except Exception as e:
        raise RuntimeError("Neither scatter3d_plot is usable nor is matplotlib available.") from e

    fig = plt.figure(figsize=(7, 6))
    ax = fig.add_subplot(111, projection='3d')
    ax.scatter(xs, ys, zs, s=point_size, c=color, depthshade=True)
    ax.set_xlabel("X")
    ax.set_ylabel("Y")
    ax.set_zlabel("Z")
    ax.set_xlim(0, 1)
    ax.set_ylim(0, 1)
    ax.set_zlim(0, 1)
    ax.set_title(f"{n} random 3D points in [0,1)^3")

    if save_path:
        plt.savefig(save_path, bbox_inches='tight')

    if show:
        plt.show()
    else:
        plt.close(fig)

    return xs, ys, zs


