I couldn't find a PyPI package named "xml_dict_parser", so I implemented a self-contained function that uses Python's built-in xml.etree.ElementTree to convert an XML string into a nested dictionary and optionally save it as JSON. The conversion follows common conventions:

- Leaf elements with only text become that text (string).
- Repeated sibling tags become lists.
- Element attributes are placed under the key "@attributes".
- If an element has both attributes and text, the text is stored under "#text".

Here is the function:

def task_func(xml_string: str, save_json: bool = False, json_file_path: str = None) -> dict:
    """
    Parse an XML string into a nested Python dictionary and optionally save as JSON.

    Args:
        xml_string: XML content as a string.
        save_json: If True, write the parsed dictionary to json_file_path.
        json_file_path: Path to the JSON file to write (required if save_json is True).

    Returns:
        A dictionary representation of the XML (root element is the top-level key).

    Raises:
        ValueError: If xml_string is empty/invalid or save_json is True but json_file_path is None.
    """
    import xml.etree.ElementTree as ET
    import json

    if not isinstance(xml_string, str) or not xml_string.strip():
        raise ValueError("xml_string must be a non-empty string.")

    try:
        root = ET.fromstring(xml_string)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML: {e}")

    def elem_to_dict(elem):
        # Build dict for this element: return {tag: value}
        node = {}
        # attributes
        if elem.attrib:
            node["@attributes"] = dict(elem.attrib)

        # children
        children = list(elem)
        if children:
            child_map = {}
            for child in children:
                child_parsed = elem_to_dict(child)   # returns {child.tag: value}
                tag = child.tag
                value = child_parsed[tag]
                if tag in child_map:
                    # existing -> make / append to list
                    if isinstance(child_map[tag], list):
                        child_map[tag].append(value)
                    else:
                        child_map[tag] = [child_map[tag], value]
                else:
                    child_map[tag] = value
            node.update(child_map)

        # text (strip whitespace). If there are no children and no attributes, return text directly.
        text = (elem.text or "").strip()
        if text:
            if children or elem.attrib:
                node["#text"] = text
            else:
                # leaf text node with no attributes -> return text as value
                return {elem.tag: text}

        # if node is empty (no children, no attributes, no text), use None
        if not node:
            return {elem.tag: None}
        return {elem.tag: node}

    parsed = elem_to_dict(root)

    if save_json:
        if not json_file_path:
            raise ValueError("json_file_path must be provided when save_json is True.")
        # Write JSON
        with open(json_file_path, "w", encoding="utf-8") as f:
            json.dump(parsed, f, ensure_ascii=False, indent=2)

    return parsed

