def stock_column_stats(rows, column):
    """
    Calculate sum, mean, min, and max for a specified column from a list of stock data rows.

    Parameters:
    - rows: iterable of records (dicts, sequences/tuples/lists, or objects with attributes).
    - column: either a string (key or attribute name) or an int (index for sequence rows).

    Returns:
    - dict with keys: 'sum', 'mean', 'min', 'max', 'count'

    Raises:
    - ValueError if no valid numeric values are found.
    """
    import math

    total = 0.0
    count = 0
    min_val = None
    max_val = None

    def _get_value(row):
        # Try several access methods
        # If column is an int, first try index access
        try:
            if isinstance(column, int):
                # Works for lists/tuples/strings and dicts (dict will raise KeyError)
                return row[column]
        except Exception:
            pass

        # If column is str, try dict lookup, attribute, or mapping access
        if isinstance(column, str):
            if isinstance(row, dict):
                return row.get(column)
            # attribute access
            if hasattr(row, column):
                try:
                    return getattr(row, column)
                except Exception:
                    pass
        # Fallback: try item access (works for many types)
        try:
            return row[column]
        except Exception:
            return None

    for row in rows:
        raw = _get_value(row)
        if raw is None or raw == "":
            continue
        # handle NaN-like strings or floats
        try:
            num = float(raw)
        except (TypeError, ValueError):
            continue
        if math.isnan(num):
            continue
        total += num
        count += 1
        if min_val is None or num < min_val:
            min_val = num
        if max_val is None or num > max_val:
            max_val = num

    if count == 0:
        raise ValueError("No valid numeric values found for column: {}".format(column))

    return {
        "sum": total,
        "mean": total / count,
        "min": min_val,
        "max": max_val,
        "count": count,
    }

