from typing import List, Dict, Sequence, Optional, Union

NUMERIC_CLEAN_RE = re.compile(r'[^\d.\-eE+]')  # allow digits, dot, -, exponent sign

def _to_float_if_possible(value):
    """Try to convert common numeric representations to float. Return None if not convertible."""
    if value is None:
        return None
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        # convert ints to floats but keep floats
        if isinstance(value, float) and math.isnan(value):
            return None
        return float(value)
    if isinstance(value, bool):
        return None
    s = str(value).strip()
    if s == '':
        return None
    # Remove common currency/commas/percent and whitespace
    # Handle percent (e.g., "12.3%") by dividing by 100
    is_percent = s.endswith('%')
    if is_percent:
        s = s[:-1].strip()
    # Remove common currency symbols and thousands separators
    # We keep characters allowed in numeric literal (digits, ., -, +, e/E)
    cleaned = NUMERIC_CLEAN_RE.sub('', s)
    if cleaned == '' or cleaned in ('-', '+'):
        return None
    try:
        val = float(cleaned)
        if is_percent:
            val = val / 100.0
        if math.isnan(val):
            return None
        return val
    except ValueError:
        return None

