) -> Dict[str, float]:
    """
    Analyze a list of stock data and calculate sum, mean, min, and max for a specified column.

    Parameters:
    - rows: list of dicts (e.g., {"close": 123.4, "open": 120.0}) or list/tuple sequences (e.g., [date, open, close]).
    - column: column name (str) when rows are dicts or header provided, or integer index when rows are sequences.
    - header: optional sequence of column names if rows are sequences and you want to pass column by name.

    Returns:
    A dictionary with keys: 'sum', 'mean', 'min', 'max', 'count'.
    Raises ValueError if no valid numeric values are found or if column cannot be resolved.
    """
    values = []
    for i, row in enumerate(rows):
        val = None
        if isinstance(row, dict):
            # If column is int with dict rows, try to use header mapping first
            if isinstance(column, int):
                if header is None:
                    raise ValueError("Column specified as integer index but rows are dicts and no header was provided.")
                try:
                    key = header[column]
                except Exception:
                    raise ValueError("Header provided but index out of range.")
                val = row.get(key)
            else:
                val = row.get(column)
        elif isinstance(row, (list, tuple)):
            if isinstance(column, int):
                try:
                    val = row[column]
                except Exception:
                    raise ValueError(f"Row {i} does not have index {column}.")
            else:
                # column is a name: need header
                if header is None:
                    raise ValueError("Column specified by name for sequence rows but no header provided.")
                try:
                    idx = header.index(column)
                except ValueError:
                    raise ValueError(f"Column name '{column}' not found in header.")
                try:
                    val = row[idx]
                except Exception:
                    raise ValueError(f"Row {i} does not have index {idx} for column '{column}'.")
        else:
            # Unsupported row type
            continue

        num = _to_float_if_possible(val)
        if num is not None:
            values.append(num)

    if not values:
        raise ValueError("No valid numeric values found for the specified column.")

    total = math.fsum(values)
    count = len(values)
    mean = total / count
    minimum = min(values)
    maximum = max(values)

    return {
        "sum": total,
        "mean": mean,
        "min": minimum,
        "max": maximum,
        "count": count
    }

