from typing import Any, Iterable, Optional, Union
import matplotlib.pyplot as plt

def plot_monthly_barchart(
    data: Union['pandas.DataFrame', dict, Iterable[float], list],
    year: Optional[int] = None,
    ax: Optional[plt.Axes] = None,
    title: Optional[str] = None,
    color: str = 'C0',
    figsize: tuple = (10, 4),
    show: bool = True
) -> plt.Axes:
    """
    Plot a bar chart of monthly data values for a single year, with 'month' on the x-axis and 'value' on the y-axis.

    Parameters:
    - data:
        * pandas.DataFrame with columns 'month' and 'value' (month can be 1-12 or month names like 'Jan')
        * dict mapping month (1-12 or month name) -> value
        * iterable/list of 12 numeric values (index 0 -> January)
    - year: optional int to display in the title
    - ax: optional matplotlib Axes to plot into
    - title: optional title (if not given and year provided, title will include the year)
    - color: bar color
    - figsize: figure size when ax is not provided
    - show: whether to call plt.show() before returning

    Returns:
    - matplotlib Axes instance containing the plot

    Examples:
    - plot_monthly_barchart([1,2,3,...,12], year=2024)
    - plot_monthly_barchart({'Jan': 10, 'Feb': 5, ...})
    - plot_monthly_barchart(df)  # df with 'month' and 'value' columns
    """
    # Month labels for x-axis
    MONTH_LABELS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

    # Try to import yearly_barchart (if available) and delegate to it
    try:
        import yearly_barchart as yb  # type: ignore
        # If the library exists and has a helper function we can call, use it.
        # As the API is unknown, attempt a generic call; if it fails, fall back.
        try:
            # Many plotting libraries accept dataframe-like inputs; try to pass through
            return yb.plot_monthly(data=data, year=year, ax=ax, title=title, color=color, figsize=figsize)
        except Exception:
            # If delegation failed, continue to the matplotlib fallback
            pass
    except Exception:
        # yearly_barchart not installed; proceed with fallback
        pass

    # --- Fallback matplotlib implementation ---
    # Normalize input to a list of 12 values in month order
    values = None
    # If pandas DataFrame is provided
    try:
        import pandas as pd  # type: ignore
    except Exception:
        pd = None

    if pd is not None and isinstance(data, pd.DataFrame):
        if {'month', 'value'}.issubset(set(data.columns)):
            # Accept numeric months or month names
            s = data[['month', 'value']].copy()
            def month_to_index(m):
                if isinstance(m, str):
                    m_low = m.strip()[:3].title()
                    if m_low in MONTH_LABELS:
                        return MONTH_LABELS.index(m_low)
                    try:
                        return int(m) - 1
                    except Exception:
                        raise ValueError(f"Unrecognized month label: {m}")
                else:
                    # numeric
                    idx = int(m) - 1
                    if not (0 <= idx <= 11):
                        raise ValueError(f"Month number out of range: {m}")
                    return idx
            arr = [None]*12
            for _, row in s.iterrows():
                idx = month_to_index(row['month'])
                arr[idx] = float(row['value'])
            # Replace missing months with 0
            values = [0.0 if v is None else v for v in arr]
        else:
            raise ValueError("DataFrame input must contain 'month' and 'value' columns.")

    # If dict: keys -> month labels or numbers
    if values is None and isinstance(data, dict):
        arr = [0.0]*12
        for k, v in data.items():
            if isinstance(k, str):
                k_key = k.strip()[:3].title()
                if k_key not in MONTH_LABELS:
                    # try numeric string
                    try:
                        idx = int(k) - 1
                    except Exception:
                        raise ValueError(f"Unrecognized month key: {k}")
                else:
                    idx = MONTH_LABELS.index(k_key)
            else:
                idx = int(k) - 1
            if not (0 <= idx <= 11):
                raise ValueError(f"Month index out of range for key: {k}")
            arr[idx] = float(v)
        values = arr

    # If iterable/list of 12 numbers
    if values is None:
        # Accept list/tuple or other iterable
        try:
            if isinstance(data, (list, tuple)) or hasattr(data, '__iter__'):
                lst = list(data)
                if len(lst) == 12:
                    values = [float(x) for x in lst]
                else:
                    # Maybe the user passed a list of (month, value) pairs
                    if all(isinstance(item, (list, tuple)) and len(item) == 2 for item in lst):
                        arr = [0.0]*12
                        for k, v in lst:
                            if isinstance(k, str):
                                k_key = k.strip()[:3].title()
                                if k_key not in MONTH_LABELS:
                                    try:
                                        idx = int(k) - 1
                                    except Exception:
                                        raise ValueError(f"Unrecognized month key: {k}")
                                else:
                                    idx = MONTH_LABELS.index(k_key)
                            else:
                                idx = int(k) - 1
                            arr[idx] = float(v)
                        values = arr
                    else:
                        raise ValueError("Iterable input must be length 12 or an iterable of (month, value) pairs.")
            else:
                raise ValueError("Unsupported data type for 'data' parameter.")
        except TypeError:
            raise ValueError("Unsupported data type for 'data' parameter.")

    # At this point we should have 12 values
    if values is None or len(values) != 12:
        raise ValueError("Could not interpret input data as monthly values for 12 months.")

    # Create axes if needed
    if ax is None:
        fig, ax = plt.subplots(figsize=figsize)

    x = list(range(12))
    ax.bar(x, values, color=color)
    ax.set_xticks(x)
    ax.set_xticklabels(MONTH_LABELS)
    ax.set_xlabel('month')
    ax.set_ylabel('value')

    if title is None:
        if year is not None:
            ax.set_title(f'Monthly values — {year}')
    else:
        ax.set_title(title)

    ax.margins(x=0.01)
    ax.set_ylim(bottom=0)  # optional; remove if negative values allowed

    if show:
        plt.show()

    return ax
