from urllib import request, error

def _normalize_string_to_ascii(s):
    """Normalize a single string to ASCII using NFKD and dropping non-ASCII chars."""
    if s is None:
        return None
    if not isinstance(s, str):
        # Only process actual Python str objects
        return s
    normalized = unicodedata.normalize("NFKD", s)
    return normalized.encode("ascii", "ignore").decode("ascii")

def _normalize_value(value):
    """Recursively normalize strings inside JSON-like structures to ASCII.
    Normalizes dict keys (converted to strings), list/tuple items, and plain strings.
    Leaves numbers, booleans, and None intact."""
    if isinstance(value, str):
        return _normalize_string_to_ascii(value)
    if isinstance(value, dict):
        new_dict = {}
        for k, v in value.items():
            # Normalize key to string then to ASCII
            if not isinstance(k, str):
                key_str = str(k)
            else:
                key_str = k
            norm_key = _normalize_string_to_ascii(key_str)
            new_dict[norm_key] = _normalize_value(v)
        return new_dict
    if isinstance(value, list):
        return [_normalize_value(item) for item in value]
    if isinstance(value, tuple):
        return tuple(_normalize_value(item) for item in value)
    # Numbers, booleans, None, etc.
    return value

def fetch_and_normalize_github_user(username, token=None, timeout=10):
    """Fetch GitHub user data for `username`, normalize all strings to ASCII, and return a dict.

    Parameters:
    - username: GitHub username (string)
    - token: optional GitHub token (string). If provided, used in Authorization header.
    - timeout: request timeout in seconds (default 10)

    Returns:
    - dict with the normalized user data (strings and keys normalized to ASCII)

    Raises:
    - urllib.error.HTTPError for HTTP errors (e.g., 404 if user not found)
    - urllib.error.URLError for network issues
    - ValueError for JSON decoding errors
    """
    if not isinstance(username, str) or not username:
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"
    headers = {
        "User-Agent": "github-user-normalizer-example/1.0",
        "Accept": "application/vnd.github.v3+json",
    }
    if token:
        headers["Authorization"] = f"token {token}"

    req = request.Request(url, headers=headers, method="GET")
    try:
        with request.urlopen(req, timeout=timeout) as resp:
            charset = resp.headers.get_content_charset() or "utf-8"
            raw = resp.read().decode(charset)
    except error.HTTPError as e:
        # Re-raise so caller can handle. You can inspect e.code and e.read() for details.
        raise
    except error.URLError:
        # Network error (DNS, connection, timeout)
        raise

    try:
        data = json.loads(raw)
    except json.JSONDecodeError as e:
        raise ValueError(f"Failed to decode JSON response: {e}") from e

    normalized = _normalize_value(data)
    return normalized

