def get_normalized_github_user(username: str, token: Optional[str] = None, timeout: int = 10) -> Dict[str, Any]:
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary with the normalized data.

    Parameters:
    - username: GitHub username (str)
    - token: optional GitHub personal access token to increase rate limits (str or None)
    - timeout: request timeout in seconds (int)

    Returns:
    - dict with the same structure as the GitHub API response, but all string values (and string keys)
      normalized to ASCII.

    Raises:
    - requests.HTTPError for non-200 responses
    - requests.RequestException for network issues
    - ValueError for invalid username input
    """
    if not username or not isinstance(username, str):
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"

    headers = {"Accept": "application/vnd.github.v3+json"}
    if token:
        headers["Authorization"] = f"token {token}"

    resp = requests.get(url, headers=headers, timeout=timeout)
    try:
        resp.raise_for_status()
    except requests.HTTPError:
        # Include response body message if available for clearer errors
        message = ""
        try:
            message = resp.json()
        except Exception:
            message = resp.text
        raise requests.HTTPError(f"GitHub API request failed: {resp.status_code} - {message}")

    data = resp.json()

    def _to_ascii(s: str) -> str:
        # Normalize to NFKD then drop non-ASCII bytes
        normalized = unicodedata.normalize("NFKD", s)
        return normalized.encode("ascii", "ignore").decode("ascii")

    def _normalize(obj: Any) -> Any:
        # Recursively normalize strings inside dicts, lists, tuples, and sets.
        if isinstance(obj, str):
            return _to_ascii(obj)
        if isinstance(obj, bytes):
            # decode bytes and normalize
            try:
                decoded = obj.decode("utf-8", errors="replace")
            except Exception:
                decoded = str(obj)
            return _to_ascii(decoded)
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                # Normalize keys (convert non-str keys to str first)
                if isinstance(k, str):
                    new_key = _to_ascii(k)
                else:
                    new_key = _to_ascii(str(k))
                new_dict[new_key] = _normalize(v)
            return new_dict
        if isinstance(obj, list):
            return [_normalize(x) for x in obj]
        if isinstance(obj, tuple):
            return tuple(_normalize(x) for x in obj)
        if isinstance(obj, set):
            # sets are converted to list to preserve JSON-serializable structure
            return [_normalize(x) for x in obj]
        # Non-string scalars (int, float, bool, None) are returned unchanged
        return obj

    normalized_data = _normalize(data)
    return normalized_data

