def task_func(lst, reps):
    """
    Calculate the mode of a list repeated `reps` times, using flattened_mode if available.
    Returns a ModeResult-like namedtuple with fields: mode, count (both as numpy arrays if numpy available).
    Example:
        >>> task_func([1, 2, 3], 5)
        ModeResult(mode=array([1]), count=array([5]))
    """
    # Helper: recursive flatten for lists/tuples
    def _flatten(seq):
        for el in seq:
            if isinstance(el, (list, tuple)):
                for sub in _flatten(el):
                    yield sub
            else:
                yield el

    # Build repeated sequence
    if reps is None:
        raise ValueError("reps must be provided")
    try:
        reps = int(reps)
    except Exception:
        raise ValueError("reps must be an integer")

    if reps <= 0:
        # empty repetition => no elements
        repeated = []
    else:
        # repeating the top-level list
        repeated = lst * reps

    flattened = list(_flatten(repeated))

    # If flattened_mode is available, prefer it
    try:
        import flattened_mode as fm  # attempt to use requested library
        # Attempt to call fm.mode on the flattened data
        # Convert flattened to a simple list or array depending on what fm expects
