            return result
        except Exception:
            # If fm.mode fails for some reason, fall back to our implementation
            pass
    except Exception:
        # library not available: fall back
        pass

    # Fallback implementation: compute mode(s) and counts
    ModeResult = namedtuple('ModeResult', ['mode', 'count'])

    if not flattened:
        # return empty arrays if no data
        try:
            import numpy as np
            return ModeResult(mode=np.array([], dtype=object), count=np.array([], dtype=int))
        except Exception:
            return ModeResult(mode=[], count=[])

    counts = Counter(flattened)
    max_count = max(counts.values())
    modes = [val for val, c in counts.items() if c == max_count]

    # Try to return numpy arrays like the example; if numpy not available, return lists
    try:
        import numpy as np
        # preserve original dtype where possible
        mode_arr = np.array(modes, dtype=object) if len(modes) != 0 else np.array([], dtype=object)
        count_arr = np.array([max_count] * len(modes), dtype=int)
        return ModeResult(mode=mode_arr, count=count_arr)
    except Exception:
        return ModeResult(mode=modes, count=[max_count] * len(modes))
