from datetime import datetime, timezone
from typing import Optional, Tuple

# Try to import zoneinfo (Python 3.9+); fall back to pytz if needed
try:
    from zoneinfo import ZoneInfo  # type: ignore
    _ZONEINFO = "zoneinfo"
except Exception:
    try:
        import pytz  # type: ignore
        ZoneInfo = None
        _ZONEINFO = "pytz"
    except Exception:
        raise ImportError(
            "No timezone library available: zoneinfo (Py3.9+) not present and pytz not installed."
        )


def convert_and_diff(
    date_str: str,
    from_tz: str,
    to_tz: str,
    fmt: Optional[str] = None,
) -> Tuple[str, float]:
    """
    Convert a date string from one time zone to another and return the converted
    datetime (ISO 8601 string with offset) and the time difference in seconds
    between the converted time and the current time in the destination time zone.

    Parameters:
    - date_str: input date/time string.
    - from_tz: IANA time zone name for the input time (e.g. "America/New_York").
    - to_tz: IANA time zone name for the output time (e.g. "Europe/London").
    - fmt: optional strptime format to parse date_str. If None, the function will
           try datetime.fromisoformat and handle a trailing 'Z' (UTC). If the
           parsed datetime includes a timezone offset, that offset is honored
           and from_tz will be ignored.

    Returns:
    - (converted_iso_str, diff_seconds)
      converted_iso_str: ISO 8601 string including offset in destination tz
      diff_seconds: (converted_time - now_in_destination_tz) in seconds (float;
                    positive if converted_time is in the future)
    """
    # Helper to make aware datetime in a zone
    def _make_aware(dt_naive: datetime, tz_name: str) -> datetime:
        if _ZONEINFO == "zoneinfo":
            try:
                return dt_naive.replace(tzinfo=ZoneInfo(tz_name))
            except Exception as e:
                raise ValueError(f"Invalid time zone name '{tz_name}': {e}")
        else:  # pytz fallback
            try:
                tz = pytz.timezone(tz_name)
            except Exception as e:
                raise ValueError(f"Invalid time zone name '{tz_name}': {e}")
            return tz.localize(dt_naive)

    def _astimezone(dt_aware: datetime, tz_name: str) -> datetime:
        if _ZONEINFO == "zoneinfo":
            try:
                return dt_aware.astimezone(ZoneInfo(tz_name))
            except Exception as e:
                raise ValueError(f"Invalid time zone name '{tz_name}': {e}")
        else:
            try:
                tz = pytz.timezone(tz_name)
            except Exception as e:
                raise ValueError(f"Invalid time zone name '{tz_name}': {e}")
            return dt_aware.astimezone(tz)

    # Parse input
    if fmt:
        # parse as naive then attach from_tz
        dt = datetime.strptime(date_str, fmt)
        dt_from = _make_aware(dt, from_tz)
    else:
        # try ISO parsing and handle 'Z' (UTC) if present
        ds = date_str.strip()
        if ds.endswith("Z"):
            # replace trailing Z with +00:00 to satisfy fromisoformat
            ds = ds[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(ds)
        except Exception:
            # fallback: try common formats
            for trial_fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
                try:
                    dt = datetime.strptime(date_str, trial_fmt)
                    break
                except Exception:
                    dt = None
            if dt is None:
                raise ValueError(
                    "date_str couldn't be parsed. Provide an explicit fmt or use ISO-8601."
                )

        if dt.tzinfo is None:
            # no tz info in parsed string -> treat as from_tz
            dt_from = _make_aware(dt, from_tz)
        else:
            # input had offset tzinfo; use it (ignore from_tz)
            dt_from = dt

    # Convert to destination tz
    dt_dest = _astimezone(dt_from, to_tz)

    # Current time in destination tz
    if _ZONEINFO == "zoneinfo":
        now_dest = datetime.now(ZoneInfo(to_tz))
    else:
        now_dest = datetime.now(pytz.timezone(to_tz))

    diff_seconds = (dt_dest - now_dest).total_seconds()

    # Return ISO 8601 with offset
    # Use datetime.isoformat() which includes offset when tz-aware
    return dt_dest.isoformat(), diff_seconds


# Example usages:
if __name__ == "__main__":
    # Example 1: explicit format, naive input interpreted as America/New_York
    converted, diff = convert_and_diff("2026-05-08 15:30:00", "America/New_York", "Europe/London", fmt="%Y-%m-%d %H:%M:%S")
    print("Converted:", converted)
    print("Seconds difference:", diff)

    # Example 2: ISO string with offset (from_tz ignored because the string contains offset)
    converted2, diff2 = convert_and_diff("2026-05-08T15:30:00-04:00", "America/New_York", "Asia/Tokyo")
    print("Converted 2:", converted2)
    print("Seconds difference 2:", diff2)
