        raise ValueError(f"Invalid timezone name '{tz_name}': {e}")

    # Make dt timezone-aware: assume naive input is local time in tz_name
    if dt.tzinfo is None:
        # zoneinfo.ZoneInfo supports direct replace(tzinfo=...)
        # pytz prefers localize
        try:
            # For ZoneInfo and many tz implementations this works
            dt = dt.replace(tzinfo=tz)
        except Exception:
            if hasattr(tz, "localize"):
                dt = tz.localize(dt)
            else:
                dt = dt.replace(tzinfo=tz)
    else:
        # Convert to requested timezone
        try:
            dt = dt.astimezone(tz)
        except Exception:
            # Fallback: attach tz directly (best-effort)
            dt = dt.replace(tzinfo=tz)

    # Compute the next local Jan 1 midnight
    target_year = dt.year + 1
    # Build the target aware datetime
    try:
        target = datetime(target_year, 1, 1, 0, 0, 0, tzinfo=tz)
    except Exception:
        naive_target = datetime(target_year, 1, 1, 0, 0, 0)
        if hasattr(tz, "localize"):
            target = tz.localize(naive_target)
        else:
            target = naive_target.replace(tzinfo=tz)

    if dt >= target:
        # If already at/after (e.g. dt exactly at Jan 1 00:00:00), pick the next year
        target_year += 1
        try:
            target = datetime(target_year, 1, 1, 0, 0, 0, tzinfo=tz)
        except Exception:
            naive_target = datetime(target_year, 1, 1, 0, 0, 0)
            if hasattr(tz, "localize"):
                target = tz.localize(naive_target)
            else:
                target = naive_target.replace(tzinfo=tz)

    delta = target - dt
    # total_seconds may be fractional; return a non-negative float
    return max(0.0, delta.total_seconds())


