if __name__ == "__main__":
    print(seconds_until_new_year("2025-12-31T23:00:00", "Europe/Berlin"))   # seconds until 2026-01-01 00:00 Europe/Berlin
    print(seconds_until_new_year("2025-07-01", "America/New_York"))         # seconds until 2026-01-01 00:00 America/New_York
    # With explicit format:
    print(seconds_until_new_year("2025-12-31 23:59:30", "UTC", fmt="%Y-%m-%d %H:%M:%S"))
