import csv
import math
import statistics
from typing import List, Optional, Union, Tuple, Dict

def normalize_csv_file(
    input_path: str,
    output_path: Optional[str] = None,
    method: str = "minmax",
    columns: Optional[Union[List[Union[str,int]], str, int]] = None,
    fill_missing: Union[str, float] = "mean",
    fill_value: Optional[float] = None,
    skip_non_numeric: bool = True,
    float_format: str = "{:.6f}",
    delimiter: str = ",",
    quotechar: str = '"',
    encoding: str = "utf-8"
) -> Tuple[List[List[str]], Dict[str, Dict[str, float]]]:
    """
    Normalize numeric columns in a CSV file.

    Parameters:
    - input_path: path to input CSV file.
    - output_path: if provided, writes normalized CSV to this path; if None, does not write.
    - method: 'minmax' or 'zscore'.
    - columns: None (auto-detect numeric columns) or list of column names or indices to normalize.
               If a single name or index is provided it will be accepted too.
    - fill_missing:
        - 'mean', 'median', 'zero', 'min', 'max', 'drop', or a numeric value.
        - If 'drop', rows with missing values in the target columns are dropped.
        - If you want a custom numeric value, pass it directly (e.g. fill_missing=0.5).
    - fill_value: alternative; when fill_missing == 'value', specify the numeric value here.
    - skip_non_numeric: if True, skip columns with non-numeric content unless explicitly listed.
    - float_format: format string for floats in output.
    - delimiter, quotechar, encoding: CSV reading/writing options.

    Returns:
    - normalized_rows: all rows (including header) as lists of strings (after normalization).
    - stats: dictionary mapping column name -> stats used (min, max, mean, stdev, median).
    """

    # Normalize parameters
    if isinstance(columns, (str, int)):
        columns = [columns]

    if method not in ("minmax", "zscore"):
        raise ValueError("method must be 'minmax' or 'zscore'")

    # Read CSV
    with open(input_path, newline='', encoding=encoding) as f:
        reader = csv.reader(f, delimiter=delimiter, quotechar=quotechar)
        rows = list(reader)

    if not rows:
        raise ValueError("Input CSV is empty")

    header = rows[0]
    data_rows = rows[1:]

    n_cols = len(header)

    # Map columns argument to indices
    col_indices_to_process = set()

    if columns is not None:
        for col in columns:
            if isinstance(col, int):
                if col < 0:
                    # allow negative indexing like Python lists
                    col_idx = n_cols + col
                else:
                    col_idx = col
                if not (0 <= col_idx < n_cols):
                    raise IndexError(f"Column index {col} out of range")
                col_indices_to_process.add(col_idx)
            elif isinstance(col, str):
                if col not in header:
                    raise ValueError(f"Column name '{col}' not found in header")
                col_indices_to_process.add(header.index(col))
            else:
                raise TypeError("columns list must contain ints or strs (names)")

    # Helper to attempt float conversion
    def try_float(s: str):
        if s is None:
            return None
        s = s.strip()
        if s == "":
            return None
        try:
            return float(s)
        except Exception:
            return None

    # Auto-detect numeric columns if columns is None
    if columns is None:
        for j in range(n_cols):
            all_numeric = True
            found_any = False
            for row in data_rows:
                if j >= len(row):
                    # treat missing cell as non-numeric for detection
                    continue
                val = try_float(row[j])
                if val is None:
                    # empty is okay (we can fill later), but if some rows contain non-numeric text, mark non-numeric
                    cell = row[j].strip()
                    if cell != "":
                        all_numeric = False
                        break
                else:
                    found_any = True
            if all_numeric and found_any:
                col_indices_to_process.add(j)

    # Gather numeric values per column
    col_values = {j: [] for j in col_indices_to_process}
    for row in data_rows:
        for j in list(col_indices_to_process):
            if j >= len(row):
                # missing cell
                continue
            v = try_float(row[j])
            if v is not None:
                col_values[j].append(v)

    # If skip_non_numeric True and a selected column has no numeric values, remove it
    if skip_non_numeric:
        for j in list(col_indices_to_process):
            if len(col_values.get(j, [])) == 0:
                col_indices_to_process.discard(j)

    # Compute stats
    stats = {}
    for j in col_indices_to_process:
        vals = col_values.get(j, [])
        if len(vals) == 0:
            # no numeric values to compute stats
            stats[header[j]] = {"min": None, "max": None, "mean": None, "stdev": None, "median": None}
            continue
        mn = min(vals)
        mx = max(vals)
        mean = statistics.mean(vals)
        median = statistics.median(vals)
        stdev = statistics.pstdev(vals) if len(vals) == 1 else statistics.stdev(vals)
        stats[header[j]] = {"min": mn, "max": mx, "mean": mean, "stdev": stdev, "median": median}

    # Function to get fill value per column
    def get_fill(j):
        if isinstance(fill_missing, (int, float)):
            return float(fill_missing)
        if fill_missing == "value":
            if fill_value is None:
                raise ValueError("fill_value must be provided when fill_missing == 'value'")
            return float(fill_value)
        if fill_missing == "mean":
            m = stats[header[j]]["mean"]
            if m is None:
                return 0.0
            return m
        if fill_missing == "median":
            m = stats[header[j]]["median"]
            if m is None:
                return 0.0
            return m
        if fill_missing == "zero":
            return 0.0
        if fill_missing == "min":
            m = stats[header[j]]["min"]
            return 0.0 if m is None else m
        if fill_missing == "max":
            m = stats[header[j]]["max"]
            return 0.0 if m is None else m
        if fill_missing == "drop":
            return None
        # If it's an unrecognized string, try to parse as float
        try:
            return float(fill_missing)
        except Exception:
            raise ValueError(f"Unsupported fill_missing: {fill_missing}")

    # If drop, filter rows with missing in any selected column
    if fill_missing == "drop":
        filtered_rows = []
        for row in data_rows:
            drop_row = False
            for j in col_indices_to_process:
                if j >= len(row):
                    drop_row = True
                    break
                if try_float(row[j]) is None:
                    cell = row[j].strip()
                    if cell == "":
                        drop_row = True
                        break
                    else:
                        # non-numeric content -> also drop
                        drop_row = True
                        break
            if not drop_row:
                filtered_rows.append(row)
        data_rows = filtered_rows

    # Now build normalized rows
    normalized_rows = [header[:]]  # include header
    for row in data_rows:
        new_row = list(row)  # copy
        # ensure row has same number of columns (pad with empty strings if necessary)
        if len(new_row) < n_cols:
            new_row.extend([""] * (n_cols - len(new_row)))
        for j in col_indices_to_process:
            raw_cell = new_row[j] if j < len(new_row) else ""
            val = try_float(raw_cell)
            if val is None:
                # need to fill
                fv = get_fill(j)
                if fv is None:
                    # should not happen except when fill_missing == 'drop' handled earlier
                    out_str = ""
                else:
                    x = fv
                    # apply normalization to filled value
                    s = stats[header[j]]
                    if method == "minmax":
                        mn = s["min"]
                        mx = s["max"]
                        if mn is None or mx is None or mx == mn:
                            norm = 0.0
                        else:
                            norm = (x - mn) / (mx - mn)
                    else:  # zscore
                        st = s["stdev"]
                        if st is None or st == 0:
                            norm = 0.0
                        else:
                            norm = (x - s["mean"]) / st
                    out_str = float_format.format(norm)
            else:
                # numeric -> normalize
                s = stats[header[j]]
                if method == "minmax":
                    mn = s["min"]
                    mx = s["max"]
                    if mn is None or mx is None or mx == mn:
                        norm = 0.0
                    else:
                        norm = (val - mn) / (mx - mn)
                else:  # zscore
                    st = s["stdev"]
                    if st is None or st == 0:
                        norm = 0.0
                    else:
                        norm = (val - s["mean"]) / st
                out_str = float_format.format(norm)
            new_row[j] = out_str
        normalized_rows.append(new_row)

    # Write output file if requested
    if output_path is not None:
        with open(output_path, "w", newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter, quotechar=quotechar, quoting=csv.QUOTE_MINIMAL)
            for r in normalized_rows:
                writer.writerow(r)

    return normalized_rows, stats

