Code:

```python
import csv
import math
import statistics
from typing import Optional, Iterable, List

def normalize_csv(
    input_path: str,
    output_path: Optional[str] = None,
    method: str = "minmax",
    columns: Optional[Iterable[str]] = None,
    missing_strategy: str = "ignore",
    delimiter: str = ",",
    missing_values: Optional[Iterable[str]] = None,
) -> str:
    """
    Normalize numeric columns in a CSV file and write the result to output_path (or overwrite input if output_path is None).

    Parameters:
    - input_path: path to input CSV file
    - output_path: path to write normalized CSV. If None, input file will be overwritten.
    - method: 'minmax' (scale values to [0,1]) or 'zscore' (mean 0, std 1)
    - columns: iterable of column names to normalize. If None, automatically detect numeric columns.
    - missing_strategy: how to handle missing numeric values:
        'ignore' - leave missing cells blank in output (no imputation)
        'mean'   - replace missing numeric values with column mean (computed ignoring missing)
        'median' - replace missing numeric values with column median
        'drop'   - drop any row that has a missing numeric value in a column that is being normalized
    - delimiter: CSV delimiter (default ',')
    - missing_values: iterable of string tokens to treat as missing (default: '', 'NA', 'N/A', 'nan', 'null')

    Returns:
    - the path to the written CSV file (output_path or input_path if overwritten)

    Notes:
    - Non-numeric columns are copied unchanged.
    - Strings that can be parsed as floats are treated as numeric values.
    - Constant columns (min == max) are set to 0.0 in minmax normalization.
    """

    if method not in ("minmax", "zscore"):
        raise ValueError("method must be 'minmax' or 'zscore'")
    if missing_strategy not in ("ignore", "mean", "median", "drop"):
        raise ValueError("missing_strategy must be one of 'ignore', 'mean', 'median', 'drop'")

    if missing_values is None:
        missing_values = {"", "NA", "N/A", "nan", "NaN", "null", "None"}

    missing_values = set(missing_values)

    # Read full CSV into memory (suitable for moderate-sized files)
    with open(input_path, newline="", encoding="utf-8") as f:
        reader = csv.reader(f, delimiter=delimiter)
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError("Input CSV is empty")
        rows = [row for row in reader]

    # Ensure rows are all same length as header by padding/truncating
    ncols = len(header)
    normalized_rows: List[List[str]] = []
    for r in rows:
        if len(r) < ncols:
            r = r + [""] * (ncols - len(r))
        elif len(r) > ncols:
            r = r[:ncols]
        normalized_rows.append(r)

    # Map header to column index
    col_index = {name: i for i, name in enumerate(header)}

    # Determine which columns to normalize
    if columns is None:
        # auto-detect numeric columns: a column is numeric if at least one non-missing cell parses as float,
        # and at least 80% of non-missing cells are parseable as float (to avoid e.g. ID columns)
        candidates = []
        for j, name in enumerate(header):
            non_missing = []
            convertible = 0
            total_non_missing = 0
            for row in normalized_rows:
                val = row[j].strip()
                if val in missing_values:
                    continue
                total_non_missing += 1
                try:
                    _ = float(val)
                    convertible += 1
                    non_missing.append(float(val))
                except Exception:
                    pass
            if total_non_missing == 0:
                # no data -> not numeric
                continue
            if convertible >= max(1, int(0.8 * total_non_missing)):
                candidates.append(name)
        target_cols = candidates
    else:
        target_cols = list(columns)
        for c in target_cols:
            if c not in col_index:
                raise ValueError(f"Requested column '{c}' not found in CSV header")

    target_idxs = [col_index[c] for c in target_cols]

    # Build numeric values per target column (skip missing tokens and unparsable entries)
    col_values = {idx: [] for idx in target_idxs}
    for row in normalized_rows:
        for idx in target_idxs:
            val = row[idx].strip()
            if val in missing_values:
                continue
            try:
                f = float(val)
                if math.isfinite(f):
                    col_values[idx].append(f)
            except Exception:
                # treat unparsable as missing
                continue

    # If dropping rows with missing numeric values, compute which rows to keep
    if missing_strategy == "drop":
        kept_rows = []
        for row in normalized_rows:
            drop = False
            for idx in target_idxs:
                val = row[idx].strip()
                if val in missing_values:
                    drop = True
                    break
                try:
                    f = float(val)
                    if not math.isfinite(f):
                        drop = True
                        break
                except Exception:
                    drop = True
                    break
            if not drop:
                kept_rows.append(row)
        normalized_rows = kept_rows

    # Recompute col_values if rows were dropped
    if missing_strategy == "drop":
        col_values = {idx: [] for idx in target_idxs}
        for row in normalized_rows:
            for idx in target_idxs:
                val = row[idx].strip()
                if val in missing_values:
                    continue
                try:
                    f = float(val)
                    if math.isfinite(f):
                        col_values[idx].append(f)
                except Exception:
                    continue

    # Compute imputation values if needed
    impute_vals = {}
    for idx in target_idxs:
        vals = col_values[idx]
        if len(vals) == 0:
            # No numeric data: impute zero
            impute_vals[idx] = 0.0
        else:
            if missing_strategy == "mean":
                impute_vals[idx] = statistics.mean(vals)
            elif missing_strategy == "median":
                impute_vals[idx] = statistics.median(vals)
            else:
                impute_vals[idx] = None  # not used for 'ignore' or 'drop'

    # Compute normalization parameters
    params = {}
    for idx in target_idxs:
        vals = col_values[idx]
        if len(vals) == 0:
            params[idx] = {"min": 0.0, "max": 0.0, "mean": 0.0, "std": 1.0}
            continue
        vmin = min(vals)
        vmax = max(vals)
        mean = statistics.mean(vals)
        if len(vals) > 1:
            # population vs sample std? use sample stdev when len>1
            try:
                std = statistics.stdev(vals)
            except statistics.StatisticsError:
                std = 0.0
        else:
            std = 0.0
        params[idx] = {"min": vmin, "max": vmax, "mean": mean, "std": std}

    # Apply normalization
    out_rows = []
    for row in normalized_rows:
        new_row = list(row)  # copy
        for idx in target_idxs:
            raw = row[idx].strip()
            if raw in missing_values or raw == "":
                if missing_strategy in ("mean", "median"):
                    impute = impute_vals[idx]
                    x = float(impute)
                elif missing_strategy == "ignore":
                    new_row[idx] = ""
                    continue
                else:
                    # should not get here for 'drop' because rows were dropped earlier
                    new_row[idx] = ""
                    continue
            else:
                try:
                    x = float(raw)
                except Exception:
                    # unparsable -> treat as missing according to strategy
                    if missing_strategy in ("mean", "median"):
                        x = float(impute_vals[idx])
                    elif missing_strategy == "ignore":
                        new_row[idx] = ""
                        continue
                    else:
                        new_row[idx] = ""
                        continue

            p = params[idx]
            if method == "minmax":
                vmin = p["min"]
                vmax = p["max"]
                if vmax == vmin:
                    # constant column => set to 0.0
                    scaled = 0.0
                else:
                    scaled = (x - vmin) / (vmax - vmin)
            else:  # zscore
                std = p["std"]
                mean = p["mean"]
                if std == 0:
                    scaled = 0.0
                else:
                    scaled = (x - mean) / std

            # format numeric value; using repr would give more precision but here use simple str
            # keep consistent numeric formatting
            if math.isnan(scaled) or not math.isfinite(scaled):
                new_row[idx] = ""
            else:
                # use a reasonably compact representation
                new_row[idx] = ("{:.6f}".format(scaled)).rstrip("0").rstrip(".") if abs(scaled) >= 1e-6 else "0"
        out_rows.append(new_row)

    # Write output CSV
    if output_path is None:
        output_path = input_path

    with open(output_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f, delimiter=delimiter)
        writer.writerow(header)
        writer.writerows(out_rows)

    return output_path
