```python
import csv
import os
import statistics
from typing import Optional, Tuple

def normalize_csv_file(
    input_path: str,
    output_path: Optional[str] = None,
    method: str = "minmax",
    missing_strategy: str = "mean",
    delimiter: str = ",",
    float_precision: int = 6,
) -> str:
    """
    Normalize numeric columns in a CSV file.
    - Tries to use the 'csv_data_normalizer' library if installed; otherwise uses an internal implementation.
    - Numeric columns are detected automatically: a column is numeric if every non-empty cell can be parsed to float.
    - method: 'minmax' (scale to [0,1]) or 'zscore' (mean 0, std 1).
    - missing_strategy: 'mean', 'median', 'drop', or 'keep'
        - 'mean'/'median': replace missing numeric values with column mean/median before scaling
        - 'drop': drop any row that has a missing value in a numeric column
        - 'keep': leave missing values blank in output (they are ignored when computing statistics)
    - delimiter: CSV delimiter (default ',')
    - float_precision: number of decimal places for output floats
    Returns the path to the output CSV file.

    Example:
        out = normalize_csv_file("data.csv", method="zscore", missing_strategy="median")
    """
    # First, try to use csv_data_normalizer if available.
    try:
        import csv_data_normalizer as cdn  # type: ignore

        # Best-effort attempt: use a common-sounding API if present.
        # We don't assume a particular API; if the import succeeds but no usable function is found,
        # fall back to the internal implementation below.
        if hasattr(cdn, "normalize_csv"):
            # If the library provides similar parameters, this will work.
            # We attempt to call it and return its result, otherwise we'll fall back.
            try:
                result = cdn.normalize_csv(
                    input_path,
                    output_path=output_path,
                    method=method,
                    missing_strategy=missing_strategy,
                    delimiter=delimiter,
                    float_precision=float_precision,
                )
                # If the library returns a path or writes the file, we assume success.
                if isinstance(result, str):
                    return result
                # If it doesn't return a path, assume it wrote to output_path or raised an error.
                if output_path:
                    return output_path
            except Exception:
                # If the library call fails for any reason, fall back to built-in implementation below.
                pass
        # If import succeeded but we couldn't use it, proceed to fallback.
    except Exception:
        # Library not installed or import failed: use fallback implementation.
        pass

    # ---------- Fallback internal implementation ----------
    if method not in ("minmax", "zscore"):
        raise ValueError("method must be 'minmax' or 'zscore'")
    if missing_strategy not in ("mean", "median", "drop", "keep"):
        raise ValueError("missing_strategy must be one of 'mean', 'median', 'drop', 'keep'")

    if not os.path.isfile(input_path):
        raise FileNotFoundError(f"Input file not found: {input_path}")

    if output_path is None:
        base, ext = os.path.splitext(input_path)
        output_path = f"{base}_normalized{ext or '.csv'}"

    # Read CSV into list of dicts
    with open(input_path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f, delimiter=delimiter)
        fieldnames = reader.fieldnames if reader.fieldnames is not None else []
        rows = [row for row in reader]

    if not fieldnames:
        # Empty or headerless CSV
        with open(output_path, "w", newline="", encoding="utf-8") as fout:
            fout.write("")  # create empty file
        return output_path

    # Detect numeric columns: a column is numeric if every non-empty cell can be parsed as float
    numeric_cols = []
    for col in fieldnames:
        is_numeric = True
        for r in rows:
            v = r.get(col, "")
            if v is None:
                v = ""
            v = v.strip()
            if v == "":
                continue
            try:
                float(v)
            except Exception:
                is_numeric = False
                break
        if is_numeric:
            numeric_cols.append(col)

    # Build numeric values per column (excluding missing entries)
    numeric_values = {col: [] for col in numeric_cols}
    for r in rows:
        for col in numeric_cols:
            v = r.get(col, "")
            if v is None:
                v = ""
            v = v.strip()
            if v == "":
                continue
            try:
                numeric_values[col].append(float(v))
            except Exception:
                # skip unparsable (shouldn't happen due to detection step)
                continue

    # Optionally drop rows with missing numeric values
    if missing_strategy == "drop":
        new_rows = []
        for r in rows:
            has_missing = False
            for col in numeric_cols:
                v = r.get(col, "")
                if v is None:
                    v = ""
                if v.strip() == "":
                    has_missing = True
                    break
            if not has_missing:
                new_rows.append(r)
        rows = new_rows

    # Compute imputations if needed
    impute_values = {}
    if missing_strategy in ("mean", "median"):
        for col in numeric_cols:
            vals = numeric_values.get(col, [])
            if not vals:
                impute_values[col] = 0.0
            else:
                if missing_strategy == "mean":
                    impute_values[col] = statistics.mean(vals)
                else:
                    impute_values[col] = statistics.median(vals)

        # Apply imputation to rows and update numeric_values to include imputed values
        for r in rows:
            for col in numeric_cols:
                v = r.get(col, "")
                if v is None:
                    v = ""
                if v.strip() == "":
                    r[col] = format(impute_values[col], f".{float_precision}f")
                    numeric_values[col].append(impute_values[col])

    # Recompute stats needed for normalization (after imputation if performed)
    col_stats = {}
    for col in numeric_cols:
        vals = numeric_values.get(col, [])
        if not vals:
            # If no observed values, set trivial stats
            col_stats[col] = {"min": 0.0, "max": 0.0, "mean": 0.0, "std": 0.0}
            continue
        col_min = min(vals)
        col_max = max(vals)
        col_mean = statistics.mean(vals)
        col_std = statistics.pstdev(vals) if len(vals) > 1 else 0.0
        col_stats[col] = {"min": col_min, "max": col_max, "mean": col_mean, "std": col_std}

    # Function to normalize a single value (string); returns formatted string or blank for missing when 'keep'
    def normalize_value(col: str, raw: str) -> str:
        s = raw.strip() if raw is not None else ""
        if s == "":
            if missing_strategy == "keep":
                return ""
            # For 'drop' we eliminated missing rows earlier; for 'mean'/'median' we've imputed them already
            # So blank shouldn't happen here except in 'keep'
            return ""
        try:
            x = float(s)
        except Exception:
            # If for some reason unparsable, keep original
            return raw
        stats = col_stats[col]
        if method == "minmax":
            lo, hi = stats["min"], stats["max"]
            if hi == lo:
                norm = 0.0
            else:
                norm = (x - lo) / (hi - lo)
        else:  # zscore
            std = stats["std"]
            mean = stats["mean"]
            if std == 0:
                norm = 0.0
            else:
                norm = (x - mean) / std
        # Format numeric output
        return format(norm, f".{float_precision}f")

    # Create output rows (copy to avoid mutating original row objects)
    out_rows = []
    for r in rows:
        out_r = dict(r)  # shallow copy
        for col in numeric_cols:
            raw = out_r.get(col, "")
            # If we used imputation, the cell may already be a string representation of the imputed value;
            # normalize_value will parse it regardless.
            if raw is None:
                raw = ""
            normed = normalize_value(col, str(raw))
            out_r[col] = normed
        out_rows.append(out_r)

    # Write out CSV
    with open(output_path, "w", newline="", encoding="utf-8") as fout:
        writer = csv.DictWriter(fout, fieldnames=fieldnames, delimiter=delimiter, extrasaction="ignore")
        writer.writeheader()
        for r in out_rows:
            # Ensure every fieldname present
            row_to_write = {fn: (r.get(fn, "") if r.get(fn, "") is not None else "") for fn in fieldnames}
            writer.writerow(row_to_write)

    return output_path
```

Notes:
- Default normalization is min-max to [0,1]. Use method="zscore" for standardization.
- missing_strategy behavior:
  - mean/median: imputes missing numeric cells then normalizes.
  - drop: removes rows that have any missing numeric cell.
  - keep: leaves missing cells blank and computes stats ignoring missing entries.
- If you do have the csv_data_normalizer package installed and it exposes a normalize_csv function with compatible parameters, the function will try to call it; otherwise it uses the fallback implementation above. If you'd like the function to strictly require that library, remove the fallback and let the import fail.

I couldn't find a real "paired_word_ttest" package in PyPI, so below is a self-contained function that tries to use that library if it happens to be installed, falls back to scipy.stats.ttest_rel if available, and otherwise computes the paired t-statistic itself. If scipy is unavailable and the sample is small (n < 30), the function returns the t-statistic and degrees of freedom but sets p_value to None (because accurate Student's-t p-values require a special function). For n >= 30 it uses a normal approximation for the p-value.

Function: paired_word_length_ttest(s1, s2) — compares corresponding word lengths (so the strings must produce the same number of words). It raises ValueError if the word counts differ.

Copy-paste this into your Python code:

def paired_word_length_ttest(s1: str, s2: str):
    """
    Perform a paired t-test on per-word lengths between two strings.
    - Words are taken as sequences separated by whitespace (re.findall r'\S+').
    - The test is only performed if both strings produce the same number of words;
      otherwise a ValueError is raised.
    - The function will try (in order):
        1) to use an installed `paired_word_ttest` package if present (tries
           common function names).
        2) to use scipy.stats.ttest_rel if scipy is installed.
        3) to compute the paired t-statistic manually and (if n >= 30) approximate
           the two-sided p-value using the normal approximation. For n < 30 the
           p-value will be returned as None if scipy is unavailable.
    Returns a dict with keys: 't_statistic', 'p_value', 'n', 'df'.
    """
    import re
    import math

    # Tokenize on whitespace
    words1 = re.findall(r"\S+", s1)
    words2 = re.findall(r"\S+", s2)

    if len(words1) != len(words2):
        raise ValueError(f"Strings produce different number of words: {len(words1)} vs {len(words2)}")

    lengths1 = [len(w) for w in words1]
    lengths2 = [len(w) for w in words2]
    n = len(lengths1)
    df = n - 1

    # Try to use paired_word_ttest library if available
    try:
        import paired_word_ttest as pwt  # type: ignore
        # Try a few plausible function names in that library
        if hasattr(pwt, "paired_ttest"):
            res = pwt.paired_ttest(lengths1, lengths2)
            # Assume it returns (t, p) or an object with attributes
            if isinstance(res, tuple) and len(res) >= 2:
                t_stat, p_val = res[0], res[1]
            elif hasattr(res, "statistic") and hasattr(res, "pvalue"):
                t_stat, p_val = res.statistic, res.pvalue
            else:
                # Unknown return format; fall back to scipy/manual
                raise RuntimeError("paired_word_ttest returned unknown result format")
            return {"t_statistic": float(t_stat), "p_value": float(p_val), "n": n, "df": df}
        if hasattr(pwt, "ttest_rel"):
            res = pwt.ttest_rel(lengths1, lengths2)
            if isinstance(res, tuple) and len(res) >= 2:
                t_stat, p_val = res[0], res[1]
            elif hasattr(res, "statistic") and hasattr(res, "pvalue"):
                t_stat, p_val = res.statistic, res.pvalue
            else:
                raise RuntimeError("paired_word_ttest.ttest_rel returned unknown result format")
            return {"t_statistic": float(t_stat), "p_value": float(p_val), "n": n, "df": df}
        # If the library exists but we can't find a usable API, fall through to scipy/manual
    except Exception:
        # If import fails or any error occurs with that library, continue to fallbacks
        pass

    # Try scipy
    try:
        from scipy import stats  # type: ignore
        t_stat, p_val = stats.ttest_rel(lengths1, lengths2)
        return {"t_statistic": float(t_stat), "p_value": float(p_val), "n": n, "df": df}
    except Exception:
        # SciPy not available or call failed; compute manually
        diffs = [a - b for a, b in zip(lengths1, lengths2)]
        mean_diff = sum(diffs) / n
        if n == 1:
            # With a single pair, variance is undefined; t is infinite if mean_diff != 0
            if diffs[0] == 0:
                return {"t_statistic": 0.0, "p_value": 1.0, "n": n, "df": df}
            else:
                return {"t_statistic": float("inf"), "p_value": None, "n": n, "df": df}

        # sample standard deviation of diffs
        ss = sum((di - mean_diff) ** 2 for di in diffs)
        s = math.sqrt(ss / (n - 1))
        if s == 0.0:
            # All diffs identical. If mean_diff == 0 then t=0; otherwise t is infinite.
            if mean_diff == 0.0:
                return {"t_statistic": 0.0, "p_value": 1.0, "n": n, "df": df}
            else:
                return {"t_statistic": float("inf"), "p_value": None, "n": n, "df": df}

        se = s / math.sqrt(n)
        t_stat = mean_diff / se

        # For p-value, try normal approximation if sample size is large (n >= 30)
        p_val = None
        if n >= 30:
            # two-sided p-value approx using normal distribution
            # normal cdf via erf
            z = abs(t_stat)
            # normal cdf
            normal_cdf = 0.5 * (1.0 + math.erf(z / math.sqrt(2.0)))
            p_val = 2.0 * (1.0 - normal_cdf)
        # If n < 30 and scipy isn't available we don't compute an accurate t-distribution p-value.
        return {"t_statistic": float(t_stat), "p_value": (None if p_val is None else float(p_val)), "n": n, "df": df}

