    except Exception:
        pass

    # 4) Fallback: heuristic rule-based tagging (simple, not linguistically complete)
    det = {"the", "a", "an", "this", "that", "these", "those"}
    preps = {"in", "on", "at", "by", "for", "with", "about", "against", "between",
             "into", "through", "during", "before", "after", "above", "below",
             "to", "from", "up", "down", "over", "under"}
    conj = {"and", "or", "but", "so", "yet", "for", "nor"}
    pron = {"i", "you", "he", "she", "it", "we", "they", "me", "him", "her", "us",
            "them", "my", "your", "his", "her", "its", "our", "their"}
    counts = {}
    for w in tokens_no_last:
        lw = w.lower()
        if re.fullmatch(r"\d+([.,]\d+)?", w):
            tag = "CD"
        elif lw in det:
            tag = "DT"
        elif lw in preps:
            tag = "IN"
        elif lw in conj:
            tag = "CC"
        elif lw in pron:
            tag = "PRP"
        elif lw.endswith("ing"):
            tag = "VBG"
        elif lw.endswith("ed"):
            tag = "VBD"
        elif lw.endswith("ly"):
            tag = "RB"
        elif lw.endswith(("ous", "ful", "able", "ible", "al", "ive", "ic")):
            tag = "JJ"
        elif w and w[0].isupper():
            tag = "NNP"
        else:
            tag = "NN"
        counts[tag] = counts.get(tag, 0) + 1

    return counts
