def iqr_of_nested(L):
    """
    Compute the interquartile range (IQR = Q3 - Q1) of all numeric elements in a nested list L.
    Nested lists can be of arbitrary depth.
    Raises:
      ValueError: if no numeric elements are found.
      TypeError: if non-numeric (non-list) leaf values are present.
    Returns:
      float: Q3 - Q1
    """
    from numbers import Number

    # Flatten nested structure
    flat = []
    def _flatten(x):
        if isinstance(x, list) or isinstance(x, tuple):
            for item in x:
                _flatten(item)
        elif isinstance(x, Number):
            flat.append(float(x))
        else:
            raise TypeError(f"Unsupported leaf element type: {type(x)}")
    _flatten(L)

    if not flat:
        raise ValueError("No numeric elements in input")

    flat.sort()

    def median(arr):
        n = len(arr)
        if n == 0:
            raise ValueError("Cannot compute median of empty list")
        mid = n // 2
        if n % 2 == 1:
            return arr[mid]
        else:
            return 0.5 * (arr[mid - 1] + arr[mid])

    n = len(flat)
    if n % 2 == 0:
        lower = flat[:n//2]
        upper = flat[n//2:]
    else:
        lower = flat[:n//2]            # exclude median
        upper = flat[n//2 + 1:]        # exclude median

    q1 = median(lower)
    q3 = median(upper)
    return float(q3 - q1)

