import json
import csv
import statistics
import math
import numbers

def dict_stats_json_to_csv(json_path, csv_path, float_precision=None):
    """
    Read a JSON file containing a list of dictionaries, compute mean and median
    (ignoring non-numeric values and booleans) for each key, and write results
    to a CSV file with columns: key, mean, median.

    Parameters:
    - json_path: path to input JSON file. JSON must contain a top-level list of dicts.
    - csv_path: path to output CSV file.
    - float_precision: optional int. If provided, round mean and median to this many decimals.

    CSV output columns: key, mean, median
    Non-numeric or missing values are ignored when computing statistics. If a key
    has no numeric values, 'NaN' is written for mean and median.

    Example:
    dict_stats_json_to_csv("data.json", "stats.csv", float_precision=3)
    """
    def is_number(x):
        # Reject booleans even though they are instances of int
        if isinstance(x, bool):
            return False
        # Accept ints, floats, decimals, and numeric strings that can be converted
        if isinstance(x, numbers.Number):
            return True
        try:
            float(x)
            return True
        except (TypeError, ValueError):
            return False

    # Read JSON
    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if not isinstance(data, list):
        raise ValueError("Input JSON must be a list of dictionaries.")

    # Collect numeric values per key
    values_by_key = {}
    for idx, item in enumerate(data):
        if not isinstance(item, dict):
            # skip non-dicts in the list
            continue
        for k, v in item.items():
            if is_number(v):
                try:
                    num = float(v)
                except Exception:
                    continue
                values_by_key.setdefault(k, []).append(num)

    # Compute stats
    results = {}
    for k, vals in values_by_key.items():
        if not vals:
            mean_val = math.nan
            median_val = math.nan
        else:
            try:
                mean_val = statistics.mean(vals)
            except statistics.StatisticsError:
                mean_val = math.nan
            try:
                median_val = statistics.median(vals)
            except statistics.StatisticsError:
                median_val = math.nan

        # Optional rounding
        if float_precision is not None and not math.isnan(mean_val):
            mean_val = round(mean_val, float_precision)
        if float_precision is not None and not math.isnan(median_val):
            median_val = round(median_val, float_precision)

        results[k] = (mean_val, median_val)

    # Include keys that appeared but only with non-numeric values
    # (they won't be in values_by_key). Find all keys from dicts to ensure coverage.
    all_keys = set()
    for item in data:
        if isinstance(item, dict):
            all_keys.update(item.keys())
    for k in all_keys:
        if k not in results:
            results[k] = (math.nan, math.nan)

    # Write CSV
    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["key", "mean", "median"])
        for k in sorted(results.keys()):
            mean_val, median_val = results[k]
            # Represent NaN as the string "NaN" in the CSV
            def fmt(x):
                if x is None:
                    return ""
                if isinstance(x, float) and math.isnan(x):
                    return "NaN"
                return str(x)
            writer.writerow([k, fmt(mean_val), fmt(median_val)])

    # Return results dict for convenience (optional)
    return results
```

Notes and behavior:
- Non-numeric values and booleans are ignored when computing stats.
- Numeric strings like "3.5" are accepted and converted to floats.
- If a key has no numeric values, its mean and median are written as "NaN".
- The function returns a dictionary mapping key -> (mean, median) in addition to writing the CSV.
