    for k in all_keys:
        if k not in result:
            result[k] = {'mean': None, 'median': None, 'count': 0}

    # Write CSV
    # CSV columns: key, mean, median, count
    with open(output_csv_path, 'w', newline='', encoding='utf-8') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(['key', 'mean', 'median', 'count'])
        # sort keys for stable output
