    """
    Compute mean, sum, max, min and standard deviation for keys 'x', 'y', 'z'
    from list of dicts `d`.

    Returns a dict mapping each key to a dict of statistics:
      {
        'x': {'mean': ..., 'sum': ..., 'max': ..., 'min': ..., 'std': ...},
        'y': {...},
        'z': {...}
      }

    If no numeric values are found for a key, all statistics for that key are None
    except 'sum' which is 0.

    Uses population standard deviation (statistics.pstdev). Change to statistics.stdev
    if you prefer sample standard deviation.
    """
    import statistics
    from numbers import Number

    keys = ('x', 'y', 'z')
    result = {}

    for k in keys:
        vals = []
        for item in d:
            # ensure item is a dict and value is numeric
            if isinstance(item, dict) and k in item:
                v = item[k]
                if isinstance(v, Number):
                    vals.append(v)

        if not vals:
            result[k] = {'mean': None, 'sum': 0, 'max': None, 'min': None, 'std': None}
        else:
            result[k] = {
                'mean': statistics.mean(vals),
                'sum': sum(vals),
                'max': max(vals),
                'min': min(vals),
                'std': statistics.pstdev(vals)  # population std; use statistics.stdev for sample std
            }

    return result

