def dict_xyz_stats(d, keys=("x", "y", "z"), sample_std=False):
    """
    Compute sum, mean, max, min, and standard deviation for specified keys
    from a list of dictionaries `d`.

    Parameters:
    - d: list of dicts
    - keys: iterable of keys to compute stats for (default ("x","y","z"))
    - sample_std: if True compute sample standard deviation (statistics.stdev),
                  if False compute population standard deviation (statistics.pstdev).

    Returns:
    A dict mapping each key to a dict of stats:
      {
        "x": {"sum": ..., "mean": ..., "max": ..., "min": ..., "std": ...},
        "y": {...},
        "z": {...}
      }
    If no numeric values are found for a key, all stats for that key will be None.
    """
    import statistics

    def is_number(v):
        # Accept int/float but exclude bool (bool is a subclass of int)
        return isinstance(v, (int, float)) and not isinstance(v, bool)

    results = {}
    for key in keys:
        vals = [item[key] for item in d if key in item and is_number(item[key])]
        if not vals:
            results[key] = {"sum": None, "mean": None, "max": None, "min": None, "std": None}
            continue

        s = sum(vals)
        mean = s / len(vals)
        mx = max(vals)
        mn = min(vals)

        try:
            if sample_std:
                std = statistics.stdev(vals) if len(vals) >= 2 else None
            else:
                std = statistics.pstdev(vals)
        except Exception:
            std = None

        results[key] = {"sum": s, "mean": mean, "max": mx, "min": mn, "std": std}

    return results

