    class MinMaxScalerDict:
        def __init__(self):
            self.min_ = {}
            self.max_ = {}

        def fit(self, dicts, keys):
            for k in keys:
                vals = [d[k] for d in dicts]
                self.min_[k] = min(vals)
                self.max_[k] = max(vals)

        def transform(self, dicts, keys):
            out = []
            for d in dicts:
                nd = d.copy()
                for k in keys:
                    mn = self.min_[k]
                    mx = self.max_[k]
                    if mx == mn:
                        nd[k] = 0.0
                    else:
                        nd[k] = (d[k] - mn) / (mx - mn)
                out.append(nd)
            return out

        def fit_transform(self, dicts, keys):
            self.fit(dicts, keys)
            return self.transform(dicts, keys)

    keys = ['x', 'y', 'z']
    scaler = MinMaxScalerDict()
    scaled = scaler.fit_transform(data, keys)

