            # Assume mkc[k] returns a Counter-like mapping
            col = mkc[k]
            try:
                result[k] = dict(col)
            except Exception:
                # If it's not directly dict-convertible, build manually
                result[k] = {val: int(count) for val, count in getattr(col, "items", lambda: [])()}
        return result

    except Exception:
        # Fallback implementation (works reliably without external libraries)
        counters = {k: Counter() for k in keys}
        for item in d:
            if not isinstance(item, dict):
                # Accept mapping-like objects too
                try:
                    item = dict(item)
                except Exception:
                    continue
            for k in keys:
                if k in item:
                    v = item[k]
                    try:
                        counters[k][v] += 1
                    except TypeError:
                        # Unhashable value -> use its repr as the key
                        counters[k][repr(v)] += 1

        return {k: dict(counters[k]) for k in keys}


