Function:

def plot_sales_from_csv_dir(
    directory,
    filename_regex,
    month_col=None,
    sales_col=None,
    date_formats=None,
    recursive=False,
    show=True,
    save_path=None
):
    """
    Search a directory for CSV files matching filename_regex, read sales data, and plot sales vs month.

    Parameters:
    - directory (str): directory to search
    - filename_regex (str): regular expression to match CSV filenames (applied to basename)
    - month_col (str|None): explicit column name to use for month/date; if None the function will auto-detect common names
    - sales_col (str|None): explicit column name to use for sales; if None the function will auto-detect common names
    - date_formats (list[str]|None): list of strptime formats to try when parsing month/date values; if None a sensible default list is used
    - recursive (bool): if True search subdirectories recursively
    - show (bool): if True call plt.show() at the end
    - save_path (str|None): if provided, save the plot to this path

    The function prints warnings for files it cannot parse and skips them.
    """
    import os
    import re
    import csv
    import datetime
    import math

    try:
        import matplotlib.pyplot as plt
        import matplotlib.dates as mdates
    except Exception as e:
        raise RuntimeError("matplotlib is required to plot but could not be imported.") from e

    # default date formats to try
    if date_formats is None:
        date_formats = [
            "%Y-%m", "%Y-%m-%d", "%Y/%m", "%Y/%m/%d",
            "%b %Y", "%B %Y", "%m/%Y", "%m/%d/%Y",
            "%Y", "%b-%Y", "%B-%Y"
        ]

    # candidate column names (case-insensitive)
    month_candidates = ["month", "date", "period", "month_name", "month-year", "month_year"]
    sales_candidates = ["sales", "amount", "revenue", "value", "total"]

    # compile filename regex
    try:
        pattern = re.compile(filename_regex)
    except re.error as e:
        raise ValueError(f"Invalid filename_regex: {e}")

    # collect matching files
    matched_files = []
    if recursive:
        for root, _, files in os.walk(directory):
            for fname in files:
                if fname.lower().endswith(".csv") and pattern.search(fname):
                    matched_files.append(os.path.join(root, fname))
    else:
        for fname in os.listdir(directory):
            if fname.lower().endswith(".csv") and pattern.search(fname):
                matched_files.append(os.path.join(directory, fname))

    if not matched_files:
        raise FileNotFoundError(f"No CSV files matching pattern '{filename_regex}' found in '{directory}'.")

    plt.figure(figsize=(10, 6))
    ax = plt.gca()
    any_plots = False

    def choose_col(provided, headers, candidates):
        if provided:
            # try exact match or case-insensitive match
            if provided in headers:
                return provided
            for h in headers:
                if h.lower() == provided.lower():
                    return h
            raise KeyError(f"Requested column '{provided}' not found in CSV headers: {headers}")
        # auto-detect
        for cand in candidates:
            for h in headers:
                if h is None:
                    continue
                if h.lower() == cand.lower():
                    return h
        # try scanning for substring matches
        for cand in candidates:
            for h in headers:
                if h and cand.lower() in h.lower():
                    return h
        return None

    def try_parse_date(s):
        s2 = s.strip()
        # try each provided format
        for fmt in date_formats:
            try:
                return datetime.datetime.strptime(s2, fmt)
            except Exception:
                continue
        # try special cases: month name only (no year)
        try:
            d = datetime.datetime.strptime(s2, "%B")  # full month name
            return d.replace(year=1900)
        except Exception:
            pass
        try:
            d = datetime.datetime.strptime(s2, "%b")  # short month name
            return d.replace(year=1900)
        except Exception:
            pass
        # try numeric month like '3' or '03' or '2020-03' partially - already attempted many formats
        # fallback: None
        return None

    def parse_sales_value(s):
        if s is None:
            return None
        s2 = str(s).strip()
        if s2 == "":
            return None
        # remove currency symbols and thousands separators, keep minus and decimal point
        s_clean = re.sub(r"[^\d\.\-eE]", "", s2)
        # handle empty after cleaning
        if s_clean == "" or s_clean == "-" or s_clean == ".":
            return None
        try:
            return float(s_clean)
        except Exception:
            return None

    for filepath in matched_files:
        try:
            with open(filepath, newline="", encoding="utf-8") as fh:
                reader = csv.DictReader(fh)
                headers = reader.fieldnames or []
                if not headers:
                    print(f"Warning: file '{filepath}' has no headers; skipping.")
                    continue

                try:
                    mcol = choose_col(month_col, headers, month_candidates)
                except KeyError as e:
                    print(f"Warning: {e} Skipping file '{filepath}'.")
                    continue
                scol = choose_col(sales_col, headers, sales_candidates)
                if mcol is None or scol is None:
                    print(f"Warning: Could not find month or sales column in '{filepath}' (headers: {headers}); skipping.")
                    continue

                rows = []
                for row in reader:
                    raw_m = row.get(mcol)
                    raw_s = row.get(scol)
                    if raw_m is None or raw_s is None:
                        continue
                    s_val = parse_sales_value(raw_s)
                    if s_val is None or (isinstance(s_val, float) and (math.isinf(s_val) or math.isnan(s_val))):
                        continue
                    d = try_parse_date(str(raw_m))
                    rows.append((d, str(raw_m).strip(), s_val))

                if not rows:
                    print(f"Warning: no usable rows found in '{filepath}'; skipping.")
                    continue

                # If all rows have parsed dates, use datetime x-axis
                if all(r[0] is not None for r in rows):
                    rows.sort(key=lambda x: x[0])
                    dates = [r[0] for r in rows]
                    sales = [r[2] for r in rows]
                    xnums = mdates.date2num(dates)
                    ax.plot_date(xnums, sales, "-o", label=os.path.basename(filepath))
                    # configure date formatting
                    locator = mdates.AutoDateLocator()
                    formatter = mdates.ConciseDateFormatter(locator)
                    ax.xaxis.set_major_locator(locator)
                    ax.xaxis.set_major_formatter(formatter)
                else:
                    # fallback to categorical x-axis using original strings in order of appearance
                    labels = [r[1] for r in rows]
                    sales = [r[2] for r in rows]
                    indices = list(range(len(sales)))
                    ax.plot(indices, sales, "-o", label=os.path.basename(filepath))
                    ax.set_xticks(indices)
                    ax.set_xticklabels(labels, rotation=45, ha="right")

                any_plots = True

        except Exception as e:
            print(f"Warning: error processing '{filepath}': {e}. Skipping.")

    if not any_plots:
        raise RuntimeError("No valid data was plotted from the matched CSV files.")

    ax.set_xlabel("Month")
    ax.set_ylabel("Sales")
    ax.set_title("Sales by Month")
    ax.legend()
    plt.tight_layout()

    if save_path:
        plt.savefig(save_path, bbox_inches="tight")
    if show:
        plt.show()

