        Use '*' as a wildcard segment to iterate all items/values at that level.
        Examples: "a.b.*.value" or ["a","b","*","value"] or ["items", 0, "value"]
    - plot_type: one of "line", "bar", "hist", "scatter".
    - title: optional plot title.
    - figsize: matplotlib figure size.
    - save_path: if provided, the plot will be saved to this path (e.g., "out.png").
    - convert_numeric_strings: if True, strings that parse as floats will be converted.

    Returns:
    - List of numeric values extracted (floats/ints).

    Notes:
    - If you have jsonpath_viz installed and prefer to use it, replace the internal traversal code
      with an appropriate jsonpath_viz query and gather the matches, then continue with the plotting.
    """
    # Helper: parse path into segments
    def parse_path(path):
        if isinstance(path, (list, tuple)):
            return list(path)
        if not isinstance(path, str):
            raise ValueError("key_path must be a list or a dot-separated string")
        # Simple split on '.'; allow segments like 'items[0]' -> 'items', '0'
        raw_segments = path.split('.')
        segments = []
        for seg in raw_segments:
            while '[' in seg and ']' in seg:
                pre, rest = seg.split('[', 1)
                idx, after = rest.split(']', 1)
                if pre:
                    segments.append(pre)
                # try to parse index as int, else keep as string
                try:
                    segments.append(int(idx))
                except ValueError:
                    segments.append(idx)
                seg = after
            if seg != "":
                # if segment is digits only, treat as int
                if seg.isdigit():
                    segments.append(int(seg))
                else:
                    segments.append(seg)
        return segments

    # Recursive traversal generator
    def traverse(obj, segments: List[Union[str,int]]):
        if not segments:
            yield obj
            return
        seg = segments[0]
        rest = segments[1:]

        # wildcard: iterate over dict values and list elements
        if seg == "*":
            if isinstance(obj, dict):
                for v in obj.values():
                    yield from traverse(v, rest)
            elif isinstance(obj, list):
                for item in obj:
                    yield from traverse(item, rest)
            else:
                return
            return

        # integer index
        if isinstance(seg, int):
            if isinstance(obj, list):
                if 0 <= seg < len(obj):
                    yield from traverse(obj[seg], rest)
            elif isinstance(obj, dict):
                # if object is dict and index provided, try to access string key of index
                key = str(seg)
                if key in obj:
                    yield from traverse(obj[key], rest)
            return

        # string key
        if isinstance(obj, dict):
            if seg in obj:
                yield from traverse(obj[seg], rest)
            else:
                return
        elif isinstance(obj, list):
            # treat string key on list by attempting to get that key from each element (if dict)
            for item in obj:
                if isinstance(item, dict) and seg in item:
                    yield from traverse(item[seg], rest)
            return
        else:
            return

    # Extract raw values
    segments = parse_path(key_path)
    raw_matches = list(traverse(json_obj, segments))

    # Convert/filter numeric values
    def to_number(x):
        if isinstance(x, bool):
            return None  # exclude booleans
        if isinstance(x, numbers.Number):
            return x
        if convert_numeric_strings and isinstance(x, str):
            try:
                if '.' in x or 'e' in x.lower():
                    return float(x)
                else:
                    return int(x)
            except Exception:
                return None
        return None

    numeric_values = []
    for v in raw_matches:
        # If v is a list of numbers (common when the final segment returns nested list), flatten
        if isinstance(v, list):
            for vi in v:
                n = to_number(vi)
                if n is not None:
                    numeric_values.append(n)
        else:
            n = to_number(v)
            if n is not None:
                numeric_values.append(n)

    if not numeric_values:
        raise ValueError("No numeric values found for the given path.")

    # Plotting
    plt.figure(figsize=figsize)
    if title:
        plt.title(title)
    if plot_type == "line":
        plt.plot(range(len(numeric_values)), numeric_values, marker='o')
        plt.xlabel("index")
        plt.ylabel("value")
    elif plot_type == "bar":
        plt.bar(range(len(numeric_values)), numeric_values)
        plt.xlabel("index")
        plt.ylabel("value")
    elif plot_type == "hist":
        plt.hist(numeric_values, bins='auto')
        plt.xlabel("value")
        plt.ylabel("count")
    elif plot_type == "scatter":
        plt.scatter(range(len(numeric_values)), numeric_values)
        plt.xlabel("index")
        plt.ylabel("value")
    else:
        raise ValueError(f"Unsupported plot_type: {plot_type}. Choose from line, bar, hist, scatter.")

    plt.tight_layout()
    if save_path:
        plt.savefig(save_path)
        plt.close()
    else:
        plt.show()

    return numeric_values
