```python
def extract_and_visualize_numeric(
    json_data,
    key_path,
    kind='line',
    title=None,
    xlabel=None,
    ylabel=None,
    show=True,
    save_path=None
):
    """
    Extract numerical values from a JSON-like structure and visualize them.

    Parameters:
    - json_data: Python dict/list representing JSON data.
    - key_path:
        - If a list/tuple: interpreted as a sequence of keys to traverse (supports '*' as wildcard).
        - If a string:
            - If it looks like a JSONPath expression (contains '$', '*', '[', ']', '@', '..', '?') it will be
              evaluated with jsonpath-ng.
            - Otherwise it is treated as a dot-separated key path (e.g. "a.b.items.value") and supports '*' as a wildcard key.
    - kind: 'line', 'bar', or 'hist' (histogram).
    - title, xlabel, ylabel: plot labels (optional).
    - show: if True, calls plt.show().
    - save_path: if provided, saves figure to this path (PNG, PDF, etc. depending on extension).

    Returns:
    - dict with keys:
        - 'values': list of extracted numeric floats
        - 'fig': the matplotlib.figure.Figure object (or None if nothing plotted)
    """
    # Local imports to keep function self-contained and allow graceful error messages
    import numbers
    try:
        import matplotlib.pyplot as plt
    except Exception as e:
        raise RuntimeError("matplotlib is required for visualization. Install it with: pip install matplotlib") from e

    def try_number(x):
        if isinstance(x, numbers.Number):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except ValueError:
                return None
        return None

    # Helper: traverse by simple key path (list of keys). Supports '*' wildcard and numeric indices.
    def extract_by_key_list(data, keys):
        results = []

        def recurse(obj, idx):
            if idx == len(keys):
                results.append(obj)
                return
            key = keys[idx]
            # wildcard: iterate values if dict, items if list
            if key == '*':
                if isinstance(obj, dict):
                    for v in obj.values():
                        recurse(v, idx + 1)
                elif isinstance(obj, list):
                    for item in obj:
                        recurse(item, idx + 1)
                return

            # numeric index access if key is int or string representing int
            if isinstance(obj, list):
                # try interpret key as int index; if not, treat as map across elements
                try:
                    kidx = int(key)
                    if 0 <= kidx < len(obj):
                        recurse(obj[kidx], idx + 1)
                    return
                except Exception:
                    # apply same key to each element
                    for item in obj:
                        recurse(item, idx)
                    return

            if isinstance(obj, dict):
                if key in obj:
                    recurse(obj[key], idx + 1)
                # if not present, no result
                return

            # non-traversable object: nothing to do
            return

        recurse(data, 0)
        return results

    # Determine whether to use jsonpath-ng or simple traversal
    use_jsonpath = False
    jsonpath_expr = None
    if isinstance(key_path, (list, tuple)):
        keys = [str(k) for k in key_path]
    elif isinstance(key_path, str):
        # heuristics: if it contains JSONPath special characters, use jsonpath-ng
        special = any(ch in key_path for ch in ['$', '*', '[', ']', '@', '..', '?', '('])
        if special:
            use_jsonpath = True
            try:
                from jsonpath_ng import parse
            except Exception as e:
                raise RuntimeError("jsonpath-ng is required to evaluate JSONPath expressions. Install with: pip install jsonpath-ng") from e
            jsonpath_expr = parse(key_path)
            keys = None
        else:
            # treat as dot-separated keys
            keys = [p for p in key_path.split('.') if p != '']
    else:
        raise ValueError("key_path must be a list/tuple of keys or a string (dot-separated path or a JSONPath expression)")

    raw_matches = []
    if use_jsonpath:
        matches = jsonpath_expr.find(json_data)
        for m in matches:
            raw_matches.append(m.value)
    else:
        raw_matches = extract_by_key_list(json_data, keys)

    # Flatten nested iterables that are lists/tuples to try to collect numbers inside them too
    flattened = []
    def flatten_and_collect(x):
        if isinstance(x, (list, tuple)):
            for item in x:
                flatten_and_collect(item)
        else:
            flattened.append(x)
    for item in raw_matches:
        flatten_and_collect(item)

    # Convert to numeric values
    numeric_values = []
    for item in flattened:
        num = try_number(item)
        if num is not None:
            numeric_values.append(num)

    # Visualization
    fig = None
    if len(numeric_values) > 0:
        fig = plt.figure(figsize=(7, 4.5))
        ax = fig.add_subplot(1, 1, 1)
        if kind == 'hist':
            ax.hist(numeric_values, bins='auto', color='C0', alpha=0.7)
            if ylabel is None:
                ylabel = 'Frequency'
        elif kind == 'bar':
            x = list(range(len(numeric_values)))
            ax.bar(x, numeric_values, color='C1', alpha=0.8)
            if xlabel is None:
                xlabel = 'Index'
            if ylabel is None:
                ylabel = 'Value'
        else:  # default to line
            x = list(range(len(numeric_values)))
            ax.plot(x, numeric_values, marker='o', linestyle='-', color='C2')
            if xlabel is None:
                xlabel = 'Index'
            if ylabel is None:
                ylabel = 'Value'

        if title:
            ax.set_title(title)
        if xlabel:
            ax.set_xlabel(xlabel)
        if ylabel:
            ax.set_ylabel(ylabel)
        ax.grid(True, linestyle=':', alpha=0.4)

        if save_path:
            fig.tight_layout()
            try:
                fig.savefig(save_path)
            except Exception as e:
                # don't fail on save; notify user by raising a RuntimeError
                raise RuntimeError(f"Failed to save figure to {save_path}: {e}") from e

        if show:
            plt.show()
        else:
            plt.close(fig)  # close to avoid display in some environments
    else:
        # nothing numeric found; no figure
        fig = None

    return {'values': numeric_values, 'fig': fig}
```

