import json
import numbers
import warnings

def plot_normalized_json(json_str, key=None, title=None, output_path=None, show=True):
    """
    Parse a JSON string, extract numerical data, min-max normalize it, and plot a line chart.
    Tries to use the `json_line_plot` library if installed; otherwise falls back to matplotlib.

    Args:
        json_str (str): JSON content (list of numbers, list of objects, or dict containing a list).
        key (str, optional): If items are objects, the numeric field name to extract. If None,
                             the function will attempt to auto-detect a numeric field.
        title (str, optional): Title for the plot.
        output_path (str, optional): File path to save the plot (PNG). If None, won't save.
        show (bool, optional): Whether to display the plot (plt.show()).

    Returns:
        (normalized_list, used_key, saved_path): normalized_list is the list of floats in [0,1],
            used_key is the field used when extracting numbers from objects (or None),
            saved_path is output_path if saved else None.

    Raises:
        ValueError: If no numeric data can be extracted from the provided JSON.
    """
    # Parse JSON
    try:
        obj = json.loads(json_str)
    except Exception as e:
        raise ValueError(f"Invalid JSON string: {e}")

    # Extract list-like container
    items = None
    used_key = None
    if isinstance(obj, list):
        items = obj
    elif isinstance(obj, dict):
        if key is not None and key in obj and isinstance(obj[key], list):
            items = obj[key]
            used_key = key
        else:
            # If the dict has a single list value, use it
            list_vals = [v for v in obj.values() if isinstance(v, list)]
            if len(list_vals) == 1:
                items = list_vals[0]
            else:
                # If a key was provided but it wasn't the list itself, maybe dict maps to objects
                # e.g. {"data": [{"x":1}, ...]} -> use obj['data'] if present
                if key is not None and key in obj:
                    maybe = obj[key]
                    if isinstance(maybe, list):
                        items = maybe
                        used_key = key
                if items is None:
                    raise ValueError("JSON object must contain a single list or specify a key for the list.")
    else:
        raise ValueError("Top-level JSON must be a list or an object containing a list.")

    # If items are numbers
    numeric_values = []
    if all(isinstance(it, numbers.Number) for it in items):
        numeric_values = [float(it) for it in items]
        used_key = None
    else:
        # Expect a list of objects/dicts; determine which field to extract
        if not all(isinstance(it, dict) for it in items):
            # Mixed types: try to coerce numeric ones
            for it in items:
                if isinstance(it, numbers.Number):
                    numeric_values.append(float(it))
                elif isinstance(it, str):
                    try:
                        numeric_values.append(float(it))
                    except Exception:
                        continue
                # ignore other non-numeric entries
        else:
            # items are dicts
            # If key provided, use it
            if key:
                candidate_key = key
                vals = []
                for obj_item in items:
                    val = obj_item.get(candidate_key, None)
                    if isinstance(val, numbers.Number):
                        vals.append(float(val))
                    elif isinstance(val, str):
                        try:
                            vals.append(float(val))
                        except Exception:
                            vals.append(None)
                    else:
                        vals.append(None)
                # Filter out None
                numeric_values = [v for v in vals if v is not None]
                used_key = candidate_key
            else:
                # Auto-detect numeric field present in (most) objects
                # Collect field names and counts of numeric occurrences
                field_counts = {}
                field_values = {}
                for obj_item in items:
                    for k, v in obj_item.items():
                        if isinstance(v, numbers.Number):
                            field_counts[k] = field_counts.get(k, 0) + 1
                            field_values.setdefault(k, []).append(float(v))
                        else:
                            # try to coerce from string
                            if isinstance(v, str):
                                try:
                                    fv = float(v)
                                    field_counts[k] = field_counts.get(k, 0) + 1
                                    field_values.setdefault(k, []).append(fv)
                                except Exception:
                                    pass
                if not field_counts:
                    # No numeric fields found; try to extract any top-level numeric entries mixed earlier
                    for it in items:
                        if isinstance(it, numbers.Number):
                            numeric_values.append(float(it))
                        elif isinstance(it, str):
                            try:
                                numeric_values.append(float(it))
                            except Exception:
                                continue
                else:
                    # choose the field with the most numeric occurrences
                    candidate_key = max(field_counts.items(), key=lambda kv: kv[1])[0]
                    numeric_values = field_values.get(candidate_key, [])
                    used_key = candidate_key

    # Final check
    if not numeric_values:
        raise ValueError("No numeric data could be extracted from the JSON input.")

    # Min-max normalize
    minv = min(numeric_values)
    maxv = max(numeric_values)
    if maxv == minv:
