    except Exception as e:
        _log("BeautifulSoup not available or failed:", e)

    # 4) Final fallback: very simple HTML parser using html.parser
    try:
        from html.parser import HTMLParser

        _log("Parsing tables via html.parser fallback (simple parser)...")

        class SimpleTableParser(HTMLParser):
            def __init__(self):
                super().__init__()
                self.in_table = False
                self.in_tr = False
                self.in_td = False
                self.tables = []  # list of tables; each table is list of rows; each row is list of cells
                self.current_table = []
                self.current_row = []
                self.current_cell = []

            def handle_starttag(self, tag, attrs):
                tag = tag.lower()
                if tag == "table":
                    self.in_table = True
                    self.current_table = []
                elif tag == "tr" and self.in_table:
                    self.in_tr = True
                    self.current_row = []
                elif tag in ("td", "th") and self.in_tr:
                    self.in_td = True
                    self.current_cell = []

            def handle_endtag(self, tag):
                tag = tag.lower()
                if tag in ("td", "th") and self.in_td:
                    cell_text = "".join(self.current_cell).strip()
                    self.current_row.append(cell_text)
                    self.in_td = False
                elif tag == "tr" and self.in_tr:
                    # append row if not empty
                    if any(c != "" for c in self.current_row):
                        self.current_table.append(self.current_row)
                    self.in_tr = False
                elif tag == "table" and self.in_table:
                    self.tables.append(self.current_table)
                    self.in_table = False

            def handle_data(self, data):
                if self.in_td:
                    self.current_cell.append(data)

            def error(self, message):
                pass

        parser = SimpleTableParser()
        parser.feed(html)
        tables = parser.tables
        if not tables:
            return {"status": "error", "message": "No tables found by simple parser."}
        if table_index < 0 or table_index >= len(tables):
            return {"status": "error", "message": f"table_index {table_index} out of range (found {len(tables)} tables)."}
        tab = tables[table_index]
        if not tab:
            return {"status": "error", "message": "Selected table is empty."}
        header = tab[0]
        data_rows = tab[1:] if len(tab) > 1 else []
        if transform:
            try:
                processed = transform([header] + data_rows)
                if not processed or not isinstance(processed, (list, tuple)):
                    return {"status": "error", "message": "Transform must return a list-of-lists (first row header)."}
                header = processed[0]
                data_rows = processed[1:]
            except Exception as e_t:
                return {"status": "error", "message": f"Transform function failed: {e_t}"}
        final_table_name = table_name or f"table_{table_index}"
        conn = sqlite3.connect(db_path)
        cur = conn.cursor()
        if if_exists == "replace":
            cur.execute(f'DROP TABLE IF EXISTS "{final_table_name}"')
        # create columns as TEXT
        col_defs = ", ".join([f'"{c}" TEXT' for c in header])
        cur.execute(f'CREATE TABLE IF NOT EXISTS "{final_table_name}" ({col_defs})')
        placeholders = ",".join(["?"] * len(header))
        insert_sql = f'INSERT INTO "{final_table_name}" ({",".join([f\'"{c}"\' for c in header])}) VALUES ({placeholders})'
        prepared = []
        for r in data_rows:
            row = [str(x) if x is not None else "" for x in r] + [""] * max(0, len(header) - len(r))
            row = row[: len(header)]
            prepared.append(row)
        if prepared:
            cur.executemany(insert_sql, prepared)
            conn.commit()
        cur.execute(f'SELECT COUNT(*) FROM "{final_table_name}"')
        nrows = cur.fetchone()[0]
        conn.close()
        return {"status": "ok", "message": "Saved via simple html.parser fallback", "db_path": db_path, "table_name": final_table_name, "rows": nrows, "columns": len(header)}
    except Exception as e:
        return {"status": "error", "message": f"All parsing attempts failed: {e}"}
