def extract_text_with_fallback(image_path,
                               target_encoding='utf-8',
                               ocr_lang='eng',
                               as_bytes=False,
                               try_encodings=None,
                               verbose=False):
    """
    Open an image, attempt OCR to extract text, convert encoding (if requested),
    and if OCR fails or returns empty, fall back to image comment / metadata.

    Parameters:
    - image_path: path to image file
    - target_encoding: when as_bytes=True, encode the final text to this encoding
    - ocr_lang: language(s) for pytesseract (e.g. 'eng', 'eng+fra')
    - as_bytes: if True, return bytes encoded in target_encoding; otherwise return str
    - try_encodings: list of encodings to try when decoding bytes from metadata; if None a default list is used
    - verbose: if True print helpful debug messages

    Returns:
    - str (default) or bytes (if as_bytes=True)

    Raises:
    - ImportError with instructions if required libraries are missing
    - FileNotFoundError if image_path doesn't exist
    """

    # Imports and requirements checks
    try:
        from PIL import Image, JpegImagePlugin, PngImagePlugin, TiffImagePlugin, ExifTags
    except Exception as e:
        raise ImportError("Pillow is required. Install with: pip install pillow") from e

    try:
        import pytesseract
    except Exception as e:
        raise ImportError("pytesseract is required. Install with: pip install pytesseract. "
                          "Also install the Tesseract binary on your system.") from e

    import os

    if not os.path.isfile(image_path):
        raise FileNotFoundError(f"No such file: {image_path}")

    if try_encodings is None:
        try_encodings = ['utf-8', 'utf-16', 'utf-16le', 'utf-16be',
                         'latin-1', 'cp1252', 'iso-8859-1', 'utf-32']

    def debug(*args):
        if verbose:
            print("[debug]", *args)

    def decode_bytes_with_candidates(b):
        # b may include EXIF UserComment prefix (8 bytes specifying encoding)
        if isinstance(b, bytes):
            # EXIF UserComment special handling:
            # If it starts with ASCII\0\0\0 or UNICODE\0\0 etc, skip first 8 bytes and decode accordingly.
            if len(b) >= 8:
                prefix = b[:8]
                try:
                    if prefix.startswith(b'ASCII'):
                        debug("EXIF UserComment: ASCII prefix found")
                        try:
                            return b[8:].decode('ascii', errors='replace')
                        except Exception:
                            pass
                    elif prefix.startswith(b'UNICODE') or prefix.startswith(b'UTF8'):
                        # EXIF UNICODE usually means UTF-16
                        debug("EXIF UserComment: UNICODE prefix found; trying utf-16")
                        try:
                            return b[8:].decode('utf-16', errors='replace')
                        except Exception:
                            pass
                except Exception:
                    pass
            # Generic trial of encodings
            for enc in try_encodings:
                try:
                    return b.decode(enc)
                except Exception:
                    continue
            # Last resort: latin-1 fallback (preserves bytes)
            return b.decode('latin-1', errors='replace')
        elif isinstance(b, str):
            return b
        else:
            return str(b)

    def extract_comment_from_image(img):
        # Try a number of locations for comments/metadata
        # 1) PNG text chunks or PIL info
        info = getattr(img, "info", {}) or {}
        candidates = []

        # Common keys in info
        for key in ('comment', 'Comment', 'Description', 'description', 'text', 'Text'):
            if key in info and info[key]:
                candidates.append(info[key])

        # PNG tEXt and iTXt might be in info as dict entries
        # Also Pillow might store raw text entries at info.keys()
        for k, v in info.items():
            if isinstance(k, str) and k.lower() in ('comment', 'description', 'title', 'subject', 'keywords', 'author'):
                candidates.append(v)

        # 2) JPEG comment (PIL stores in info.get('comment') often)
        # 3) EXIF UserComment (tag 37510)
        try:
            exif = img.getexif()  # returns an Exif object, dict-like
            if exif:
                # Tag 37510 is UserComment
                USER_COMMENT_TAG = 37510
                if USER_COMMENT_TAG in exif:
                    candidates.append(exif[USER_COMMENT_TAG])
                # Try to fetch any other string-like EXIF tags
                for tag_id, value in exif.items():
                    # If value looks like a comment or string
                    if isinstance(value, (bytes, str)) and value:
                        candidates.append(value)
        except Exception as e:
            debug("No EXIF or unable to read EXIF:", e)

        # 4) Try JPEG APP markers (PIL JpegImagePlugin may store 'comment' in info)
        # 5) As a last resort, return None
        if not candidates:
            return None

        # Return the first candidate that decodes to non-empty
        for c in candidates:
            decoded = decode_bytes_with_candidates(c)
            if decoded and decoded.strip():
                return decoded
        return None

    # Open image
    with Image.open(image_path) as img:
        # Attempt OCR
        ocr_text = ""
        try:
            debug("Running OCR with pytesseract, lang=", ocr_lang)
            ocr_text = pytesseract.image_to_string(img, lang=ocr_lang)
            if ocr_text:
                debug("OCR produced text of length", len(ocr_text))
        except pytesseract.pytesseract.TesseractNotFoundError as e:
            debug("Tesseract binary not found:", e)
            ocr_text = ""
        except Exception as e:
            debug("OCR failed:", e)
            ocr_text = ""

        final_text = ""
        # If OCR gave useful text, use it; otherwise try comments
        if ocr_text and ocr_text.strip():
            final_text = ocr_text
        else:
            debug("OCR empty or failed, trying image comments/metadata")
            comment_text = extract_comment_from_image(img)
            if comment_text and comment_text.strip():
                final_text = comment_text
                debug("Found comment text of length", len(final_text))
            else:
                debug("No comment text found; returning empty string")
                final_text = ""

    # Final normalization: ensure str
    if isinstance(final_text, bytes):
        final_text = decode_bytes_with_candidates(final_text)
    else:
        # Ensure it's a str
        final_text = str(final_text)

    # Strip BOM if present
    if final_text.startswith('\ufeff'):
        final_text = final_text.lstrip('\ufeff')

    # Return according to as_bytes flag
    if as_bytes:
        try:
            return final_text.encode(target_encoding, errors='replace')
        except Exception as e:
            # If encoding fails, try utf-8 as fallback
            debug("Encoding to target failed:", e)
            return final_text.encode('utf-8', errors='replace')
    else:
        return final_text
