                    for k, v in info.items():
                        if isinstance(v, str):
                            txts.append(f"{k}:{v}")
                    if txts:
                        comment_text = "\n".join(txts)
            except Exception:
                pass

        # JPEG comment (Pillow may put it in info.get('comment') as bytes)
        if comment_text is None:
            try:
                info = img.info or {}
                if "comment" in info and info["comment"]:
                    comment_text = info["comment"]
            except Exception:
                pass

        if comment_text:
            vprint("Found comment metadata in image; using that instead of OCR.")
            raw_result = comment_text
        else:
            # No comment metadata found; attempt OCR using pytesseract
            vprint("No comment metadata found; attempting OCR with pytesseract.")
            try:
                import pytesseract
            except Exception as e:
                raise RuntimeError("pytesseract is required for OCR fallback but is not installed.") from e

            # Ensure image is in a mode pytesseract handles well
            try:
                img_for_ocr = img.convert("RGB")
            except Exception:
                img_for_ocr = img

            # Call pytesseract
            try:
                if ocr_lang:
                    raw_result = pytesseract.image_to_string(img_for_ocr, lang=ocr_lang)
                else:
                    raw_result = pytesseract.image_to_string(img_for_ocr)
            except Exception as e:
                raise RuntimeError(f"pytesseract OCR failed: {e}") from e

    # At this point, raw_result should be either a Python str or bytes
    # Normalize to a Python str by decoding bytes if necessary
    final_text = None
    used_src_encoding = None
    # Try to use a chardet-like detector if available and src_encoding == 'auto' and we have bytes
    def detect_encoding(b):
        try:
            import chardet
            det = chardet.detect(b)
            return det.get("encoding"), det
        except Exception:
            try:
                from charset_normalizer import from_bytes
                dets = from_bytes(b)
                if dets:
                    best = dets.best()
                    if best:
                        return best.encoding, {"confidence": best.percent_best}
                return None, None
            except Exception:
                return None, None

    if isinstance(raw_result, bytes):
        if src_encoding == "auto":
            enc, detinfo = detect_encoding(raw_result)
            if enc:
                used_src_encoding = enc
                try:
                    final_text = raw_result.decode(enc, errors="replace")
                except Exception:
                    final_text = raw_result.decode(enc, errors="replace")
            else:
                used_src_encoding = "utf-8 (fallback)"
                final_text = raw_result.decode("utf-8", errors="replace")
        else:
            used_src_encoding = src_encoding
            try:
                final_text = raw_result.decode(src_encoding, errors="replace")
            except Exception:
                final_text = raw_result.decode(src_encoding, errors="replace")
    else:
        # raw_result is str (unicode)
        final_text = raw_result
        used_src_encoding = "unicode (no decoding needed)"

    # Ensure final_text is a str
    if not isinstance(final_text, str):
        final_text = str(final_text)

    # Convert to destination encoding if caller wants bytes, otherwise return unicode str
    if return_bytes:
        try:
            out_bytes = final_text.encode(dst_encoding, errors="replace")
        except Exception as e:
            # If encoding fails, try utf-8 as a last resort
            warnings.warn(f"Encoding to {dst_encoding} failed; falling back to utf-8 with replacement. Error: {e}")
            out_bytes = final_text.encode("utf-8", errors="replace")
        vprint(f"Returning bytes encoded as {dst_encoding}. Backend used: {used_backend}. Source encoding info: {used_src_encoding}")
        return out_bytes
    else:
        vprint(f"Returning unicode string. Backend used: {used_backend}. Source encoding info: {used_src_encoding}")
        return final_text
