def extract_text_from_image(
    image_path,
    src_encoding=None,
    dest_encoding='utf-8',
    prefer_img_ocr_codec=True,
    fallback_to_comments=True,
    return_bytes=False,
    ocr_lang=None
):
    """
    Open an image file, extract text using OCR and convert text encoding,
    with a fallback to image comment/chunk processing.

    Parameters:
    - image_path: path to the image file (JPEG/PNG/...).
    - src_encoding: source encoding (str) or None/'auto' to auto-detect.
    - dest_encoding: the encoding for output bytes if return_bytes=True.
    - prefer_img_ocr_codec: try to use img_ocr_codec if installed.
    - fallback_to_comments: if OCR yields no text, try to extract image comments/text chunks.
    - return_bytes: if True, return bytes encoded with dest_encoding. If False, return Python str.
    - ocr_lang: language code for OCR (e.g. 'eng'); passed to pytesseract/easyocr if available.

    Returns:
    - If return_bytes=False: a Unicode Python str (possibly empty).
    - If return_bytes=True: bytes encoded using dest_encoding.

    Notes:
    - Optional dependencies that improve results: pillow (PIL), pytesseract or easyocr, chardet.
    - If you have img_ocr_codec installed, the function will try several likely callables from it.
    """

    import io
    import os
    import struct
    import zlib

    # Helper: try to import a module, return None if not available
    def try_import(name):
        try:
            return __import__(name)
        except Exception:
            return None

    chardet = try_import('chardet')
    PIL = try_import('PIL')
    if PIL:
        from PIL import Image

    # Helper: detect encoding of bytes
    def detect_encoding(b):
        if not b:
            return None
        if chardet:
            try:
                d = chardet.detect(b)
                return d.get('encoding')
            except Exception:
                return None
        return None

    # Helper: normalize to str from bytes/str
    def to_unicode(value, src_enc):
        if value is None:
            return ''
        if isinstance(value, str):
            return value
        if isinstance(value, bytes):
            enc = src_enc
            if not enc or enc == 'auto':
                enc = detect_encoding(value) or 'utf-8'
            try:
                return value.decode(enc, errors='replace')
            except Exception:
                return value.decode(enc, errors='replace')
        # fallback
        return str(value)

    # Try to use img_ocr_codec if available
    text = ''
    used_img_ocr_codec = False
    if prefer_img_ocr_codec:
        img_ocr_codec = try_import('img_ocr_codec')
        if img_ocr_codec:
            # Try a few likely function names/attributes
            tried = []
            result = None
            # function names to try (adjust if your actual library differs)
            candidates = [
                'ocr_image',
                'extract_text',
                'decode_image',
                'decode',
                'read_text',
                'read_image'
            ]
            for name in candidates:
                fn = getattr(img_ocr_codec, name, None)
                if callable(fn):
                    try:
                        # prefer passing path, but many APIs accept file-like or bytes
                        result = fn(image_path)
                        tried.append((name, 'called with path'))
                        break
                    except TypeError:
                        # try opening file and passing bytes/fileobj
                        try:
                            with open(image_path, 'rb') as f:
                                data = f.read()
                            result = fn(data)
                            tried.append((name, 'called with bytes'))
                            break
                        except Exception:
                            tried.append((name, 'failed with bytes'))
                    except Exception:
                        tried.append((name, 'raised'))
            # if result found, normalize
            if result is not None:
                used_img_ocr_codec = True
                if isinstance(result, bytes):
                    text = to_unicode(result, src_encoding)
                else:
                    # could be str or object with .text
                    if hasattr(result, 'text'):
                        text = to_unicode(getattr(result, 'text'), src_encoding)
                    else:
                        text = to_unicode(result, src_encoding)

    # If we don't have text yet or it's empty, try standard OCR fallbacks
    if not text:
        # 1) Try pytesseract + PIL
        pytesseract = try_import('pytesseract')
        if pytesseract and PIL:
            try:
                img = Image.open(image_path)
                # pytesseract expects language like 'eng' or None
                kwargs = {}
                if ocr_lang:
                    kwargs['lang'] = ocr_lang
                ocr_text = pytesseract.image_to_string(img, **kwargs)
                if ocr_text:
                    text = to_unicode(ocr_text, src_encoding)
                img.close()
            except Exception:
                # ignore and try next
                text = text or ''
        # 2) Try easyocr
        if not text:
            easyocr = try_import('easyocr')
            if easyocr:
                try:
                    # easyocr's Reader expects a list of languages
                    langs = [ocr_lang] if ocr_lang else ['en']
                    reader = easyocr.Reader(langs, gpu=False)  # gpu optional
                    results = reader.readtext(image_path, detail=0)
                    if results:
                        ocr_text = '\n'.join(results)
                        text = to_unicode(ocr_text, src_encoding)
                except Exception:
                    text = text or ''

    # If still no text and fallback_to_comments, try to extract comments/chunks from the image format
    if (not text) and fallback_to_comments:
        btext_parts = []

        # Read file bytes
        try:
            with open(image_path, 'rb') as f:
                data = f.read()
        except Exception:
            data = b''

        def extract_png_texts(data_bytes):
            out = []
            PNG_SIG = b'\x89PNG\r\n\x1a\n'
            if not data_bytes.startswith(PNG_SIG):
                return out
            offset = len(PNG_SIG)
            while offset + 8 <= len(data_bytes):
                # length (4), type (4)
                length = struct.unpack('>I', data_bytes[offset:offset+4])[0]
                ctype = data_bytes[offset+4:offset+8].decode('ascii', errors='ignore')
                offset += 8
                chunk_data = data_bytes[offset:offset+length]
                offset += length
                crc = data_bytes[offset:offset+4] if offset+4 <= len(data_bytes) else b''
                offset += 4
                if ctype == 'tEXt':
                    # format: keyword\x00text
                    try:
                        k, v = chunk_data.split(b'\x00', 1)
                        out.append(v)
                    except Exception:
                        out.append(chunk_data)
                elif ctype == 'iTXt':
                    # iTXt: keyword\0 compression_flag\0 compression_method\0 language_tag\0 translated_keyword\0 text
                    # We'll attempt to handle uncompressed and compressed cases simply
                    try:
                        parts = chunk_data.split(b'\x00', 5)
                        if len(parts) >= 6:
                            # parts[5] is text (maybe compressed)
                            compression_flag = parts[1]
                            text_bytes = parts[5]
                            if compression_flag == b'\x01':
                                try:
                                    text_bytes = zlib.decompress(text_bytes)
                                except Exception:
                                    pass
                            out.append(text_bytes)
                        else:
                            out.append(chunk_data)
                    except Exception:
                        out.append(chunk_data)
                elif ctype == 'zTXt':
                    # zTXt: keyword\0 compression_method(1)\x.. compressed_text
                    try:
                        k_and_rest = chunk_data.split(b'\x00', 1)
                        if len(k_and_rest) == 2:
                            rest = k_and_rest[1]
                            # first byte is compression method
                            if len(rest) >= 1:
                                comp_method = rest[0]
                                compressed = rest[1:]
                                try:
                                    text_bytes = zlib.decompress(compressed)
                                except Exception:
                                    text_bytes = compressed
                                out.append(text_bytes)
                            else:
                                out.append(rest)
                        else:
                            out.append(chunk_data)
                    except Exception:
                        out.append(chunk_data)
                # continue until IEND ideally
                if ctype == 'IEND':
                    break
            return out

        def extract_jpeg_comments(data_bytes):
            out = []
            if not data_bytes.startswith(b'\xff\xd8'):
                return out
            offset = 2
            length = len(data_bytes)
            while offset + 4 <= length:
                if data_bytes[offset] != 0xFF:
                    offset += 1
                    continue
                marker = data_bytes[offset+1]
                offset += 2
                # markers without length: 0xD0..0xD9, 0x01, etc. For simplicity handle common ones with length
                if marker == 0xD9 or marker == 0xDA:
                    break
                # read segment length
                if offset + 2 > length:
                    break
                seg_len = struct.unpack('>H', data_bytes[offset:offset+2])[0]
                offset += 2
                seg_data = data_bytes[offset:offset + seg_len - 2]
                # COM marker is 0xFE
                if marker == 0xFE:
                    out.append(seg_data)
                # APP1 Exif check - try to find UserComment if piexif present
                if marker == 0xE1:
                    # check for Exif header
                    if seg_data.startswith(b'Exif\x00\x00'):
                        try:
                            piexif = try_import('piexif')
                            if piexif:
                                exif_dict = piexif.load(b'Exif\x00\x00' + seg_data[6:])
                                # look for UserComment tag (37510) in Exif IFD (Exif)
                                user_comment = None
                                exif_ifd = exif_dict.get('Exif', {})
                                if 37510 in exif_ifd:
                                    user_comment = exif_ifd[37510]
                                if user_comment:
                                    if isinstance(user_comment, bytes):
                                        out.append(user_comment)
                                    else:
                                        out.append(str(user_comment).encode('utf-8', errors='replace'))
                        except Exception:
                            pass
                offset += seg_len - 2
            return out

        # PNG
        try:
            png_texts = extract_png_texts(data)
            for pb in png_texts:
                if isinstance(pb, str):
                    btext_parts.append(pb.encode('utf-8', errors='replace'))
                else:
                    btext_parts.append(pb)
        except Exception:
            pass

        # JPEG
        try:
            jpeg_texts = extract_jpeg_comments(data)
            for pb in jpeg_texts:
                if isinstance(pb, str):
                    btext_parts.append(pb.encode('utf-8', errors='replace'))
                else:
                    btext_parts.append(pb)
        except Exception:
            pass

        # If Pillow present, also check Image.info for 'comment' or textual keys
        if PIL:
            try:
                img = Image.open(image_path)
                info = img.info or {}
                # PIL might store 'comment' as bytes
                for k, v in info.items():
                    if k.lower() in ('comment', 'comments', 'text', 'description', 'caption'):
                        if isinstance(v, bytes):
                            btext_parts.append(v)
                        elif isinstance(v, str):
                            btext_parts.append(v.encode('utf-8', errors='replace'))
                # For PNG, some text stored in img.text (Pillow 9+)
                text_entries = {}
                try:
                    # Image.info may contain textual keys already
                    # Additionally, PNG has images.text or PngImagePlugin
                    text_entries = getattr(img, 'text', {}) or {}
                except Exception:
                    text_entries = {}
                for val in (text_entries.values() if isinstance(text_entries, dict) else []):
                    if isinstance(val, bytes):
                        btext_parts.append(val)
                    elif isinstance(val, str):
                        btext_parts.append(val.encode('utf-8', errors='replace'))
                img.close()
            except Exception:
                pass

        # Combine parts and decode
        combined_bytes = b'\n'.join(btext_parts) if btext_parts else b''
        if combined_bytes:
            text = to_unicode(combined_bytes, src_encoding)

    # Ensure text is at least empty string
    text = text or ''

    # Convert to destination encoding if requested
    if return_bytes:
        try:
            out_bytes = text.encode(dest_encoding, errors='replace')
        except Exception:
            out_bytes = text.encode('utf-8', errors='replace')
        return out_bytes
    else:
        return text

