    import github_repo_client  # type: ignore
    _HAS_GITHUB_REPO_CLIENT = True
except Exception:
    _HAS_GITHUB_REPO_CLIENT = False

import requests


def fetch_github_repo_info(
    repo_api_url: str,
    token: Optional[str] = None,
    issues_warning_threshold: int = 500,
    timeout: float = 10.0,
) -> Dict[str, Any]:
    """
    Fetch and return information about a GitHub repository using its API URL.

    Parameters:
    - repo_api_url: str
        Full GitHub repository API URL (e.g. "https://api.github.com/repos/owner/repo").
    - token: Optional[str]
        If provided, used as a Bearer token for Authorization to increase rate limits.
    - issues_warning_threshold: int
        If the repository has more open issues than this threshold, a warning is printed.
    - timeout: float
        Request timeout in seconds.

    Returns:
    - dict: Parsed JSON response from the GitHub API on success.

    Raises:
    - RuntimeError: For request/connection issues or when GitHub returns an error status.
    """
    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "fetch_github_repo_info/1.0",
    }
    if token:
        headers["Authorization"] = f"Bearer {token}"

    # Helper to interpret rate-limit headers
    def _rate_limit_info(hdrs: Dict[str, Any]) -> Dict[str, Any]:
        remaining = hdrs.get("X-RateLimit-Remaining")
        reset = hdrs.get("X-RateLimit-Reset")
        info = {}
        if remaining is not None:
            try:
                info["remaining"] = int(remaining)
            except Exception:
                info["remaining"] = remaining
        if reset is not None:
            try:
                reset_ts = int(reset)
                wait_seconds = max(0, reset_ts - int(time.time()))
                info["reset_unix"] = reset_ts
                info["wait_seconds"] = wait_seconds
            except Exception:
                info["reset"] = reset
        if "Retry-After" in hdrs:
            try:
                info["retry_after"] = int(hdrs["Retry-After"])
            except Exception:
                info["retry_after"] = hdrs["Retry-After"]
        return info

    # Try to use github_repo_client if available and exposes a GET-like method
    use_requests_fallback = False
    if _HAS_GITHUB_REPO_CLIENT:
        try:
            grc = github_repo_client
            # try typical method names; adapt if the library actually exposes different names
            if hasattr(grc, "get"):
                resp = grc.get(repo_api_url, headers=headers, timeout=timeout)  # type: ignore
            elif hasattr(grc, "request"):
                resp = grc.request("GET", repo_api_url, headers=headers, timeout=timeout)  # type: ignore
            else:
                # Unknown interface; fall back to requests
                use_requests_fallback = True

            if not use_requests_fallback:
                # Normalize the response: if it's a requests-like Response object, use its attributes.
                if hasattr(resp, "status_code") and hasattr(resp, "json"):
                    status_code = getattr(resp, "status_code")
                    resp_headers = getattr(resp, "headers", {})
                    try:
                        data = resp.json()
                    except Exception as e:
                        raise RuntimeError(f"Failed to parse JSON from github_repo_client response: {e}")
                elif isinstance(resp, dict):
                    status_code = 200
                    resp_headers = {}
                    data = resp
                else:
                    # Unexpected return type from github_repo_client; fall back to requests
                    use_requests_fallback = True
        except Exception:
            use_requests_fallback = True

    if use_requests_fallback or not _HAS_GITHUB_REPO_CLIENT:
        try:
            r = requests.get(repo_api_url, headers=headers, timeout=timeout)
        except requests.exceptions.RequestException as e:
            raise RuntimeError(f"Network error while requesting {repo_api_url}: {e}") from e

        status_code = r.status_code
        resp_headers = r.headers
        # Try to parse JSON even for error responses (GitHub supplies messages in JSON)
        try:
            data = r.json()
        except Exception:
            data = None

    # Handle HTTP errors and rate limiting
    if status_code == 403:
        rate_info = _rate_limit_info(resp_headers)
        # GitHub signals rate limiting with remaining=0 OR a 'rate limit exceeded' message
        msg = ""
        if data and isinstance(data, dict) and "message" in data:
            msg = data.get("message", "")
        if (rate_info.get("remaining") == 0) or ("rate limit" in msg.lower()) or ("API rate limit exceeded" in msg):
            # Rate limited
            wait_seconds = rate_info.get("wait_seconds")
            reset_unix = rate_info.get("reset_unix")
            details = {
                "error": "rate_limited",
                "message": msg or "API rate limit exceeded",
                "rate_info": rate_info,
                "status_code": status_code,
            }
            if wait_seconds is not None:
                raise RuntimeError(
                    f"GitHub API rate limit exceeded. Retry after ~{wait_seconds} seconds (reset at unix {reset_unix})."
                )
            else:
                raise RuntimeError(f"GitHub API rate limit exceeded. Details: {details}")
        else:
            # General 403
            raise RuntimeError(f"Access forbidden (403) when requesting {repo_api_url}. Message: {msg}")

    if 400 <= status_code < 600:
        # Other client/server errors
        err_msg = ""
        if data and isinstance(data, dict):
            err_msg = data.get("message") or str(data)
        raise RuntimeError(f"HTTP {status_code} error from GitHub API: {err_msg}")

    if not isinstance(data, dict):
        # Unexpected non-JSON response
        raise RuntimeError("Unexpected response format from GitHub API: expected JSON object.")

    # Check open issue count and warn if above threshold
    # Official repo endpoint typically has 'open_issues_count'
    open_issues = None
    if "open_issues_count" in data:
        try:
            open_issues = int(data.get("open_issues_count", 0))
        except Exception:
            open_issues = None
    elif "open_issues" in data:
        try:
            open_issues = int(data.get("open_issues", 0))
        except Exception:
            open_issues = None

    if open_issues is not None and open_issues > issues_warning_threshold:
        print(
            f"Warning: repository reports {open_issues} open issues which exceeds the threshold of {issues_warning_threshold}."
        )

    # Return the parsed JSON data
    return data
