import time
import datetime

def fetch_repo_info(repo_api_url, token=None, warn_issue_threshold=100, timeout=10):
    """
    Fetch information about a GitHub repository from its API URL.

    Parameters:
    - repo_api_url (str): Full GitHub API repo URL, e.g. "https://api.github.com/repos/owner/repo".
    - token (str|None): Personal access token (optional). If provided, will be used for Authorization.
    - warn_issue_threshold (int): If open issues exceed this, a warning will be printed.
    - timeout (float|int): Request timeout in seconds when falling back to requests.

    Returns:
    - dict: Parsed JSON response from the GitHub API (repository object) on success.
    - None: On error (HTTP error, rate limit, network error). Errors and warnings are printed.
    """
    # Try to use gh_repo_client if it's available in the environment.
    try:
        import gh_repo_client as gh  # may raise ImportError if not installed
    except Exception:
        gh = None

    # Helper to print rate-limit info from headers (if present)
    def _print_rate_limit_info(headers):
        remaining = headers.get('X-RateLimit-Remaining')
        reset = headers.get('X-RateLimit-Reset')
        limit = headers.get('X-RateLimit-Limit')
        parts = []
        if remaining is not None:
            parts.append(f"remaining={remaining}")
        if limit is not None:
            parts.append(f"limit={limit}")
        if reset is not None:
            try:
                reset_ts = int(reset)
                reset_time = datetime.datetime.fromtimestamp(reset_ts)
                parts.append(f"reset_at={reset_time.isoformat()}")
            except Exception:
                parts.append(f"reset={reset}")
        if parts:
            print("Rate limit info:", ", ".join(parts))

    # If gh_repo_client exists, attempt to use it.
    if gh is not None:
        try:
            # Try a few common API patterns for a client library.
            if hasattr(gh, "get_repository"):
                repo_data = gh.get_repository(repo_api_url, token=token)
            elif hasattr(gh, "get_repo"):
                repo_data = gh.get_repo(repo_api_url, token=token)
            elif hasattr(gh, "Client"):
                client = gh.Client(token=token) if token is not None else gh.Client()
                # try get_repository or repo methods on the client
                if hasattr(client, "get_repository"):
                    repo_data = client.get_repository(repo_api_url)
                elif hasattr(client, "get_repo"):
                    repo_data = client.get_repo(repo_api_url)
                else:
                    raise AttributeError("gh_repo_client.Client does not expose get_repository/get_repo")
            else:
                raise AttributeError("gh_repo_client has no recognized entrypoints (get_repository/get_repo/Client)")

            # Expect repo_data to be a dict-like object
            if not isinstance(repo_data, dict):
                # Attempt to convert common wrapper types to dict
                try:
                    repo_data = dict(repo_data)
                except Exception:
                    # If it's a model object, try to pull a few common attributes
                    fallback = {}
                    for key in ("full_name", "name", "description", "html_url", "stargazers_count",
                                "forks_count", "open_issues_count", "open_issues"):
                        if hasattr(repo_data, key):
                            fallback[key] = getattr(repo_data, key)
                    if fallback:
                        repo_data = fallback
                    else:
                        print("gh_repo_client returned an unexpected object; returning None.")
                        return None

        except Exception as e:
            # If gh_repo_client usage fails for any reason, fall back to requests approach below.
            print(f"gh_repo_client call failed: {e}. Falling back to requests.")
            gh = None  # force fallback

    # Fallback: use requests to call the GitHub API directly
    if gh is None:
        try:
            import requests
        except Exception as e:
            print("Neither gh_repo_client is available nor is 'requests' installable. Error:", str(e))
            return None

        headers = {
            "Accept": "application/vnd.github.v3+json",
            "User-Agent": "fetch_repo_info/1.0"
        }
        if token:
            headers["Authorization"] = f"token {token}"

        try:
            resp = requests.get(repo_api_url, headers=headers, timeout=timeout)
        except requests.exceptions.RequestException as e:
            print("Network/request error while contacting GitHub API:", str(e))
            return None

        # Handle rate limiting specifically
        if resp.status_code == 403:
            body_text = ""
            try:
                body_text = resp.text or ""
            except Exception:
                pass
            remaining = resp.headers.get("X-RateLimit-Remaining")
            if remaining == "0" or "rate limit exceeded" in body_text.lower():
                print("GitHub API rate limit exceeded.")
                _print_rate_limit_info(resp.headers)
                return None
            else:
                # 403 for other reasons (e.g., insufficient permissions)
                print(f"HTTP 403 Forbidden returned from GitHub API. Response: {resp.text}")
                _print_rate_limit_info(resp.headers)
                return None

        if resp.status_code >= 400:
            # Other HTTP errors
            print(f"HTTP error {resp.status_code} returned from GitHub API.")
            # Try to show a helpful snippet of JSON message if present
            try:
                err_json = resp.json()
                print("Error details:", err_json)
            except Exception:
                print("Response text:", resp.text[:1000])
            _print_rate_limit_info(resp.headers)
            return None

        try:
            repo_data = resp.json()
        except ValueError as e:
            print("Failed to parse JSON response from GitHub API:", str(e))
            return None

    # At this point repo_data should be a dict. Validate minimal content.
    if not isinstance(repo_data, dict):
        print("Unexpected repository data format; expected dict-like JSON.")
        return None

    # Check open issues threshold
    open_issues = repo_data.get("open_issues_count")
    # Some APIs might use 'open_issues'
    if open_issues is None:
        open_issues = repo_data.get("open_issues")

    try:
        if open_issues is not None:
            open_issues_int = int(open_issues)
            if open_issues_int > warn_issue_threshold:
                print(
                    f"Warning: repository reports {open_issues_int} open issues which exceeds the threshold of {warn_issue_threshold}."
                )
    except Exception:
        # If conversion fails, skip the threshold check
        pass

    # Return the repository JSON object so caller can inspect whatever fields they need
    return repo_data
