def fetch_sqlite_data(db_path, query):
    """
    Fetches data from an SQLite database at db_path using the provided SQL query.
    Returns a list of dicts (column name -> value).
    If more than 10000 rows are returned a warning "The data contains more than 10000 rows." is issued.

    Behavior:
    - If the module `sqlite_data_fetcher` is importable and exposes a `fetch(db_path, query)` function,
      that function will be used and its result returned (if it returns rows as tuples, they will be
      converted to list-of-dicts if column names are available).
    - Otherwise, falls back to the builtin sqlite3 module.
    """
    import warnings

    # Try to use sqlite_data_fetcher if available
    try:
        import sqlite_data_fetcher as sdf  # type: ignore
    except Exception:
        sdf = None

    # Helper to normalize rows -> list[dict]
    def _normalize_rows(cursor, rows):
        # If sqlite3.Cursor-like with .description
        col_names = None
        try:
            col_names = [col[0] for col in cursor.description]  # may raise
        except Exception:
            col_names = None

        normalized = []
        if col_names is not None:
            for r in rows:
                # r may be sqlite3.Row (mapping-like), tuple, or dict
                if isinstance(r, dict):
                    normalized.append(r)
                else:
                    try:
                        # try treat as mapping-like
                        normalized.append(dict(r))
                    except Exception:
                        # treat as sequence
                        normalized.append({col_names[i]: r[i] for i in range(min(len(col_names), len(r)))})
        else:
            # No column names available; return rows as-is (wrapped as dicts with numeric keys)
            for r in rows:
                try:
                    normalized.append(dict(r))
                except Exception:
                    normalized.append({i: v for i, v in enumerate(r)})
        return normalized

    # If sqlite_data_fetcher appears present, try to use a plausible API
    if sdf is not None:
        # If the library exposes a simple `fetch(db_path, query)` API, prefer it.
        fetch_fn = getattr(sdf, "fetch", None)
        if callable(fetch_fn):
            rows = fetch_fn(db_path, query)
            # Try to normalize return value:
            # If it's a sequence of dict-like objects, return as list(dict).
            # If it's a sequence of tuples, we need column names. If the library provides them, try to use them.
            try:
                # If the fetch function returns (rows, column_names) tuple, handle that
                if isinstance(rows, tuple) and len(rows) == 2 and isinstance(rows[1], (list, tuple)):
                    raw_rows, col_names = rows
                    normalized = []
                    for r in raw_rows:
                        if isinstance(r, dict):
                            normalized.append(r)
                        else:
                            normalized.append({col_names[i]: r[i] for i in range(min(len(col_names), len(r)))})
                    result = normalized
                else:
                    # If rows is list of dicts, ensure plain dicts
                    if rows and isinstance(rows[0], dict):
                        result = [dict(r) for r in rows]
                    else:
                        # We can't determine column names; return rows as list(dict) with index keys
                        result = []
                        for r in rows:
                            try:
                                result.append(dict(r))
                            except Exception:
                                result.append({i: v for i, v in enumerate(r)})
                if len(result) > 10000:
                    warnings.warn("The data contains more than 10000 rows.", UserWarning)
                return result
            except Exception:
                # Fall back to builtin sqlite3 below if result normalization fails
                pass

        # If fetch not present or normalization failed, try fallback to sqlite3
    # Fallback: use builtin sqlite3
    import sqlite3
    conn = sqlite3.connect(db_path)
    try:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        result = [dict(r) for r in rows]
        if len(result) > 10000:
            warnings.warn("The data contains more than 10000 rows.", UserWarning)
        return result
    finally:
        try:
            conn.close()
        except Exception:
            pass

