from datetime import datetime, timezone
from typing import List, Union

def avg_time_diff_seconds(timestamps: List[Union[str, int, float, datetime]],
                          tz_name: str = "UTC",
                          signed: bool = False) -> float:
    """
    Calculate the average time difference in seconds between each consecutive pair
    of timestamps in the given list after converting them to the specified timezone.

    Parameters:
    - timestamps: list of timestamps. Each item may be:
        - a datetime.datetime (naive or tz-aware),
        - an ISO-8601 string (e.g. "2021-03-27T12:34:56Z" or "2021-03-27T08:34:56-04:00"),
        - a numeric Unix epoch (int or float, seconds since epoch).
    - tz_name: timezone name (IANA), e.g. "UTC", "America/New_York". Default "UTC".
    - signed: if False (default) uses absolute intervals; if True uses signed differences
      (so negative intervals are possible if timestamps go backward).

    Returns:
    - average interval in seconds (float). If fewer than 2 timestamps, returns 0.0.

    Notes:
    - Naive datetimes or naive-parsed strings are interpreted as being in the target timezone.
    - Requires Python 3.9+ for zoneinfo; if not available, will try to use pytz if installed.
    - If a string is not ISO-8601, having python-dateutil installed improves parsing.
    """
    # Attempt to import ZoneInfo (Python 3.9+); otherwise fall back to pytz if available
    try:
        from zoneinfo import ZoneInfo  # type: ignore
        _use_zoneinfo = True
    except Exception:
        _use_zoneinfo = False
        try:
            import pytz  # type: ignore
        except Exception:
            raise RuntimeError("This function requires zoneinfo (Python 3.9+) or pytz installed.")

    # Optional: dateutil for more flexible parsing
    _dateutil_parser = None
    try:
        from dateutil import parser as _duparser  # type: ignore
        _dateutil_parser = _duparser
    except Exception:
        _dateutil_parser = None

    def _parse_one(x):
        # Returns a tz-aware datetime in the target timezone
        if isinstance(x, datetime):
            dt = x
        elif isinstance(x, (int, float)):
            # Interpret numeric as Unix epoch seconds (UTC)
            dt = datetime.fromtimestamp(float(x), tz=timezone.utc)
        elif isinstance(x, str):
            s = x.strip()
            # Handle trailing 'Z' (UTC)
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            # Try ISO parsing first
            try:
                dt = datetime.fromisoformat(s2)
            except Exception:
                # Try numeric string (epoch)
                try:
                    epoch = float(s)
                    dt = datetime.fromtimestamp(epoch, tz=timezone.utc)
                except Exception:
                    # Try dateutil if available
                    if _dateutil_parser is not None:
                        try:
                            # isoparse if available, fallback to parse
                            if hasattr(_dateutil_parser, "isoparse"):
                                dt = _dateutil_parser.isoparse(s)
                            else:
                                dt = _dateutil_parser.parse(s)
                        except Exception as e:
                            raise ValueError(f"Could not parse timestamp string: {s!r}") from e
                    else:
                        raise ValueError(
                            "Could not parse timestamp string and python-dateutil is not available: "
                            f"{s!r}"
                        )
        else:
            raise TypeError("Each timestamp must be datetime, str, int, or float.")

        # Make dt timezone-aware and convert/localize to target timezone
        if _use_zoneinfo:
            target_tz = ZoneInfo(tz_name)
            if dt.tzinfo is None:
                # Treat naive datetime as being in the target timezone
                dt = dt.replace(tzinfo=target_tz)
            else:
                dt = dt.astimezone(target_tz)
        else:
            # Using pytz
            import pytz  # local import
            target_tz = pytz.timezone(tz_name)
            if dt.tzinfo is None:
                dt = target_tz.localize(dt)
            else:
                dt = dt.astimezone(target_tz)

        return dt

    if not timestamps or len(timestamps) < 2:
        return 0.0

    # Parse all timestamps in order (do NOT sort; consecutive means in given order)
    parsed = [_parse_one(x) for x in timestamps]

    # Compute consecutive intervals in seconds
    intervals = []
    for i in range(1, len(parsed)):
        secs = (parsed[i] - parsed[i - 1]).total_seconds()
        if not signed:
            secs = abs(secs)
        intervals.append(secs)

    if not intervals:
        return 0.0

    return float(sum(intervals) / len(intervals))
