    - ValueError for unparseable strings.
    - RuntimeError if no timezone library available (zoneinfo or pytz).
    """
    if len(timestamps) < 2:
        return None

    if not _USE_ZONEINFO and pytz is None:
        raise RuntimeError("No timezone support available: install Python 3.9+ (zoneinfo) or the 'pytz' package.")

    def _parse_one(ts):
        # Accept datetime objects directly
        if isinstance(ts, datetime):
            dt = ts
        elif isinstance(ts, str):
            s = ts.strip()
            # Accept trailing 'Z' (UTC)
            if s.endswith('Z'):
                s = s[:-1] + '+00:00'
            try:
                dt = datetime.fromisoformat(s)
            except ValueError:
                raise ValueError(f"Timestamp string not ISO-8601 or unparseable: {ts!r}")
        else:
            raise TypeError("Each timestamp must be a datetime or ISO 8601 string")

        # If naive:
        if dt.tzinfo is None:
            if naive_assume_utc:
                dt = dt.replace(tzinfo=timezone.utc)
            else:
                # assume naive timestamps are in target_tz
                if _USE_ZONEINFO:
                    dt = dt.replace(tzinfo=ZoneInfo(target_tz))
                else:
                    # pytz localize
                    dt = pytz.timezone(target_tz).localize(dt)

        # Convert to target timezone
        if _USE_ZONEINFO:
            return dt.astimezone(ZoneInfo(target_tz))
        else:
            return dt.astimezone(pytz.timezone(target_tz))

    dts = [_parse_one(ts) for ts in timestamps]
    if sort:
        dts = sorted(dts)

    deltas = []
    for a, b in zip(dts, dts[1:]):
        # use absolute difference (duration)
        deltas.append(abs((b - a).total_seconds()))

    return sum(deltas) / len(deltas)
