from datetime import datetime, timezone

# Try to use zoneinfo (Python 3.9+); fallback to pytz if available
try:
    from zoneinfo import ZoneInfo  # type: ignore
    _ZONE_IMPL = "zoneinfo"
except Exception:
    try:
        import pytz  # type: ignore
        _ZONE_IMPL = "pytz"
    except Exception:
        _ZONE_IMPL = None


def _parse_iso_timestamp(ts):
    """
    Parse an ISO-8601 timestamp string to a datetime.
    If parsing fails and dateutil is available, use dateutil.parser.
    """
    if isinstance(ts, datetime):
        return ts
    if not isinstance(ts, str):
        raise TypeError(f"Timestamp must be a datetime or ISO-8601 string, got {type(ts)}")

    s = ts.strip()
    # Accept trailing 'Z' as UTC
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    try:
        return datetime.fromisoformat(s)
    except Exception:
        # Try dateutil if installed
        try:
            from dateutil import parser  # type: ignore
            # dateutil.parser.isoparse is stricter; parser.parse is more lenient
            return parser.isoparse(s)
        except Exception:
            raise ValueError(f"Could not parse timestamp string: {ts}")


def _ensure_aware(dt):
    """Return an aware datetime. If naive, assume UTC."""
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt


def _convert_to_tz(dt, tz_name):
    """
    Convert an aware datetime to the given timezone name.
    tz_name should be a string like 'UTC' or 'America/New_York'.
    """
    dt = _ensure_aware(dt)
    if _ZONE_IMPL == "zoneinfo":
        tz = ZoneInfo(tz_name)  # may raise if invalid
        return dt.astimezone(tz)
    elif _ZONE_IMPL == "pytz":
        import pytz  # local import to satisfy linting
        tz = pytz.timezone(tz_name)
        # astimezone works with pytz timezones when dt is aware
        return dt.astimezone(tz)
    else:
        raise RuntimeError("No timezone implementation available. Use Python 3.9+ (zoneinfo) or install pytz.")


def average_time_diff_seconds(timestamps, tz_name):
    """
    Calculate the average time difference in seconds between consecutive timestamps
    in the provided list after converting them to the specified timezone.

    Parameters:
    - timestamps: list of ISO-8601 strings or datetime objects
    - tz_name: timezone name string (e.g., 'UTC', 'America/New_York')

    Returns:
    - float: average of absolute differences in seconds between consecutive timestamps.
             Returns 0.0 if fewer than 2 timestamps are provided.

    Behavior and assumptions:
    - Naive datetimes (no tzinfo) are assumed to be UTC.
    - Differences are computed in the order of the list (no sorting), and absolute values
      are used so the average interval is non-negative.
    """
    if not isinstance(timestamps, (list, tuple)):
        raise TypeError("timestamps must be a list or tuple")

    if len(timestamps) < 2:
        return 0.0

    parsed = [_parse_iso_timestamp(t) for t in timestamps]
    converted = [_convert_to_tz(dt, tz_name) for dt in parsed]

    diffs = []
    for i in range(len(converted) - 1):
        delta = (converted[i + 1] - converted[i]).total_seconds()
        diffs.append(abs(delta))

    return sum(diffs) / len(diffs)


