def convert_and_plot_weights(data=None, figsize=(8, 6), save_path=None, show=True):
    """
    Convert string-formatted weights to floats (kilograms) and plot a scatter of weight vs height.

    Parameters:
    - data: dict (optional). Required keys:
        - 'Weight_String': list of weight strings (e.g. "70 kg", "154 lb", "11 st 3 lb", "70kg", "154lbs", "70")
        - 'Height': list of numeric heights (e.g. cm or m). Heights will be used as x-axis.
      If None, a default example dataset is used.
    - figsize: tuple for matplotlib figure size.
    - save_path: if provided, saves the plot to this path (file extension decides format).
    - show: if True (default), calls plt.show() to display the plot.

    Returns:
    - weights_kg: list of floats (weights converted to kilograms; NaN where conversion failed).
    - fig, ax: matplotlib figure and axes objects (useful for further customization).
    """
    import re
    import math
    import matplotlib.pyplot as plt

    # Default dataset if none provided
    if data is None:
        data = {
            'Weight_String': [
                "70 kg", "154 lb", "11 st 3 lb", "68kg", "180lbs", "72", "70.5 kg", "11stone", "200 pounds", "85,5 kg"
            ],
            # Example heights (could be cm or m; labels will indicate unknown units)
            'Height': [170, 180, 175, 169, 185, 172, 178, 176, 190, 165]
        }

    # Basic validation
    if not isinstance(data, dict):
        raise TypeError("data must be a dict with keys 'Weight_String' and 'Height'")

    if 'Weight_String' not in data or 'Height' not in data:
        raise KeyError("data must contain 'Weight_String' and 'Height' keys")

    weight_strings = data['Weight_String']
    heights = data['Height']

    if len(weight_strings) != len(heights):
        raise ValueError("Length of 'Weight_String' and 'Height' lists must be equal")

    # Helper: parse one weight string/number into kilograms (float)
    def parse_weight_to_kg(w):
        """
        Parse a weight expressed as a string or numeric to kilograms (float).
        Supported formats:
        - Numeric (int/float) -> assumed kilograms
        - "70 kg", "70kg" -> kilograms
        - "154 lb", "154lbs", "154 pounds" -> pounds -> converted to kg
        - "11 st 3 lb", "11stone 3lb", "11 st", etc. -> stones (+ optional pounds) -> converted
        - Comma decimal separators like "85,5 kg" supported
        Returns float (kg) or math.nan on failure.
        """
        if w is None:
            return math.nan

        # If it's already numeric
        if isinstance(w, (int, float)):
            return float(w)

        if not isinstance(w, str):
            # Attempt to coerce to string then parse
            try:
                w = str(w)
            except Exception:
                return math.nan

        s = w.strip().lower()
        s = s.replace(",", ".")  # support "85,5 kg"
        s = s.replace("\u00A0", " ")  # non-breaking space to normal space

        # Recognize stone patterns first (they may also include 'lb' or 'pound')
        # Look for 'st' or 'stone' present
        stone_match = re.search(r'(\d+(?:\.\d+)?)\s*(?:st|stone)\b', s)
        if stone_match:
            # stones value
            try:
                stones = float(stone_match.group(1))
            except:
                stones = 0.0
            # Look for pounds after stones
            pounds_match = re.search(r'(?:st|stone)[^\d]*?(\d+(?:\.\d+)?)\s*(?:lb|lbs|pound|pounds)\b', s)
            pounds = 0.0
            if pounds_match:
                try:
                    pounds = float(pounds_match.group(1))
                except:
                    pounds = 0.0
            # If there was pattern like "11 3" without lb but with two numbers and 'st' before, try to capture second number
            if not pounds_match:
                # find all numbers
                numbers = re.findall(r'(\d+(?:\.\d+)?)', s)
                if len(numbers) >= 2:
                    # If the first number equals stones capture and second may be pounds; ensure there is 'st' presence
                    # We already matched stones; take next number as pounds if there is a non-letter separation or explicit context
                    # This is a heuristic
                    try:
                        idx = numbers.index(stone_match.group(1))
                        if idx + 1 < len(numbers):
                            potential_pounds = numbers[idx + 1]
                            pounds = float(potential_pounds)
                    except Exception:
                        pass
            kg = stones * 6.35029318 + pounds * 0.45359237
            return float(kg)

        # If 'lb' or 'pound' in string -> interpret as pounds
        if re.search(r'\b(lb|lbs|pound|pounds)\b', s):
            # find the first numeric token
            num_match = re.search(r'(\d+(?:\.\d+)?)', s)
            if not num_match:
                return math.nan
            try:
                pounds = float(num_match.group(1))
            except:
                return math.nan
            kg = pounds * 0.45359237
            return float(kg)

        # If 'kg' in string -> interpret as kg
        if re.search(r'\bkg\b', s) or s.endswith('kg'):
            num_match = re.search(r'(\d+(?:\.\d+)?)', s)
            if not num_match:
                return math.nan
            try:
                kg = float(num_match.group(1))
                return float(kg)
            except:
                return math.nan

        # If nothing explicit, but there is a number, assume it's kilograms
        num_match = re.search(r'(\d+(?:\.\d+)?)', s)
        if num_match:
            try:
                return float(num_match.group(1))
            except:
                return math.nan

        # Unable to parse
        return math.nan

    # Convert all weights
    weights_kg = []
    for w in weight_strings:
        try:
            kg = parse_weight_to_kg(w)
            weights_kg.append(kg)
        except Exception:
            weights_kg.append(math.nan)

    # Convert heights to floats where possible
    heights_numeric = []
    for h in heights:
        if isinstance(h, (int, float)):
            heights_numeric.append(float(h))
            continue
        try:
            # handle commas as decimal separators
            if isinstance(h, str):
                v = h.strip().replace(",", ".")
            else:
                v = str(h)
            heights_numeric.append(float(v))
        except Exception:
            heights_numeric.append(math.nan)

    # Prepare plotting arrays, filtering out pairs where either is NaN
    paired = [(ht, wt) for ht, wt in zip(heights_numeric, weights_kg) if not (math.isnan(ht) or math.isnan(wt))]
    if len(paired) == 0:
        raise ValueError("No valid numeric pairs to plot after conversion.")

    xs = [p[0] for p in paired]  # heights
    ys = [p[1] for p in paired]  # weights (kg)

    # Create scatter plot
    fig, ax = plt.subplots(figsize=figsize)
    ax.scatter(xs, ys, color='tab:blue', alpha=0.7, edgecolors='k')

    ax.set_xlabel("Height (units as provided)")
    ax.set_ylabel("Weight (kg)")
    ax.set_title("Weight (kg) vs Height")
    ax.grid(True, linestyle='--', alpha=0.4)

    # Annotate points with original weight strings (optional, small labels)
    try:
        for (ht, wt), orig in zip(paired, [w for w, h in zip(weight_strings, heights_numeric) if not (math.isnan(h) or math.isnan(parse_weight_to_kg(w)))]):
            ax.annotate(str(orig), (ht, wt), textcoords="offset points", xytext=(4, 4), fontsize=8, alpha=0.75)
    except Exception:
        pass  # annotations are non-critical; ignore errors

    plt.tight_layout()

    if save_path:
        plt.savefig(save_path, dpi=300)

    if show:
        plt.show()

    return weights_kg, fig, ax
