import numpy as np

def pearson_score_grade_correlation(
    scores: Iterable[str],
    grades: Iterable[str],
    grade_order: Optional[List[str]] = None,
) -> float:
    """
    Compute the Pearson correlation coefficient between numerical scores and categorical grades.

    Parameters
    - scores: iterable of score values (strings are accepted, e.g. "85", "85.5", "85%", "1,234.5").
    - grades: iterable of categorical grade values (e.g. "A", "B+", "Excellent", "1st").
    - grade_order: optional list specifying grades from highest to lowest (rank order).
                   If provided, the first element is treated as the highest rank and mapped to the
                   largest numeric value. If not provided, the function will attempt to infer a
                   sensible ordering (see heuristics in code).

    Returns
    - Pearson correlation coefficient (float) between converted numeric scores and encoded grades.

    Raises
    - ValueError if arrays have different lengths or if fewer than 2 valid pairs remain after cleaning.
    """

    def _to_float_score(s):
        if s is None:
            return np.nan
        if isinstance(s, (int, float, np.number)):
            return float(s)
        s_str = str(s).strip()
        if s_str == "":
            return np.nan
        # Remove commas
        s_str = s_str.replace(",", "")
        # Handle percentages like "85%"
        if s_str.endswith("%"):
            try:
                return float(s_str[:-1])
            except ValueError:
                return np.nan
        # Try plain float conversion
        try:
            return float(s_str)
        except ValueError:
            # Try extracting first number in the string
            m = re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", s_str)
            if m:
                try:
                    return float(m.group(0))
                except ValueError:
                    return np.nan
            return np.nan

    # Convert inputs to lists
    scores_list = list(scores)
    grades_list = list(grades)
    if len(scores_list) != len(grades_list):
        raise ValueError("scores and grades must have the same length")

    # Convert scores
    scores_f = np.array([_to_float_score(s) for s in scores_list], dtype=float)

    # Encode grades
    unique_grades = []
    seen = set()
    for g in grades_list:
        key = None if g is None else str(g).strip()
        if key not in seen:
            seen.add(key)
            unique_grades.append(key)

    # Heuristics for grade ordering if not provided
    if grade_order is None:
        # Known letter-grade order (highest to lowest)
        LETTER_ORDER = [
            "A+", "A", "A-", "B+", "B", "B-", "C+", "C", "C-", "D+", "D", "D-", "F"
        ]
        # Normalize grades to strings for membership checks
        uniq_set = set(g for g in unique_grades if g is not None)
        if uniq_set and uniq_set.issubset(set(LETTER_ORDER)):
            # Use letter order intersection preserving order from LETTER_ORDER
            grade_order = [g for g in LETTER_ORDER if g in uniq_set]
        else:
            # If all grades look numeric (e.g., "1", "2", "3" or "1st", "2nd"), try numeric conversion
            def _grade_numeric_value(x):
                if x is None:
                    return None
                try:
                    return float(x)
                except Exception:
                    # Try to extract numeric part (e.g., "1st" -> 1)
                    m = re.search(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", x)
                    if m:
                        try:
                            return float(m.group(0))
                        except Exception:
                            return None
                    return None

            numeric_vals = {g: _grade_numeric_value(g) for g in uniq_set}
            if len(numeric_vals) > 0 and all(v is not None for v in numeric_vals.values()):
                # If convertable to numbers, order by numeric descending (higher number = higher rank)
                sorted_by_num = sorted(numeric_vals.items(), key=lambda kv: kv[1], reverse=True)
                grade_order = [kv[0] for kv in sorted_by_num]
            else:
                # Fallback: order unique grades by their first occurrence (preserve dataset order),
                # then assign higher numeric value to earlier-occurring category (assumes first is highest).
                # This is a heuristic; for reliable mapping provide grade_order explicitly.
                grade_order = [g for g in unique_grades if g is not None]

    # Build mapping from grade -> numeric encoded value (higher rank -> larger number)
    # If grade_order contains duplicates or doesn't include all observed grades, include missing ones at end
    seen_order = []
    for g in grade_order:
        if g not in seen_order:
            seen_order.append(g)
    for g in unique_grades:
        if g not in seen_order:
            seen_order.append(g)

    # Map top-ranked to largest numeric value (e.g., if 5 distinct grades: top->5, next->4, ...)
    n_levels = len(seen_order)
    mapping = {g: (n_levels - idx) for idx, g in enumerate(seen_order)}

    # Encode grades list, map None or unknown to np.nan
    encoded = []
    for g in grades_list:
        key = None if g is None else str(g).strip()
        if key in mapping:
            encoded.append(float(mapping[key]))
        else:
            encoded.append(np.nan)
    encoded = np.array(encoded, dtype=float)

    # Drop pairs where either scores_f or encoded is nan
    valid_mask = ~np.isnan(scores_f) & ~np.isnan(encoded)
    x = scores_f[valid_mask]
    y = encoded[valid_mask]

    if x.size < 2:
        raise ValueError("Fewer than 2 valid (score, grade) pairs available for correlation.")

    # Compute Pearson correlation using numpy
    # If either std is zero, correlation is undefined (return nan)
    x_mean = x.mean()
    y_mean = y.mean()
    x_dev = x - x_mean
    y_dev = y - y_mean
    denom = np.sqrt(np.sum(x_dev * x_dev) * np.sum(y_dev * y_dev))
    if denom == 0:
        return float("nan")
    corr = float(np.sum(x_dev * y_dev) / denom)

    return corr
```

