import re
import ast
import json
from html.parser import HTMLParser

# Use requests if installed, otherwise fall back to urllib
try:
    import requests
except Exception:
    requests = None
    from urllib.request import urlopen, Request
    from urllib.error import URLError, HTTPError

def _fetch_url_text(url, timeout=10, headers=None):
    headers = headers or {}
    if requests is not None:
        resp = requests.get(url, timeout=timeout, headers=headers)
        resp.raise_for_status()
        return resp.text
    else:
        req = Request(url, headers=headers or {})
        with urlopen(req, timeout=timeout) as res:
            return res.read().decode(res.headers.get_content_charset('utf-8') or 'utf-8')

class _ScriptExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.scripts = []
        self._in_script = False
        self._current = []

    def handle_starttag(self, tag, attrs):
        if tag.lower() == "script":
            self._in_script = True
            self._current = []

    def handle_endtag(self, tag):
        if tag.lower() == "script" and self._in_script:
            self.scripts.append("".join(self._current))
            self._in_script = False
            self._current = []

    def handle_data(self, data):
        if self._in_script:
            self._current.append(data)

def _find_top_level_brace_objects(s):
    """
    Return list of top-level {...} substrings found in s.
    It scans characters and collects balanced brace substrings at top level.
    """
    objs = []
    depth = 0
    start_idx = None
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == '{':
            if depth == 0:
                start_idx = i
            depth += 1
        elif ch == '}':
            if depth > 0:
                depth -= 1
                if depth == 0 and start_idx is not None:
                    objs.append(s[start_idx:i+1])
                    start_idx = None
        elif ch in ("'", '"'):
            # skip strings to avoid miscounting braces inside strings
            quote = ch
            i += 1
            while i < len(s):
                if s[i] == "\\":
                    i += 2
                    continue
                if s[i] == quote:
                    break
                i += 1
        i += 1
    return objs

def _remove_js_comments(s):
    # Remove /* ... */ and //... line comments (naive but effective for many cases)
    s = re.sub(r'/\*.*?\*/', '', s, flags=re.S)
    s = re.sub(r'//.*?(?=\n|$)', '', s)
    return s

def _remove_trailing_commas(s):
    # remove trailing commas before } or ]
    s = re.sub(r',\s*(?=[}\]])', '', s)
    return s

def _quote_unquoted_keys(s):
    # Add double quotes around unquoted object keys: { key: ... } -> { "key": ... }
    # Note: naive approach but works for common cases
    def repl(m):
        pre = m.group(1)
        key = m.group(2)
        post = m.group(3)
        return f'{pre}"{key}"{post}'
    pattern = re.compile(r'([{\s,])([A-Za-z_][A-Za-z0-9_-]*)(\s*:)')
    return pattern.sub(repl, s)

def _convert_single_to_double_quotes(s):
    # Replace single-quoted string literals with double-quoted ones.
    # This simple regex handles common cases but may fail on complex strings with escaped quotes.
    def unesc(m):
        inner = m.group(1)
        inner = inner.replace('"', '\\"')
        return f'"{inner}"'
    return re.sub(r"'([^'\\]*(?:\\.[^'\\]*)*)'", unesc, s)

def _normalize_js_object_to_json(s):
    s = _remove_js_comments(s)
    s = _remove_trailing_commas(s)
    s = _quote_unquoted_keys(s)
    s = _convert_single_to_double_quotes(s)
    return s

def fetch_and_parse_script_dicts(url, timeout=10, headers=None, max_candidates_per_script=20):
    """
    Fetches the webpage at `url`, extracts <script> tag contents, and tries to evaluate any
    brace-enclosed strings found in those scripts as Python dictionaries.

    Returns: (results, diagnostics)
      - results: list of dicts parsed successfully
      - diagnostics: list of dict entries of the form:
            {'script_index': int, 'candidate_index': int, 'candidate': str, 'status': 'ok'/'fail', 'reason': str}
    """
    text = _fetch_url_text(url, timeout=timeout, headers=headers)
    parser = _ScriptExtractor()
    parser.feed(text)
    results = []
    diagnostics = []
    for sidx, script in enumerate(parser.scripts):
        candidates = _find_top_level_brace_objects(script)
        # limit number of candidates per script to avoid pathological cases
        if len(candidates) > max_candidates_per_script:
            candidates = candidates[:max_candidates_per_script]
        for cidx, cand in enumerate(candidates):
            diag = {'script_index': sidx, 'candidate_index': cidx, 'candidate': cand[:200]}
            parsed = None
            # 1) Try ast.literal_eval directly (works if it's already Python-literal)
            try:
                val = ast.literal_eval(cand)
                if isinstance(val, dict):
                    parsed = val
                    diag.update({'status': 'ok', 'reason': 'ast.literal_eval'})
                else:
                    diag.update({'status': 'fail', 'reason': f'ast.literal_eval returned {type(val).__name__}'})
            except Exception:
                # try JSON-based parsing
                pass

            if parsed is None:
                try:
                    json_candidate = _normalize_js_object_to_json(cand)
                    val = json.loads(json_candidate)
                    if isinstance(val, dict):
                        parsed = val
                        diag.update({'status': 'ok', 'reason': 'json.loads (after normalization)'})
                    else:
                        diag.update({'status': 'fail', 'reason': f'json.loads returned {type(val).__name__}'})
                except Exception as e:
                    # store last exception message
                    if diag.get('status') != 'ok':
                        diag.update({'status': 'fail', 'reason': f'json parse error: {e}'})

            if parsed is not None:
                results.append(parsed)
            diagnostics.append(diag)
    return results, diagnostics

