def format_unix_timestamp(timestamp, timezone_str="UTC", fmt="%Y-%m-%d %H:%M:%S"):
    """
    Convert a Unix timestamp to a formatted date/time string in the specified timezone.

    Behavior:
    - Attempts to use an installed 'unix_timestamp_formatter' library if available.
      It checks for commonly named functions (format, format_timestamp, to_datetime_string)
      and tries to call them with arguments (timestamp, timezone=..., fmt=...).
      If that fails, it falls back to a local implementation using the standard library.
    - Accepts timestamp as int, float or numeric string.
    - Detects milliseconds vs seconds: if timestamp appears > 1e11 it's treated as milliseconds.
    - timezone_str should be an IANA timezone name like 'UTC', 'Europe/Berlin', 'America/New_York'.
      If zoneinfo is not available, it will try backports.zoneinfo. If timezone is invalid,
      a ValueError is raised.
    - fmt is a strftime format string.

    Returns:
    - formatted date/time string

    Examples:
    - format_unix_timestamp(1650000000, "UTC") -> '2022-04-15 05:20:00' (depending on fmt)
    - format_unix_timestamp(1650000000000, "America/Los_Angeles")  # milliseconds input
    """
    # Local imports to keep function self-contained
    import importlib

    # Try to use 'unix_timestamp_formatter' library if present
    try:
        utf = importlib.import_module("unix_timestamp_formatter")
        # Try a few plausible function names and call them if available.
        call_tried = False
        for fname in ("format", "format_timestamp", "to_datetime_string", "format_unix_timestamp"):
            if hasattr(utf, fname):
                func = getattr(utf, fname)
                # Try calling with common parameter names; if it fails, fallback to local implementation
                try:
                    # Try calling with named args first
                    return func(timestamp, timezone=timezone_str, fmt=fmt)
                except TypeError:
                    try:
                        return func(timestamp, timezone_str, fmt)
                    except TypeError:
                        try:
                            # Some libraries may expect seconds as float and format string named differently
                            return func(float(timestamp), timezone_str, fmt)
                        except Exception:
                            # If we can't call this function successfully, continue to next candidate
                            call_tried = True
                            continue
                except Exception:
                    # If function raised for other reasons, re-raise to inform user
                    raise
        # If module exists but none of the above worked, fall through to fallback implementation
    except ImportError:
        # Module not installed; we'll use fallback implementation below
        pass

    # Fallback implementation using datetime + zoneinfo/backports
    try:
        # Python 3.9+ zoneinfo
        from zoneinfo import ZoneInfo
    except Exception:
        # Try backports for older Pythons
        try:
            from backports.zoneinfo import ZoneInfo
        except Exception:
            ZoneInfo = None

    from datetime import datetime, timezone

    # Parse numeric timestamp
    if isinstance(timestamp, str):
        try:
            if "." in timestamp:
                ts = float(timestamp)
            else:
                ts = int(timestamp)
        except ValueError:
            raise ValueError("timestamp string must be numeric")
    elif isinstance(timestamp, (int, float)):
        ts = float(timestamp)
    else:
        raise TypeError("timestamp must be int, float, or numeric string")

    # Detect milliseconds (very large values)
    # Typical Unix seconds values around 1.7e9 in 2024; ms values ~ 1.7e12
    if abs(ts) > 1e11:
        ts = ts / 1000.0

    # Build aware datetime in requested timezone
    if timezone_str in (None, "", "UTC"):
        # Use UTC directly
        dt = datetime.fromtimestamp(ts, tz=timezone.utc)
        if timezone_str != "UTC" and ZoneInfo is not None:
            # If user passed "" or None, we already use UTC; otherwise when timezone_str=="UTC" it's fine
            pass
    else:
        if ZoneInfo is None:
            raise RuntimeError(
                "zoneinfo not available; install Python 3.9+ or 'backports.zoneinfo' to use timezones"
            )
        try:
            tz = ZoneInfo(timezone_str)
        except Exception as e:
            raise ValueError(f"Invalid timezone name: {timezone_str}") from e
        # Create aware datetime in that timezone
        # Use datetime.fromtimestamp with tz to get correct offset handling including DST
        dt = datetime.fromtimestamp(ts, tz=tz)

    try:
        return dt.strftime(fmt)
    except Exception as e:
        raise ValueError(f"Invalid format string: {fmt}") from e
