            # Read a reasonable amount (whole page is usually fine)
            raw = resp.read()
            # Try to get charset from headers; fallback to utf-8
            charset = None
            content_type = resp.headers.get('Content-Type', '')
            if 'charset=' in content_type:
                try:
                    charset = content_type.split('charset=')[-1].split(';')[0].strip()
                except Exception:
                    charset = None
            if not charset:
                # Python 3.11+: resp.headers.get_content_charset(); else None
                try:
                    charset = resp.headers.get_content_charset()  # may be None
                except Exception:
                    charset = None
            if not charset:
                charset = 'utf-8'

            try:
                html = raw.decode(charset, errors='replace')
            except Exception:
                html = raw.decode('utf-8', errors='replace')

    except urllib.error.HTTPError as e:
        return f"Failed to fetch URL: HTTP Error {e.code} - {e.reason}"
    except urllib.error.URLError as e:
        # e.reason may be a string or exception
        reason = getattr(e, 'reason', str(e))
        return f"Failed to fetch URL: {reason}"
    except Exception as e:
        return f"Failed to fetch URL: {e}"

    # parse title
    parser = _TitleParser()
    try:
        parser.feed(html)
    except Exception:
        # parsing error; continue to attempt to find <title> with regex as last resort
        pass

    title = parser.get_title()
    if not title:
        # last resort: regexp for <title>...</title>
        m_title = re.search(r'<title[^>]*>(.*?)</title>', html, re.IGNORECASE | re.DOTALL)
        if m_title:
            title = re.sub(r'\s+', ' ', m_title.group(1)).strip()

    if not title:
        return "Could not retrieve page title (no <title> tag found)."

    return title
