    Returns an error message string if no URL is found or fetch/parsing fails.

    Parameters:
      text (str): Input string that may contain a URL.
      timeout (int|float): Timeout in seconds for the HTTP request.

    Returns:
      str: Page title on success, or an error message starting with "Error:" on failure.

    Example:
      >>> get_page_title_from_text("Check this out: https://www.example.com/page.html")
      "Example Domain"
    """
    import re
    from html.parser import HTMLParser
    import urllib.request
    import urllib.error

    # 1) Extract first http(s) URL
    url_match = re.search(r'https?://[^\s\'"<>]+', text)
    if not url_match:
        return "Error: No valid URL found in input."
    url = url_match.group(0).rstrip('.,);:!?')  # strip common trailing punctuation

    # 2) Fetch the URL
    req = urllib.request.Request(
        url,
        headers={'User-Agent': 'Mozilla/5.0 (compatible; PageTitleFetcher/1.0)'}
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = getattr(resp, 'status', None)
            if status is not None and status >= 400:
                return f"Error: HTTP {status} when fetching URL."
            content_type = resp.getheader('Content-Type', '') or ''
            raw = resp.read()
    except urllib.error.HTTPError as e:
        return f"Error: HTTP {e.code} when fetching URL."
    except urllib.error.URLError as e:
        return f"Error: Failed to fetch URL: {e.reason}"
    except Exception as e:
        return f"Error: {e}"

    # 3) Decode bytes using charset from Content-Type if present, else try utf-8 then iso-8859-1
    m = re.search(r'charset=([^\s;]+)', content_type, re.IGNORECASE)
    if m:
        encoding = m.group(1).strip('"').strip("'")
        try:
            html = raw.decode(encoding, errors='replace')
        except Exception:
            html = raw.decode('utf-8', errors='replace')
    else:
        try:
            html = raw.decode('utf-8', errors='strict')
        except Exception:
            html = raw.decode('iso-8859-1', errors='replace')

    # 4) Parse out the <title> using HTMLParser
    class _TitleParser(HTMLParser):
        def __init__(self):
            super().__init__()
            self.in_title = False
            self.chunks = []

        def handle_starttag(self, tag, attrs):
            if tag.lower() == 'title':
                self.in_title = True

        def handle_endtag(self, tag):
            if tag.lower() == 'title':
                self.in_title = False

        def handle_data(self, data):
            if self.in_title:
                self.chunks.append(data)

        def get_title(self):
            return ''.join(self.chunks).strip()

    parser = _TitleParser()
    try:
        parser.feed(html)
    except Exception:
        # In case of badly-formed HTML, feed may raise; but we can continue
        pass
    title = parser.get_title()

    if not title:
        return "Error: Page has no title element or it is empty."
    return title

