from typing import List, Optional
import requests
from datetime import datetime

def get_repos_sorted_by_creation(username: str, token: Optional[str] = None) -> List[str]:
    """
    Retrieve repository names for the given GitHub username, sorted ascending by creation date.

    Args:
        username: GitHub username to query.
        token: Optional GitHub personal access token (string). If provided, used for Authorization to increase rate limits.

    Returns:
        A list of repository names (strings) sorted by creation date (oldest first).

    Raises:
        ValueError: If the user is not found (HTTP 404).
        RuntimeError: For other HTTP errors or unexpected responses.
    """
    headers = {"Accept": "application/vnd.github+json"}
    if token:
        headers["Authorization"] = f"token {token}"

    base_url = f"https://api.github.com/users/{username}/repos"
    params = {"per_page": 100, "page": 1}
    repos = []

    while True:
        resp = requests.get(base_url, headers=headers, params=params, timeout=10)
        if resp.status_code == 404:
            raise ValueError(f"GitHub user '{username}' not found (404).")
        if resp.status_code != 200:
            # Try to include message from the API if present
            try:
                err = resp.json()
                msg = err.get("message", "")
            except Exception:
                msg = resp.text
            raise RuntimeError(f"GitHub API error {resp.status_code}: {msg}")

        page_data = resp.json()
        if not isinstance(page_data, list):
            raise RuntimeError("Unexpected API response format; expected a list of repositories.")

        for r in page_data:
            # Defensive extraction; created_at should be present
            name = r.get("name")
            created_at = r.get("created_at")
            if name and created_at:
                repos.append((name, created_at))

        # Pagination: use the 'next' link if present
        if "next" in resp.links:
            params["page"] += 1
        else:
            break

    # Parse dates and sort; created_at strings are like "YYYY-MM-DDTHH:MM:SSZ"
    def parse_iso_z(ts: str) -> datetime:
        # Handle the 'Z' suffix explicitly
        if ts.endswith("Z"):
            return datetime.strptime(ts, "%Y-%m-%dT%H:%M:%SZ")
        # Attempt fromisoformat for other forms
        return datetime.fromisoformat(ts)

    repos.sort(key=lambda tup: parse_iso_z(tup[1]))
    return [name for name, _ in repos]


# Example usage:
if __name__ == "__main__":
    # Replace 'octocat' with the desired username and optionally provide a token
    try:
        names = get_repos_sorted_by_creation("octocat", token=None)
        for n in names:
            print(n)
    except Exception as e:
        print("Error:", e)
