    min_grade: int = 0,
    max_grade: int = 100,
    report_format: str = "dict"
) -> Any:
    """
    Create a grade report for a list of students across given subjects.

    - students: list of student names (strings).
    - subjects: list of subject names (strings).
    - seed: optional int to seed randomness for reproducibility.
    - min_grade, max_grade: range (inclusive) to generate integer grades.
    - report_format: "dict" (default) returns a nested dict,
                     "markdown" returns a markdown-formatted table string.

    Returned dict format (when report_format="dict"):
      {
        "students": {
          "<student_name>": {
            "grades": { "<subject>": int, ... },
            "average": float
          },
          ...
        },
        "subjects": ["subj1", "subj2", ...]
      }

    The function will try to import a 'grade_reporter' library and use it if present.
    If not present, a small local GradeReporter implementation is used instead.

    Example:
      create_grade_report(["Alice","Bob"], ["Math","History"], seed=42)
    """
    # Basic validation
    if not students:
        raise ValueError("students list must not be empty")
    if not subjects:
        raise ValueError("subjects list must not be empty")
    if min_grade > max_grade:
        raise ValueError("min_grade must be <= max_grade")
    if report_format not in ("dict", "markdown"):
        raise ValueError("report_format must be 'dict' or 'markdown'")

    # Attempt to import a (possibly non-existent) grade_reporter library.
    # If it's not available, define a small fallback implementation.
    try:
        import grade_reporter  # type: ignore
        # Assume grade_reporter provides a GradeReporter class with add_student and report methods.
        ReporterClass = getattr(grade_reporter, "GradeReporter", None)
        if ReporterClass is None:
            raise ImportError("grade_reporter module does not provide GradeReporter")
        use_external = True
    except Exception:
        use_external = False

    # Local fallback implementation
    class _LocalGradeReporter:
        def __init__(self, subjects):
            self.subjects = list(subjects)
            self._students = {}  # name -> grades dict

        def add_student(self, name: str, grades: Dict[str, int]):
            # Accepts grades dict keyed by subject names
            self._students[name] = dict(grades)

        def compute_averages(self) -> Dict[str, float]:
            avgs = {}
            for name, grades in self._students.items():
                if not self.subjects:
                    avgs[name] = 0.0
                else:
                    total = sum(grades.get(s, 0) for s in self.subjects)
                    avgs[name] = round(total / len(self.subjects), 2)
            return avgs

        def to_dict(self) -> Dict[str, Any]:
            avgs = self.compute_averages()
            students_out = {}
            for name, grades in self._students.items():
                students_out[name] = {
                    "grades": {s: grades.get(s, None) for s in self.subjects},
                    "average": avgs[name]
                }
            return {"students": students_out, "subjects": list(self.subjects)}

        def to_markdown(self) -> str:
            # Build a markdown table: Student | subj1 | subj2 | ... | Average
            header = ["Student"] + self.subjects + ["Average"]
            lines = [" | ".join(header), " | ".join("---" for _ in header)]
            d = self.to_dict()["students"]
            for name in sorted(d.keys()):
                row = [name] + [str(d[name]["grades"].get(s, "")) for s in self.subjects] + [str(d[name]["average"])]
                lines.append(" | ".join(row))
            return "\n".join(lines)

    # If external library exists and offers the expected interface, use it; otherwise use local.
    if use_external:
        # Example usage if external library provides similar API.
        Reporter = ReporterClass(subjects)
    else:
        Reporter = _LocalGradeReporter(subjects)

    rnd = random.Random(seed)

    # Generate grades for each student
    for student in students:
        grades = {}
        for subj in subjects:
            grades[subj] = rnd.randint(min_grade, max_grade)
        # Add student to reporter
        # Use duck-typing: call add_student if available, otherwise try alternative methods.
        if hasattr(Reporter, "add_student"):
            Reporter.add_student(student, grades)
        elif hasattr(Reporter, "add"):
            Reporter.add(student, grades)
        else:
            # as a last resort, set attribute (fallback reporter shouldn't hit this)
            setattr(Reporter, student, grades)

    # Produce output in requested format
    if report_format == "dict":
        if hasattr(Reporter, "to_dict"):
            return Reporter.to_dict()
        else:
            # Try to build the dict directly
